var storyContent = {"inkVersion":21,"root":[["\n","\n","\n","\n","\n","\n","\n","\n","\n",{"->":"night_0"},["done",{"#f":5,"#n":"g-0"}],null],"done",{"night_0":[{"->":".^.the_call"},{"the_call":[["^Tuesday. 11:47 PM.","\n","^The phone echoes through your apartment.","\n","^You've been with the Order of the Night for three years now. Long enough to know that when Silas Ward calls before midnight, it's not good. And when he calls after midnight, it's even worse.","\n","^This one is right on the line.","\n","ev","str","^Pick up the phone.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Let it ring a second longer, then pick up.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["\n",{"->":".^.^.g-0"},{"#f":5}],"c-1":["\n","ev",{"VAR?":"silas_trust"},1,"-",{"VAR=":"silas_trust","re":true},"/ev","^You let it ring three times. A small rebellion. Silas will notice it.","\n",{"->":".^.^.g-0"},{"#f":5}],"g-0":["^\"It's Ward.\" His voice is flat, curt, the way it always is. You've never heard the man laugh and you're not sure if he can. \"We have a situation. Get here now.\"","\n","^\"Now?\"","\n","^\"Now.\"","\n",{"->":"night_0.headquarters"},{"#f":5}]}],{"#f":1}],"headquarters":[["^For an ancient order, the headquarters is not impressive by any means. A rented office above a nail salon inside of a Las Vegas strip mall. Buzzing fluorescent lights. A coffee maker that's been brewing the same pot since before you were born. Maybe since before Silas was born.","\n","^Silas is standing at the end of a long table with an open folder. Paper. He doesn't trust anything digital. You see a map, two photographs, and a new cell phone still in its box.","\n","^He picks up one photograph and holds it up.","\n","^\"Mara Castillo. Do you know her?\"","\n",["ev",{"^->":"night_0.headquarters.0.8.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"We've met before, briefly.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_0.headquarters.0.9.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"I know the name.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_0.headquarters.0.10.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"She handled the Winslow case, right?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"night_0.headquarters.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.8.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.g-0"},{"#f":5}],"c-1":["ev",{"^->":"night_0.headquarters.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.9.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.g-0"},{"#f":5}],"c-2":["ev",{"^->":"night_0.headquarters.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.10.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.g-0"},{"#f":5}],"g-0":["^\"Three weeks ago, I sent Mara to investigate a location in Nevada. A year-round haunted attraction called The Hollows. It's built inside an old mine outside of a town called Veinrock. She went in undercover, hired as a scare actor.\"","\n","^He slides the other photograph across the table. It's a promotional shot of the entrance to The Hollows. A massive mine shaft mouth, lit in red, fog spilling out. The tagline reads: THE MOST TERRIFYING EXPERIENCE IN AMERICA. OPEN 365 NIGHTS A YEAR.","\n","^\"For the first ten days, she reported in regularly. Standard observations. Unnaturally large attraction. Extends deep underground. Some areas restricted to senior staff. Then her reports became... odd.\"","\n",["ev",{"^->":"night_0.headquarters.0.g-0.6.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-3","flg":18},{"s":["^\"Odd how?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_0.headquarters.0.g-0.7.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-4","flg":18},{"s":["^\"Define odd.\"",{"->":"$r","var":true},null]}],{"c-3":["ev",{"^->":"night_0.headquarters.0.g-0.c-3.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.6.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.^.g-1"},{"#f":5}],"c-4":["ev",{"^->":"night_0.headquarters.0.g-0.c-4.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.7.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.^.g-1"},{"#f":5}],"#f":5}],"g-1":["^\"She said the place felt wrong. Not haunted. She's handled hauntings. She said it felt... hungry.\"","\n",["ev",{"^->":"night_0.headquarters.0.g-1.2.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-5","flg":18},{"s":["^\"Hungry?\"",{"->":"$r","var":true},null]}],"ev","str","^Keep listening.","/str","/ev",{"*":".^.c-6","flg":20},{"c-5":["ev",{"^->":"night_0.headquarters.0.g-1.c-5.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.2.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.^.g-2"},{"#f":5}],"c-6":["\n",{"->":".^.^.^.g-2"},{"#f":5}],"#f":5}],"g-2":["^\"She described a persistent low-frequency hum in the lower tunnels. Guests experiencing terror disproportionate to the stimuli. And she mentioned a smell: ozone and copper coming from below the attraction level.\"","\n","^He pauses.","\n","^\"Her last report was twenty days ago. I've heard nothing since.\"","\n",["ev",{"^->":"night_0.headquarters.0.g-2.6.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-7","flg":18},{"s":["^\"Did you try to reach her?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_0.headquarters.0.g-2.7.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-8","flg":18},{"s":["^\"What did you do?\"",{"->":"$r","var":true},null]}],{"c-7":["ev",{"^->":"night_0.headquarters.0.g-2.c-7.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.6.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.^.g-3"},{"#f":5}],"c-8":["ev",{"^->":"night_0.headquarters.0.g-2.c-8.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.7.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.^.g-3"},{"#f":5}],"#f":5}],"g-3":["^\"I called The Hollows directly. Asked for Mara. They said no one by that name works there. I gave them her description. Nothing. I asked about recent hires in the past month. They told me there's nothing else they could help me with.\"","\n","^The facts settle in the air.","\n","^\"Mara Castillo worked there for ten days. She reported to me from inside. And now they are saying she never existed.\"","\n",{"->":"night_0.headquarters_answers"},{"#f":5}]}],{"#f":1}],"headquarters_answers":[[["ev",{"^->":"night_0.headquarters_answers.0.0.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str",{"CNT?":"night_0.headquarters_cover_name"},"!","/ev",{"*":".^.^.c-0","flg":19},{"s":["^\"Could she have used a cover name?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_0.headquarters_answers.0.1.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","str","^\"","/str",{"CNT?":"night_0.headquarters_record"},"!","/ev",{"*":".^.^.c-1","flg":23},{"s":["^\"That's not possible.",{"->":"$r","var":true},null]}],"ev","str","^Wait for him to continue.","/str",{"CNT?":".^.^.^.headquarters_wait"},"!","/ev",{"*":".^.c-2","flg":21},{"c-0":["ev",{"^->":"night_0.headquarters_answers.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.0.s"},[{"#n":"$r2"}],"\n",{"->":"night_0.headquarters_cover_name"},{"#f":5}],"c-1":["ev",{"^->":"night_0.headquarters_answers.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.1.s"},[{"#n":"$r2"}],"^ There has to be a record.\"","\n",{"->":"night_0.headquarters_record"},{"#f":5}],"c-2":["^ You wait.","\n",{"->":"night_0.headquarters_wait"},{"#f":5}]}],{"#f":1}],"headquarters_cover_name":["^\"She did. I assigned one to her, 'Elena Voss.' No record of that name.\"","\n",{"->":".^.^.headquarters_answers"},{"#f":1}],"headquarters_record":["^\"That's what I thought. But I assigned our digital forensics team to look remotely at the employee databases. No payroll records. We checked the security footage but the cameras recycle every 2 days. Convenient.\"","\n",{"->":".^.^.headquarters_answers"},{"#f":1}],"headquarters_wait":[["^Silas is unusually quiet. He always has an answer, even if it's \"insufficient data.\"","\n",["^\"I think something there is capable of making people disappear. But I don't know how.\"","\n",{"->":"night_0.the_assignment"},{"#f":5,"#n":"g-0"}],null],{"#f":1}],"the_assignment":["^\"Here's what we do know.\"","\n","^He beckons you over next to him and points to the map. It's a topographic survey of the area around Veinrock, Nevada.","\n","^\"Veinrock was a silver mining town. In 1973, a sinkhole collapsed the main shaft of the Aldrich Silver Mine. Forty-eight miners were killed. The remaining residents emptied out within a year. It became a ghost town for twenty-five years.\"","\n","^His finger thuds on the map.","\n","^\"In 1998, a company called HorrorCo Entertainment purchased the mine and the surrounding property. Built a haunted attraction inside of the tunnels. Named it The Hollows. And they've been operating year-round ever since.\"","\n",{"->":".^.^.the_assignment_questions"},{"#f":1}],"the_assignment_questions":[[["ev",{"^->":"night_0.the_assignment_questions.0.0.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","str","^\"","/str",{"CNT?":"night_0.the_year_round"},"!","/ev",{"*":".^.^.c-0","flg":23},{"s":["^\"Year round?",{"->":"$r","var":true},null]}],["ev",{"^->":"night_0.the_assignment_questions.0.1.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str",{"CNT?":"night_0.the_horrorco"},"!","/ev",{"*":".^.^.c-1","flg":19},{"s":["^\"What do we know about HorrorCo?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_0.the_assignment_questions.0.2.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str",{"CNT?":"night_0.the_flagged"},"!","/ev",{"*":".^.^.c-2","flg":19},{"s":["^\"Why did the Order flag this location?\"",{"->":"$r","var":true},null]}],"ev","str","^Nod.","/str","/ev",{"*":".^.c-3","flg":20},{"c-0":["ev",{"^->":"night_0.the_assignment_questions.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.0.s"},[{"#n":"$r2"}],"^ That's unusual for a haunt.\"","\n",{"->":"night_0.the_year_round"},{"#f":5}],"c-1":["ev",{"^->":"night_0.the_assignment_questions.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.1.s"},[{"#n":"$r2"}],"\n",{"->":"night_0.the_horrorco"},{"#f":5}],"c-2":["ev",{"^->":"night_0.the_assignment_questions.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.2.s"},[{"#n":"$r2"}],"\n",{"->":"night_0.the_flagged"},{"#f":5}],"c-3":["\n",{"->":"night_0.the_ask"},{"#f":5}]}],{"#f":1}],"the_year_round":["^\"Yes. Most haunted attractions are seasonal. Halloween. Maybe a few weekends in the fall. The Hollows runs every single night. And it's not lacking for business. Visitors come from across the country. There's a waitlist.\"","\n",{"->":".^.^.the_assignment_questions"},{"#f":1}],"the_horrorco":["^\"Almost nothing. They're incorporated in Delaware. Shell company structure. No public-facing leadership. No press interviews. No social media presence except for marketing. For a company running the most popular haunted attraction in the country, they are remarkably invisible.\"","\n",{"->":".^.^.the_assignment_questions"},{"#f":1}],"the_flagged":["^\"Disappearances. Over the past three years, at least eight people connected to The Hollows have vanished. Guests, employees, a local contractor. Local police investigated and found nothing. All cold cases, closed. The pattern caught our attention.\"","\n",{"->":".^.^.the_assignment_questions"},{"#f":1}],"the_ask":[["^Silas gestures at the boxed phone.","\n","^\"Burner. Encrypted line. My number is the only contact. Report in every twenty-four hours. If I don't hear from you in forty-eight, I'm sending a team.\"","\n","^He pauses.","\n","^\"Your cover is already set up. You've applied for a scare actor position at The Hollows under the name 'Val Rowan.' You start orientation tomorrow. Drive out tonight.\"","\n","^He organizes the files back into the folder. His gaze rises to meet you directly. You're used to concern in his expression, but this is severe.","\n","^\"I need to know what happened to Mara. And I need to know what's inside of that mine. But I want to be clear about priorities.\"","\n",["ev",{"^->":"night_0.the_ask.0.12.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"Finding Mara is the priority.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_0.the_ask.0.13.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Understanding the threat is the priority.\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"night_0.the_ask.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.12.s"},[{"#n":"$r2"}],"\n","ev","str","^find_mara","/str","/ev",{"VAR=":"priority","re":true},"^Silas nods slowly.","\n","^\"Agreed. Whatever is happening at The Hollows, we have an agent unaccounted for. Find her first. The investigation is secondary.\"","\n",{"->":"night_0.the_drive"},{"#f":5}],"c-1":["ev",{"^->":"night_0.the_ask.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.13.s"},[{"#n":"$r2"}],"\n","ev","str","^investigate_paranormal","/str","/ev",{"VAR=":"priority","re":true},"ev",{"VAR?":"silas_trust"},1,"+",{"VAR=":"silas_trust","re":true},"/ev","^Silas nods.","\n","^\"The Order's mission is to identify and contain threats. Mara knew the risks. If we understand what we're dealing with, we're better positioned to help her and anyone else.\"","\n",{"->":"night_0.before_the_drive"},{"#f":5}]}],{"#f":1}],"before_the_drive":[["ev","str","^\"I understand.\"","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"night_0.the_drive"},{"#f":5}]}],{"#f":1}],"the_drive":[["^1 AM.","\n","^The drive is six hours through the empty Nevada desert highway. Your headlights cut a tunnel through the dark and reflect the occasional pair of animal eyes from the shoulder of the road.","\n","^You think about Mara. You met her once, at an Order debrief in Denver. She was sharp, careful, the kind of person who checked exits when she walked into a room. Not the kind of person who disappears.","\n","^Around 4 AM, you pass a sign: VEINROCK - 43 MILES.","\n","^Around 5 AM, you pass another: THE HOLLOWS - OPEN EVERY NIGHT - YOU WON'T SURVIVE.","\n","^Around 6 AM, just as the sky is turning grey, you see it.","\n","^Veinrock.","\n","ev","str","^Drive through","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"night_0.veinrock"},{"#f":5}]}],{"#f":1}],"veinrock":["^A cluster of low buildings along a single main road. A gas station. A motel called THE MINESHAFT INN with a half-lit neon sign. A diner. A gift shop. The town is smaller than you expected.","\n","^The end of the road leads to the base of a low mountain. Even from here, in the grey early morning, you see the arch of the mine entrance. Massive, industrial, hung with arrays of unlit lights and speakers. A banner across the top reads THE HOLLOWS in dripping red letters.","\n","^It's closed. It's quiet. The parking lot is empty.","\n","^But you feel it.","\n","^Something underground. A hum you feel in your chest instead of hearing in your ears. A warmth in the air that doesn't match the rising desert dawn.","\n","^You pull into the Mineshaft Inn. The motel owner, half-asleep and disinterested, hands you a key. Room 6.","\n","^You set your bag down and plug in the burner phone. You draw the shades shut across the window facing the mine entrance at the end of town.","\n","^Orientation is at 2 PM.","\n","^You have eight hours.","\n",{"->":".^.^.veinrock_hub"},{"#f":1}],"veinrock_hub":[["ev","str","^Try to sleep.","/str",{"CNT?":".^.^.^.veinrock_sleep"},"!","/ev",{"*":".^.c-0","flg":21},"ev","str","^Explore the town.","/str",{"CNT?":".^.^.^.veinrock_explore"},"!","/ev",{"*":".^.c-1","flg":21},"ev","str","^Call Silas and confirm you've arrived.","/str",{"CNT?":".^.^.^.veinrock_silas"},"!","/ev",{"*":".^.c-2","flg":21},"ev","str","^Head to orientation.","/str",{"CNT?":".^.^.^.veinrock_sleep"},{"CNT?":".^.^.^.veinrock_explore"},"||",{"CNT?":".^.^.^.veinrock_silas"},"||","/ev",{"*":".^.c-3","flg":21},{"c-0":["\n",{"->":"night_0.veinrock_sleep"},{"#f":5}],"c-1":["\n",{"->":"night_0.veinrock_explore"},{"#f":5}],"c-2":["\n",{"->":"night_0.veinrock_silas"},{"#f":5}],"c-3":["\n",{"->":"night_0.end_night_0"},{"#f":5}]}],{"#f":1}],"veinrock_sleep":["^You manage a few hours of shallow, restless sleep. You dream about a mine shaft that goes down forever. You wake up feeling slightly more alert.","\n",{"->":".^.^.veinrock_hub"},{"#f":1}],"veinrock_explore":["ev",true,"/ev",{"VAR=":"day_1_gloria","re":true},"^You walk along the main road as the sun comes up. Everything is closed. The town feels like a movie set. Facades with nothing behind them. You notice the diner opens at 7. An older adult woman behind the window turns on lights. You don't go in yet, but you've clocked her.","\n",{"->":".^.^.veinrock_hub"},{"#f":1}],"veinrock_silas":["ev",{"VAR?":"silas_trust"},1,"+",{"VAR=":"silas_trust","re":true},"/ev","^You call Silas. He picks up on one ring.","\n","^\"You're there? Good. Get some rest. Report in after your first shift. And be careful.\"","\n",{"->":".^.^.veinrock_hub"},{"#f":1}],"end_night_0":[["^2PM.","\n","^You walk across town to The Hollows.","\n","^The mine entrance is bigger up close. The arch must be at least thirty feet tall. In the daylight, you see the infrastructure: wiring, ventilation ducts, a ticket booth, crowd barriers for the nightly queue. It's a professional operation.","\n","^A sign by the staff entrance reads: NEW HIRE ORIENTATION - REPORT TO OFFICE.","\n","^You push through the door.","\n","^The air changes immediately. Cooler. Damp. And underneath everything, that hum.","\n","^You're inside.","\n","ev","str","^Continue.","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"day_1"},{"#f":5}]}],{"#f":1}],"#f":1}],"day_1":[{"->":".^.orientation_entrance"},{"orientation_entrance":[["^The staff entrance leads into a narrow concrete corridor. Fluorescent tubes overhead. The air smells like fog machine fluid and something older underneath: damp stone, copper, earth.","\n","^A laminated sign on the wall reads: ALL STAFF MUST CHECK IN AT FRONT OFFICE BEFORE SHIFT. Another reads: RESTRICTED AREAS ARE OFF-LIMITS. VIOLATORS WILL BE TERMINATED.","\n","ev","str","^That's one way to phrase it.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Keep moving.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["\n","^Terminated. You file that word away.","\n",{"->":"day_1.the_office"},{"#f":5}],"c-1":["\n",{"->":"day_1.the_office"},{"#f":5}]}],{"#f":1}],"the_office":[["^The front office is a converted mining foreman's room. You can still see the old riveted iron walls behind the drywall. A desk. Filing cabinets. A bank of security monitors showing camera feeds from inside the attraction, all currently dark.","\n","^A man stands up from behind the desk. Mid-50s. Polo shirt with the HorrorCo logo, a stylized H with claw marks through it. He's got the energy of a car dealership manager: big smile, firm handshake, eyes that are already sizing you up.","\n","^\"You must be Val! Dale Ruskin, general manager. Welcome to The Hollows.\"","\n","ev","str","^\"Nice to meet you.\"","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^\"Thanks for having me. I'm excited to start.\"","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["\n","^\"Likewise, likewise. We're glad to have you. Always need fresh faces around here.\" He laughs at something that isn't a joke.","\n",{"->":"day_1.dale_intro"},{"#f":5}],"c-1":["\n","^\"Love the enthusiasm. That's what we look for. Enthusiasm and reliability.\" He holds eye contact a beat too long on that last word.","\n",{"->":"day_1.dale_intro"},{"#f":5}]}],{"#f":1}],"dale_intro":[["^\"So, Val. Before we get into the tour and the paperwork, tell me: why The Hollows? We're not exactly easy to get to.\"","\n",["ev",{"^->":"day_1.dale_intro.0.2.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","str","^\"","/str","/ev",{"*":".^.^.c-0","flg":22},{"s":["^\"I've always been into haunts.",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.dale_intro.0.3.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","str","^\"","/str","/ev",{"*":".^.^.c-1","flg":22},{"s":["^\"Honestly, I needed a change of scenery.",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.dale_intro.0.4.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","str","^\"","/str","/ev",{"*":".^.^.c-2","flg":22},{"s":["^\"I heard the rumors.",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_1.dale_intro.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.2.s"},[{"#n":"$r2"}],"^ This is the best in the country, right?\"","\n","^Dale beams. \"The best in the country. Maybe the world. And I'm not just saying that because I run the place.\" He is absolutely saying that because he runs the place.","\n",{"->":"day_1.dale_tour_start"},{"#f":5}],"c-1":["ev",{"^->":"day_1.dale_intro.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.3.s"},[{"#n":"$r2"}],"^ Saw the listing online.\"","\n","^\"A lot of people end up here that way. Looking for something different.\" His smile doesn't waver. \"They usually find it.\"","\n",{"->":"day_1.dale_tour_start"},{"#f":5}],"c-2":["ev",{"^->":"day_1.dale_intro.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.4.s"},[{"#n":"$r2"}],"^ People say this place is the real deal.\"","\n","^Dale's expression doesn't change, but something behind his eyes shifts. Just for a moment. Then the smile is back, wider.","\n","^\"People say a lot of things. That's the beauty of the haunt business. The line between what's real and what's performance? That's where the magic is.\"","\n","ev",{"VAR?":"dale_suspicion"},1,"+",{"VAR=":"dale_suspicion","re":true},"/ev",{"->":"day_1.dale_tour_start"},{"#f":5}]}],{"#f":1}],"dale_tour_start":[["^\"Alright. Let me show you the operation.\"","\n","^Dale grabs a clipboard and leads you out of the office and into the main corridor. In daylight (or rather, in the work lights that substitute for daylight down here) The Hollows looks like a construction site crossed with a theater backstage. Exposed wiring. Plywood flats painted to look like stone walls. Animatronic rigs hanging limp from the ceiling.","\n","^\"We run about thirty scare zones across three levels,\" Dale explains, walking briskly. \"Upper tunnels, mid-level, and the deep rooms. You'll start in the uppers. That's where most new hires go.\"","\n",["ev",{"^->":"day_1.dale_tour_start.0.6.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"What's in the deep rooms?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.dale_tour_start.0.7.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"How many actors per shift?\"",{"->":"$r","var":true},null]}],"ev","str","^Just follow and observe.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["ev",{"^->":"day_1.dale_tour_start.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.6.s"},[{"#n":"$r2"}],"\n","^Dale doesn't break stride. \"The deep rooms are for senior actors. High-intensity scares. Mechanical rigs, water effects, the works. You'll get there eventually.\" He says it like a promise. Or a warning.","\n",{"->":"day_1.the_tour"},{"#f":5}],"c-1":["ev",{"^->":"day_1.dale_tour_start.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.7.s"},[{"#n":"$r2"}],"\n","^\"We run about forty actors on a full night, plus tech crew, plus floor managers. It's a big operation.\" He says this with pride, but forty actors for a haunted attraction this size seems thin.","\n",{"->":"day_1.the_tour"},{"#f":5}],"c-2":["\n","^You take in the details as Dale talks. The corridors are wider than you expected. The ceilings are high: original mine architecture, reinforced but not rebuilt. This place wasn't just converted. It was barely modified. The mine is the attraction.","\n",{"->":"day_1.the_tour"},{"#f":5}]}],{"#f":1}],"the_tour":[["^Dale leads you through a winding route. Even with the work lights on, the tunnels feel oppressive. The walls are rough stone, real mine walls, not set dressing. Every so often you pass a steel door marked with a HorrorCo logo and a keycard reader.","\n","^\"Storage,\" Dale says when you glance at one. \"Equipment, props, spare parts. Nothing exciting.\"","\n","^The doors are spaced irregularly. Some corridors have three in a row. Others have none for long stretches. There's no pattern you can see.","\n",["ev",{"^->":"day_1.the_tour.0.6.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"That's a lot of storage.\"",{"->":"$r","var":true},null]}],"ev","str","^Note the door locations mentally.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["ev",{"^->":"day_1.the_tour.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.6.s"},[{"#n":"$r2"}],"\n","^\"Big operation, big inventory.\" Dale doesn't elaborate.","\n",{"->":"day_1.meet_bex"},{"#f":5}],"c-1":["\n","^You count. Fourteen locked doors between the office and the first scare zone. That's more infrastructure than any haunted attraction needs.","\n",{"->":"day_1.meet_bex"},{"#f":5}]}],{"#f":1}],"meet_bex":[["^You notice the temperature dropping as you walk deeper. Not dramatically, just a degree or two, steady, like descending into something.","\n","^Dale rounds a corner and you nearly walk into someone.","\n","^They're sitting on an overturned crate in the middle of a scare zone, eating a granola bar. Black jeans, black hoodie, pale makeup smudged around their eyes from last night's shift. Or maybe the night before. They look up without surprise, as if they'd been expecting you.","\n","^\"Bex, this is Val. New hire. Val, this is Bex. They've been with us for...\" Dale pauses, and for a second he looks genuinely uncertain. \"How long has it been, Bex?\"","\n","^Bex chews. Thinks.","\n","^\"A while.\"","\n","^Dale laughs. \"A while. Bex is one of our best. They'll show you the ropes tonight.\"","\n",["ev",{"^->":"day_1.meet_bex.0.14.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"Hey. Nice to meet you.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.meet_bex.0.15.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Looking forward to working together.\"",{"->":"$r","var":true},null]}],"ev","str","^Just nod.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["ev",{"^->":"day_1.meet_bex.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.14.s"},[{"#n":"$r2"}],"\n","^Bex nods. \"Likewise.\" Their eyes flick to Dale, then back to you. Something passes across their face that you can't read.","\n",{"->":"day_1.bex_aside"},{"#f":5}],"c-1":["ev",{"^->":"day_1.meet_bex.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.15.s"},[{"#n":"$r2"}],"\n","^\"Sure.\" Bex's voice is flat. Not hostile, just... distant. Like they're listening to something else.","\n",{"->":"day_1.bex_aside"},{"#f":5}],"c-2":["\n","^You nod. Bex nods back. There's a stillness to them that feels practiced. Or maybe involuntary.","\n",{"->":"day_1.bex_aside"},{"#f":5}]}],{"#f":1}],"bex_aside":[["^Dale claps his hands. \"Alright, I've got paperwork to finish up. Bex, give Val the actor's tour? Show them the upper zones, the break room, the usual.\"","\n","^He turns to you. \"Come find me in the office when you're done. We'll get your contract signed and your schedule sorted.\"","\n","^Dale leaves. His footsteps echo and fade.","\n","^Bex watches him go. They wait until the sound disappears completely.","\n","^\"So,\" Bex says. \"First haunt job?\"","\n",["ev",{"^->":"day_1.bex_aside.0.10.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"First professional one, yeah.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.bex_aside.0.11.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"I've done a few seasonal gigs.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.bex_aside.0.12.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"Is Dale always like that?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_1.bex_aside.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.10.s"},[{"#n":"$r2"}],"\n","^\"Professional.\" Bex almost smiles. \"That's one word for it.\"","\n",{"->":"day_1.bex_tour"},{"#f":5}],"c-1":["ev",{"^->":"day_1.bex_aside.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.11.s"},[{"#n":"$r2"}],"\n","^\"Seasonal.\" Bex says the word like it's from another language. \"Right. Most haunts are seasonal.\"","\n",{"->":"day_1.bex_tour"},{"#f":5}],"c-2":["ev",{"^->":"day_1.bex_aside.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.12.s"},[{"#n":"$r2"}],"\n","^Bex considers this. \"Dale is... consistent. He's always exactly like that. Every single day. Which, if you think about it, is kind of weird.\"","\n",{"->":"day_1.bex_tour"},{"#f":5}]}],{"#f":1}],"bex_tour":[["^Bex hops off the crate and starts walking. Their pace is slower than Dale's, more deliberate. They point things out as you go.","\n","^\"Break room's down that hall. Fridge, microwave, lockers. Lock your stuff. Things go missing sometimes.\"","\n","^\"Costume room is past the break room. You'll get fitted before your first shift tonight. Mostly something to go over your black clothes, face paint, maybe a mask depending on your zone.\"","\n","^They stop at an intersection. Left goes upward; you can feel the grade. Right goes down.","\n","^\"Left is the upper scare zones. That's where you'll be tonight. Right goes to mid-level.\"","\n",["ev",{"^->":"day_1.bex_tour.0.10.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"And below mid-level?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.bex_tour.0.11.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"What zone are you in?\"",{"->":"$r","var":true},null]}],"ev","str","^Follow their lead.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["ev",{"^->":"day_1.bex_tour.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.10.s"},[{"#n":"$r2"}],"\n","^Bex doesn't answer immediately. They look down the right corridor. The work lights end about fifty feet in, replaced by a dim amber glow.","\n","^\"Below mid-level is deep rooms. You don't go there.\"","\n","^\"Dale said it's for senior actors.\"","\n","^\"Dale says a lot of things.\" Bex turns left. \"Come on.\"","\n",{"->":"day_1.upper_zones"},{"#f":5}],"c-1":["ev",{"^->":"day_1.bex_tour.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.11.s"},[{"#n":"$r2"}],"\n","^\"I rotate. Uppers, mids, wherever they need me.\" A pause. \"I used to work the deep rooms. A while ago.\"","\n","^\"What was that like?\"","\n","^Bex starts walking left, toward the upper zones. \"Dark,\" they say, and don't elaborate.","\n",{"->":"day_1.upper_zones"},{"#f":5}],"c-2":["\n","^Bex turns left without hesitation. As you follow, you glance down the right corridor. The work lights thin out quickly. The walls narrow. The air coming from that direction is warmer.","\n",{"->":"day_1.upper_zones"},{"#f":5}]}],{"#f":1}],"upper_zones":[["^The upper scare zones are, in daylight, almost comically mundane. Plywood corridors painted black. Fog machine nozzles built into the floor. Hidden alcoves where actors wait. Speakers wired into the walls. Motion sensors trigger strobe lights and sound cues.","\n","^Bex walks you through three zones: THE SHAFT, THE COLLAPSE, and THE BURIED.","\n","^\"Creative naming,\" you say.","\n","^\"HorrorCo has a theme.\" Bex runs a hand along the tunnel wall. Real stone, not plywood. \"Mining disaster. Cave-ins. Being trapped underground. Guests love it.\"","\n",["ev",{"^->":"day_1.upper_zones.0.8.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","str","^\"","/str","/ev",{"*":".^.^.c-0","flg":22},{"s":["^\"Do you know the history?",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.upper_zones.0.9.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Have you ever seen anything actually... strange in here?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.upper_zones.0.10.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"Guests ever get hurt?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_1.upper_zones.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.8.s"},[{"#n":"$r2"}],"^ The actual mine?\"","\n","^Bex stops walking. \"The Aldrich Mine. 1973. Sinkhole took the whole main shaft. Killed...\" They pause. Their mouth opens and closes. \"Forty...\" They frown. \"A lot of people.\"","\n","^Their hand goes to the wall. Touches the stone. As if the number might be in there somewhere.","\n",{"->":"day_1.end_of_tour"},{"#f":5}],"c-1":["ev",{"^->":"day_1.upper_zones.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.9.s"},[{"#n":"$r2"}],"\n","^Bex's pace doesn't change. \"Define strange. I work in a haunted house. Everything's strange. That's the product.\"","\n","^\"I mean strange that's not part of the show.\"","\n","^A beat of silence.","\n","^\"Ask me again after you've worked a few shifts.\"","\n",{"->":"day_1.end_of_tour"},{"#f":5}],"c-2":["ev",{"^->":"day_1.upper_zones.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.10.s"},[{"#n":"$r2"}],"\n","^\"Sometimes. People trip, run into walls, panic. Standard haunt stuff. We're trained in de-escalation.\" Bex recites this like they've said it a hundred times.","\n","^\"I've heard rumors about worse than that.\"","\n","^Bex looks at you. Really looks at you, for the first time.","\n","^\"Rumors are good for business.\"","\n",{"->":"day_1.end_of_tour"},{"#f":5}]}],{"#f":1}],"end_of_tour":[["^Bex walks you back toward the office corridor.","\n","^\"One more thing.\" They stop. \"When you're working your zone, stay in your zone. Don't wander. Especially after midnight. The layout can get...\" They search for the word. \"Confusing.\"","\n",["ev",{"^->":"day_1.end_of_tour.0.4.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"Confusing how?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.end_of_tour.0.5.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Is that standard advice?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.end_of_tour.0.6.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"Thanks for the heads up.\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_1.end_of_tour.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.4.s"},[{"#n":"$r2"}],"\n","^\"You'll think you know where you are, and then you won't. Happens to everyone at first. Just stay put and wait for the shift to end.\"","\n","^That doesn't sound like normal new-hire advice.","\n",{"->":"day_1.sign_paperwork"},{"#f":5}],"c-1":["ev",{"^->":"day_1.end_of_tour.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.5.s"},[{"#n":"$r2"}],"\n","^\"It's my advice.\" Bex meets your eyes. \"Take it or don't.\"","\n",{"->":"day_1.sign_paperwork"},{"#f":5}],"c-2":["ev",{"^->":"day_1.end_of_tour.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.6.s"},[{"#n":"$r2"}],"\n","ev",{"VAR?":"bex_relationship"},1,"+",{"VAR=":"bex_relationship","re":true},"/ev","ev",true,"/ev",{"VAR=":"bex_hum","re":true},"^Bex nods once. They turn to go, then stop.","\n","^\"Val? The hum. You hear it, right?\"","\n","^Before you can answer, they walk away.","\n",{"->":"day_1.sign_paperwork"},{"#f":5}]}],{"#f":1}],"sign_paperwork":[["^You find Dale in the office. He's got a stack of paperwork ready: employment contract, NDA, liability waiver. Standard forms, except for the NDA, which is unusually comprehensive.","\n","^You scan the key clauses:","\n","^\"Employee agrees not to disclose any details of attraction design, layout, or operational procedures...\"","\n","^\"Employee acknowledges that The Hollows experience may include intense sensory stimulation including but not limited to extreme darkness, physical contact, confined spaces, and disorientation...\"","\n","^\"Employee waives all claims against HorrorCo Entertainment LLC for psychological distress, injury, or...\"","\n","^The next word catches your eye.","\n","^\"...disappearance.\"","\n",["ev",{"^->":"day_1.sign_paperwork.0.14.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"This waiver mentions disappearance.\"",{"->":"$r","var":true},null]}],"ev","str","^Read it again to make sure you read it right.","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^Keep reading without reacting.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["ev",{"^->":"day_1.sign_paperwork.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.14.s"},[{"#n":"$r2"}],"\n","^Dale doesn't blink. \"Legal boilerplate. Our lawyers are thorough. You know how it is. Cover every base, no matter how unlikely.\" His smile is steady.","\n",{"->":"day_1.sign_or_not"},{"#f":5}],"c-1":["\n","^Disappearance. That's what it says. Right there between \"injury\" and a clause about \"unforeseen metaphysical phenomena,\" which you also have questions about.","\n",{"->":"day_1.sign_or_not"},{"#f":5}],"c-2":["\n","^You file it away. Disappearance. Unforeseen metaphysical phenomena. This is not a standard liability waiver.","\n",{"->":"day_1.sign_or_not"},{"#f":5}]}],{"#f":1}],"sign_or_not":[["^Dale is watching you read. Patient. Still smiling.","\n","^\"Any questions before you sign?\"","\n",["ev",{"^->":"day_1.sign_or_not.0.4.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"What are 'unforeseen metaphysical phenomena'?\"",{"->":"$r","var":true},null]}],"ev","str","^Sign it.","/str","/ev",{"*":".^.c-1","flg":20},["ev",{"^->":"day_1.sign_or_not.0.11.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"Seems pretty thorough for a haunted house.\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_1.sign_or_not.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.4.s"},[{"#n":"$r2"}],"\n","^\"You ever been in a haunt so scary you felt like you left your body? Like reality shifted?\" Dale chuckles. \"Guests have tried to sue over panic attacks, dissociative episodes, that sort of thing. The clause protects us. Nothing more.\"","\n","ev",{"VAR?":"dale_suspicion"},1,"+",{"VAR=":"dale_suspicion","re":true},"/ev",{"->":"day_1.sign_it"},{"#f":5}],"c-1":["\n","^You sign. You're here to investigate, not to be protected by paperwork. Whatever rights you're waiving, the Order will handle the legal side.","\n",{"->":"day_1.post_sign"},{"#f":5}],"c-2":["ev",{"^->":"day_1.sign_or_not.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.11.s"},[{"#n":"$r2"}],"\n","^\"We're not just a haunted house, Val. We're the most terrifying experience in America.\" He taps the promotional photo on his desk. \"That comes with liability.\"","\n",{"->":"day_1.sign_it"},{"#f":5}]}],{"#f":1}],"sign_it":[["ev","str","^Sign the paperwork.","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"day_1.post_sign"},{"#f":5}]}],{"#f":1}],"post_sign":["^Dale takes the signed forms and files them immediately. He hands you a schedule. Your first shift starts tonight at 7 PM.","\n","^\"Costume fitting at 6. Bex will get you set up. Show starts at 8, but we do run-throughs first. You'll be in Zone 2: The Collapse.\"","\n","^He extends his hand. You shake it.","\n","^\"Welcome to The Hollows, Val. You're going to love it here.\"","\n","^His grip is firm. A beat too long.","\n","^\"Everyone does.\"","\n",{"->":".^.^.pre_night_1"},{"#f":1}],"pre_night_1":["^You step outside. Late afternoon. The desert sun is already dropping toward the mountains. You have a few hours before your shift.","\n","ev",{"VAR?":"day_1_gloria"},"/ev",[{"->":".^.b","c":true},{"b":["\n","^You think about the woman you saw in the diner this morning. It's still open. The sign reads ALDRICH'S.","\n",{"->":".^.^.^.6"},null]}],"nop","\n",{"->":".^.^.pre_night_1_hub"},{"#f":1}],"pre_night_1_hub":[["ev","str","^Go to the diner.","/str",{"VAR?":"day_1_gloria"},{"CNT?":"day_1.gloria_intro"},"!","&&","/ev",{"*":".^.c-0","flg":21},"ev","str","^Go back to the motel and prepare.","/str",{"CNT?":"day_1.pre_night_1_motel"},"!","/ev",{"*":".^.c-1","flg":21},"ev","str","^Call Silas to report.","/str",{"CNT?":"day_1.pre_night_1_silas"},"!","/ev",{"*":".^.c-2","flg":21},"ev","str","^Head to your shift.","/str","/ev",{"*":".^.c-3","flg":20},{"c-0":["\n",{"->":"day_1.gloria_intro"},{"#f":5}],"c-1":["\n",{"->":"day_1.pre_night_1_motel"},{"#f":5}],"c-2":["\n",{"->":"day_1.pre_night_1_silas"},{"#f":5}],"c-3":["\n",{"->":"day_1.to_night_1"},{"#f":5}]}],{"#f":1}],"pre_night_1_motel":["^You walk back to the Mineshaft Inn. Room 6. You sit on the bed and go over what you've learned: the locked doors, the deep rooms, Bex's warning, the waiver. You write it all down in your notebook in the Order's shorthand.","\n","ev",{"VAR?":"priority"},"str","^find_mara","/str","==","/ev",[{"->":".^.b","c":true},{"b":["^ You also note that you haven't found any trace of Mara yet. No one has mentioned a recent departure. It's like she was never here. Because according to them, she wasn't.",{"->":".^.^.^.10"},null]}],"nop","\n",{"->":".^.^.pre_night_1_hub"},{"#f":1}],"pre_night_1_silas":["ev",{"VAR?":"silas_trust"},1,"+",{"VAR=":"silas_trust","re":true},"/ev","^You call from the burner. Silas picks up on the second ring.","\n","^\"I'm in. Start tonight. The place is big, three levels, maybe more. Restricted areas everywhere. The NDA mentions 'disappearance' and 'metaphysical phenomena' in the liability waiver.\"","\n","^Silence on the line.","\n","^\"Stay sharp. And stay on the upper levels for now.\"","\n","ev",{"VAR?":"priority"},"str","^find_mara","/str","==","/ev",[{"->":".^.b","c":true},{"b":["^ \"Any trace of Mara?\" he asks. ",{"->":".^.^.^.23"},null]}],[{"->":".^.b"},{"b":["^ \"Focus on the layout first,\" he adds.",{"->":".^.^.^.23"},null]}],"nop","^ \"Report after your shift.\"","\n",{"->":".^.^.pre_night_1_hub"},{"#f":1}],"gloria_intro":[["^The diner is small, warm, and mostly empty. Checkered floor, vinyl booths, a counter with stools. The kind of place that hasn't been updated since the '80s because it didn't need to be.","\n","^The woman behind the counter is in her early sixties. She moves with a careful precision. Her eyes are sharp. A name tag reads GLORIA.","\n","^She sets a coffee down in front of you before you ask for one.","\n","^\"You're new.\"","\n","^It's not a question.","\n",["ev",{"^->":"day_1.gloria_intro.0.10.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"That obvious?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.gloria_intro.0.11.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"I just started at The Hollows.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.gloria_intro.0.12.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"I'm Val.\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_1.gloria_intro.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.10.s"},[{"#n":"$r2"}],"\n","^\"It's a small town. And people don't come here unless they're visiting The Hollows or working there.\" She studies you. \"You don't look like a tourist.\"","\n","^\"My name is Val.\"","\n",{"->":"day_1.gloria_chat"},{"#f":5}],"c-1":["ev",{"^->":"day_1.gloria_intro.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.11.s"},[{"#n":"$r2"}],"\n","^Something crosses her face. Fast, then gone. She tops off a coffee cup that's already full.","\n","^\"Another one.\"","\n","^\"My name is Val.\"","\n",{"->":"day_1.gloria_chat"},{"#f":5}],"c-2":["ev",{"^->":"day_1.gloria_intro.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.12.s"},[{"#n":"$r2"}],"\n","^\"Gloria.\" She doesn't offer a handshake. \"You working up at the mine?\"","\n",{"->":"day_1.gloria_chat"},{"#f":5}]}],{"#f":1}],"gloria_chat":[["^Gloria leans against the counter. The diner is empty except for the two of you.","\n","^\"How long you planning to stay?\"","\n",["ev",{"^->":"day_1.gloria_chat.0.4.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"As long as they'll have me.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.gloria_chat.0.5.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Haven't decided yet.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.gloria_chat.0.6.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"Why do you ask?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_1.gloria_chat.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.4.s"},[{"#n":"$r2"}],"\n","^Gloria's mouth tightens. \"That's what they all say.\"","\n",{"->":"day_1.gloria_hints"},{"#f":5}],"c-1":["ev",{"^->":"day_1.gloria_chat.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.5.s"},[{"#n":"$r2"}],"\n","^\"Smart. Keep it that way.\"","\n",{"->":"day_1.gloria_hints"},{"#f":5}],"c-2":["ev",{"^->":"day_1.gloria_chat.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.6.s"},[{"#n":"$r2"}],"\n","^\"Because people come to work at that place and they stay. Longer than makes sense. Longer than they planned.\" She pauses. \"And some of them don't stay at all. They just... stop being here.\"","\n",{"->":"day_1.gloria_hints"},{"#f":5}]}],{"#f":1}],"gloria_hints":[["^She pours herself a coffee and sits down across from you.","\n","^\"My family built this town. My father owned the mine. I was nine years old when the ground opened up and swallowed it.\"","\n",["ev",{"^->":"day_1.gloria_hints.0.4.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"I'm sorry.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.gloria_hints.0.5.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"The sinkhole.\"",{"->":"$r","var":true},null]}],"ev","str","^Listen.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["ev",{"^->":"day_1.gloria_hints.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.4.s"},[{"#n":"$r2"}],"\n","^She waves the sympathy away. \"It was a long time ago. Or it feels like it should be.\"","\n",{"->":"day_1.gloria_more"},{"#f":5}],"c-1":["ev",{"^->":"day_1.gloria_hints.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.5.s"},[{"#n":"$r2"}],"\n","^\"You did your homework.\" A flicker of something. Respect, maybe. Or wariness.","\n",{"->":"day_1.gloria_more"},{"#f":5}],"c-2":["\n",{"->":"day_1.gloria_more"},{"#f":5}]}],{"#f":1}],"gloria_more":[["^\"Forty-eight men went down that morning. None came back up. They said it was a geological event. Natural causes. But I was there. I heard it.\"","\n","^She wraps both hands around her mug.","\n","^\"A sinkhole doesn't breathe.\"","\n",["ev",{"^->":"day_1.gloria_more.0.6.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"What do you mean, breathe?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.gloria_more.0.7.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"You think it was something else.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_1.gloria_more.0.8.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"That must have been traumatic for a nine-year-old.\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_1.gloria_more.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.6.s"},[{"#n":"$r2"}],"\n","^\"I mean I heard it inhale. The ground shook, and then there was a sound like the earth was taking a breath. And then the men were gone.\"","\n","ev",{"VAR?":"gloria_trust"},1,"+",{"VAR=":"gloria_trust","re":true},"/ev",{"->":"day_1.gloria_end"},{"#f":5}],"c-1":["ev",{"^->":"day_1.gloria_more.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.7.s"},[{"#n":"$r2"}],"\n","^\"I know it was something else. I've known for fifty years. Nobody wanted to hear it then. Nobody wants to hear it now.\"","\n","ev",{"VAR?":"gloria_trust"},1,"+",{"VAR=":"gloria_trust","re":true},"/ev",{"->":"day_1.gloria_end"},{"#f":5}],"c-2":["ev",{"^->":"day_1.gloria_more.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.8.s"},[{"#n":"$r2"}],"\n","^\"It was. But the trauma isn't the memory. The trauma is that nobody believed what I heard.\" Her jaw sets. \"I know what I heard.\"","\n",{"->":"day_1.gloria_end"},{"#f":5}]}],{"#f":1}],"gloria_end":[["^Gloria stands, suddenly brisk. The openness closes.","\n","^\"You should eat something before your shift. The meatloaf's decent.\"","\n","^She's done talking. For now. But you can feel it. She has more. She's been waiting to tell someone. She just needs to know you're worth telling.","\n","ev","str","^Eat and head back.","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n","^The meatloaf is, in fact, decent.","\n",{"->":"day_1.pre_night_1_hub"},{"#f":5}]}],{"#f":1}],"to_night_1":[["^The sun drops behind the mountain. The Hollows' lights come on: reds, purples, a sickly green. The speakers mounted outside begin a low ambient drone. Cars start pulling into the parking lot. The queue forms.","\n","^Showtime.","\n","ev","str","^Report for your first shift.","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"night_1"},{"#f":5}]}],{"#f":1}],"#f":1}],"night_1":[{"->":".^.costume_fitting"},{"costume_fitting":[["^The costume room is bigger than you expected. More of a wardrobe department than a closet. Racks of costumes line both walls, organized by zone. Shelves of face paint, spirit gum, prosthetic pieces, dental appliances. A row of lit mirrors along the back wall, each station stocked with brushes, sponges, adhesive remover. It smells like greasepaint and latex and sweat.","\n","^The room is already busy. A woman two stations down is being transformed into something with a caved-in ribcage, a silicone chest piece strapped over her torso with visible bone and lung tissue. The detail is surgical. Next to her, a guy is pulling on a full-body suit that makes him look eight feet tall, elongated arms ending in jointed claw extensions. He flexes them, testing the range of motion. Across the room, someone is sitting perfectly still while another actor applies layered prosthetics to their face, building up a texture of blistered, peeling skin. They pop open a small plastic case from their bag and carefully press in a pair of milky white scleral lenses.","\n","^These aren't Halloween store costumes. This is professional creature work. Movie quality.","\n","^Bex is waiting at an open station. They've already laid out your pieces.","\n","ev","str","^Approach them","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"night_1.bex_fitting"},{"#f":5}]}],{"#f":1}],"bex_fitting":["^\"You're a dead miner. Zone 2, The Collapse.\"","\n","^The costume is a shredded, dust-caked mining jumpsuit, torn and aged to look like it's been underground for decades. Bex helps you into it over your black base layer. It's heavier than it looks: weighted in the shoulders, stiffened in places with dried resin to hold its shape. Over that, a cracked leather tool belt with a dented tin lantern clipped to the hip.","\n","^For the face, Bex sits you down at the mirror and works fast. Grey and blue greasepaint as a base. Darkened hollows around the eyes. A prosthetic gash across the forehead, glued down with spirit gum and blended at the edges. Then the mask: a half-face piece of cracked grey rubber molded to look like a caved-in skull, one eye socket crushed inward. It fits over the top half of your face, leaving your jaw exposed so your scream carries.","\n","^\"You don't talk. You don't chase. You wait in the boo hole until a group passes your trigger point, then you hit the window and scream. Reset. Wait. Repeat.\"","\n",{"->":".^.^.fitting_hub"},{"#f":1}],"fitting_hub":[[["ev",{"^->":"night_1.fitting_hub.0.0.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str",{"CNT?":"night_1.fitting_groups"},"!","/ev",{"*":".^.^.c-0","flg":19},{"s":["^\"How many groups per night?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_1.fitting_hub.0.1.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str",{"CNT?":"night_1.fitting_boohole"},"!","/ev",{"*":".^.^.c-1","flg":19},{"s":["^\"What's a boo hole?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_1.fitting_hub.0.2.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str",{"CNT?":"night_1.fitting_trigger"},"!","/ev",{"*":".^.^.c-2","flg":19},{"s":["^\"What's the trigger point?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_1.fitting_hub.0.3.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str",{"CNT?":"night_1.fitting_rules"},"!","/ev",{"*":".^.^.c-3","flg":19},{"s":["^\"Any rules I should know?\"",{"->":"$r","var":true},null]}],"ev","str","^No more questions.","/str","/ev",{"*":".^.c-4","flg":20},{"c-0":["ev",{"^->":"night_1.fitting_hub.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.0.s"},[{"#n":"$r2"}],"\n",{"->":"night_1.fitting_groups"},{"#f":5}],"c-1":["ev",{"^->":"night_1.fitting_hub.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.1.s"},[{"#n":"$r2"}],"\n",{"->":"night_1.fitting_boohole"},{"#f":5}],"c-2":["ev",{"^->":"night_1.fitting_hub.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.2.s"},[{"#n":"$r2"}],"\n",{"->":"night_1.fitting_trigger"},{"#f":5}],"c-3":["ev",{"^->":"night_1.fitting_hub.0.c-3.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.3.s"},[{"#n":"$r2"}],"\n",{"->":"night_1.fitting_rules"},{"#f":5}],"c-4":["\n",{"->":"night_1.fitting_continued"},{"#f":5}]}],{"#f":1}],"fitting_groups":["^\"On a full night? You'll get maybe sixty, seventy groups through your zone. Peak hours, they're coming every thirty to forty-five seconds. Off-peak, you might wait a few minutes between.\"","\n",{"->":".^.^.fitting_hub"},{"#f":1}],"fitting_boohole":["^\"It's the alcove you hide in. Small space behind the window, just big enough for you to stand in. You wait in there, watch through the slit, and hit the window when they cross your mark.\" They glance at you. \"You'll be spending a lot of time in it. Get comfortable. Or as comfortable as you can.\"","\n",{"->":".^.^.fitting_hub"},{"#f":1}],"fitting_trigger":["^\"There's a mark on the floor. Glow tape, only visible from inside the boo hole. When the first person in the group crosses it, you go. Not before. Timing is everything. Too early and they see it coming. Too late and you're scaring the back of their heads.\"","\n",{"->":".^.^.fitting_hub"},{"#f":1}],"fitting_rules":["^\"Don't touch the guests. Don't break character in front of guests. Don't leave your zone. If a guest says the safe word, which is 'mercy,' you break character, turn on your flashlight, and walk them to the nearest exit. Other than that...\" Bex shrugs. \"Make them scream.\"","\n",{"->":".^.^.fitting_hub"},{"#f":1}],"fitting_continued":[["^You look at yourself in the mirror. Under the fluorescent lights, you can see where the work ends: the spirit gum edge, the seam of the mask, the clean line where the greasepaint stops at your collar. It's impressive up close. From ten feet away in a dark corridor, it would be convincing. In full fog with strobes, it'll be something else entirely.","\n","^Around you, the other actors are finishing up. The woman with the ribcage piece is testing a mechanism that makes the exposed lung inflate and deflate. The tall guy on stilts takes a practice step, his claw arms swaying. The actor with the blistered face has added a set of rotting dental prosthetics and is grinning at the mirror, checking the fit.","\n","^Bex watches your reaction.","\n","^\"It looks different in the dark. Everything does.\"","\n",["ev",{"^->":"night_1.fitting_continued.0.8.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"I believe you.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_1.fitting_continued.0.9.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"How do I look?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"night_1.fitting_continued.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.8.s"},[{"#n":"$r2"}],"\n",{"->":"night_1.run_through"},{"#f":5}],"c-1":["ev",{"^->":"night_1.fitting_continued.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.9.s"},[{"#n":"$r2"}],"\n","^\"Dead.\" Bex says it flat. Then, almost a smile. \"That's the idea.\"","\n",{"->":"night_1.run_through"},{"#f":5}]}],{"#f":1}],"run_through":[["^6:45 PM. The full cast assembles in the break room for the pre-show meeting. About thirty-five actors tonight, plus a handful of tech crew and three floor managers. Dale is at the front, clipboard in hand, radiating enthusiasm.","\n","^\"Good evening, everyone. Full house tonight. We're sold out through midnight. Let's give them something to remember.\"","\n","^He runs through the assignments. Zone by zone, actor by actor. You're Zone 2, Position B: The Collapse, boo hole three. Bex is in Zone 2 as well, Position A. They'll be in the corridor ahead of you, doing a stalker walk to herd groups toward your window.","\n","^\"New hire tonight. Val Rowan, Zone 2 Bravo. Bex, keep an eye on them.\"","\n","^Bex nods.","\n","^Dale finishes the briefing with the same line he apparently uses every night: \"Make it real, people.\"","\n","^The actors disperse. Some are joking, loose, relaxed. A few are stretching like athletes. One woman is already in character, muttering to herself in a corner, her eyes blank. Nobody seems to think this is unusual.","\n","ev","str","^Follow Bex to your zone.","/str","/ev",{"*":".^.c-0","flg":20},["ev",{"^->":"night_1.run_through.0.20.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Does he always say that? 'Make it real'?\"",{"->":"$r","var":true},null]}],{"c-0":["\n",{"->":"night_1.enter_zone"},{"#f":5}],"c-1":["ev",{"^->":"night_1.run_through.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.20.s"},[{"#n":"$r2"}],"\n","^Bex is already walking. \"Every night. Same speech, same words. I've heard it...\" They trail off, counting something internally, then give up. \"A lot.\"","\n",{"->":"night_1.enter_zone"},{"#f":5}]}],{"#f":1}],"enter_zone":[["^Bex leads you through the upper tunnels. The work lights are off now. The show lighting is on: dim red washes, pockets of total darkness, the occasional flicker of a strobe on standby. The fog machines are warming up, a low hiss from the floor vents. The speakers are cycling ambient audio. Dripping water. Distant rumbling. A pickaxe striking stone, over and over.","\n","^The Collapse is a series of narrow corridors designed to look like a mine tunnel after a cave-in. Timber supports lean at bad angles. Rubble (foam, but convincing) is piled against the walls. The ceiling is deliberately low. Guests will have to duck in places.","\n","^Your boo hole is a recessed alcove behind a breakaway window. It's a tight space, barely wide enough for your shoulders. A water bottle and a flashlight sit on a narrow ledge at hip height. A reset button for the window's pneumatic latch is mounted on the wall.","\n","^Bex shows you the mechanics.","\n","^\"Window's spring-loaded. You slam it open, you scream, you hold for one second, then pull it shut and hit the reset. The latch resets in about three seconds. Don't try to hit the next group before it clicks or you'll jam it.\"","\n","^They demonstrate. The window bangs open with a sharp crack. Even expecting it, your pulse jumps.","\n","^\"That's the startle. The sound does half the work. The other half is your scream. Make it sharp. Short. From the chest, not the throat, or you'll blow your voice out by 10.\"","\n",["ev",{"^->":"night_1.enter_zone.0.14.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"Got it.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_1.enter_zone.0.15.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"What's your position like?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_1.enter_zone.0.16.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"What if the window jams?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"night_1.enter_zone.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.14.s"},[{"#n":"$r2"}],"\n",{"->":"night_1.first_groups"},{"#f":5}],"c-1":["ev",{"^->":"night_1.enter_zone.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.15.s"},[{"#n":"$r2"}],"\n","^\"I'm in the corridor before you. I step out from behind a support beam, match their walking pace, stay about five feet behind the last person. No sound. When they notice me, they speed up. Right into your window.\" A pause. \"Teamwork.\"","\n",{"->":"night_1.first_groups"},{"#f":5}],"c-2":["ev",{"^->":"night_1.enter_zone.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.16.s"},[{"#n":"$r2"}],"\n","^\"Bang on it with your palm. If it doesn't open, use the flashlight to signal the floor manager. But it won't jam if you time the reset right. Just listen for the click.\"","\n",{"->":"night_1.first_groups"},{"#f":5}]}],{"#f":1}],"first_groups":[["^7:55 PM. Five minutes to showtime.","\n","^You're in the boo hole. The window is shut. The corridor outside is dark except for the faint red wash. The fog is rolling in, ankle-height, cold. The ambient audio has shifted to something lower, more rhythmic. Almost like breathing.","\n","^Through the wall, muffled, you can hear the crowd outside. Hundreds of people in line. Talking, laughing, nervous. Someone screams from the entrance of another zone and there's a ripple of laughter.","\n","^Your radio crackles. Dale's voice: \"Doors open in two. Positions, everyone. Let's have a good night.\"","\n","^You press your back against the rear wall of the alcove. You pull the mask down. You wait.","\n","^The first group enters The Collapse at 8:02 PM.","\n","^You hear them before you see them. Footsteps. Nervous whispers. Someone saying \"oh my God\" already and nothing has happened yet. The fog swirls around their ankles.","\n","^Through the slit in the window, you see Bex step out behind them. Silent. The last person in the group, a tall guy in a baseball cap, glances back and freezes. \"Oh, oh, GO, go go go.\" The group surges forward.","\n","^The first person crosses your glow tape mark.","\n","ev","str","^Hit the window.","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"night_1.first_scare"},{"#f":5}]}],{"#f":1}],"first_scare":[["^You slam the window open. The crack echoes off the stone walls. You scream: short, sharp, from the chest like Bex said.","\n","^The reaction is immediate. The person in front recoils into the person behind them. Someone shrieks. The tall guy in the back is now trying to get to the front. The group compresses, stumbles, then bolts down the corridor and around the corner.","\n","^You pull the window shut. Hit the reset. The latch clicks.","\n","^Silence. Fog. The ambient audio loops.","\n","^Thirty seconds later, the next group comes through.","\n","ev","str","^Reset and go again.","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"night_1.the_rhythm"},{"#f":5}]}],{"#f":1}],"the_rhythm":[["^You find the rhythm.","\n","^Window. Scream. Reset. Wait. Listen for footsteps. Watch for the glow tape. Window. Scream. Reset.","\n","^Every group is different. Some are loud before they even reach you. Teenagers, usually, performing bravery for each other. They scream the hardest when the window hits. Some groups are quiet, cautious, which means the startle lands cleaner. Couples grip each other. Kids (too young to be here, you think, but that's not your call) sometimes cry. Parents pull them through.","\n","^After about twenty groups, your body starts to settle into it. Your shoulders loosen. Your scream becomes consistent: same pitch, same duration, same force. You learn to read the timing by sound alone. Footsteps on gravel. The change in the fog pattern when a body moves through it. Bex's groups always arrive at the same pace, herded to perfection.","\n","^This is the job. Repetition. Precision. Controlled bursts of adrenaline. Reset. Repeat.","\n","^By 9:30, your throat is raw and your right shoulder aches from the window. You take a sip of water. A floor manager's voice comes over the radio: \"Zone 2, pacing is good. Keep it up.\"","\n","ev","str","^Keep working.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Check in with Bex during a gap between groups.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["\n",{"->":"night_1.late_shift"},{"#f":5}],"c-1":["\n","^You lean out of the boo hole during a lull. Bex is standing at their position, still as stone. You give a thumbs up. They return it without turning their head. They're watching the corridor.","\n","^\"How's your voice?\" they ask, barely above a whisper.","\n","^\"Holding.\"","\n","^\"Good. It gets busy after 10.\"","\n",{"->":"night_1.late_shift"},{"#f":5}]}],{"#f":1}],"late_shift":[["^Bex is right. After 10, the gaps between groups shrink. You're hitting the window every thirty seconds, sometimes faster. The groups are louder, more energized. Weekend crowd. Some of them have been drinking. You can smell it through the fog.","\n","^At 10:47 PM, something different.","\n","^A group comes through. Four people. They're quieter than average. Moving slowly. Bex does the stalker walk behind them, but the last person in the group doesn't react. Doesn't speed up. Doesn't look back.","\n","^They cross the glow tape.","\n","^You hit the window.","\n","^Three of them flinch. Standard reaction. The fourth, the one at the back, turns and looks directly at you through the open window.","\n","^Not startled. Not scared. Just... looking. Their face is calm. They hold eye contact for a long moment.","\n","^Then they turn and walk on.","\n","ev","str","^That was strange. But you've heard that some guests are just like that.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Radio the floor manager.","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^Ask Bex about it at the next lull.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["\n","^You've seen tough customers before. The ones who come to prove they can't be scared. Arms crossed, smirking, unimpressed. This wasn't that. This person wasn't performing toughness. They were just... absent.","\n",{"->":"night_1.the_figure_appears"},{"#f":5}],"c-1":["\n","^You key the radio. \"Zone 2 Bravo. Last group, person in the back. No reaction. Something felt off.\"","\n","^Static. Then: \"Copy, Zone 2. Probably a repeat visitor. Don't worry about it.\"","\n",{"->":"night_1.the_figure_appears"},{"#f":5}],"c-2":["\n","^You lean out during the next gap. \"That last group. The person at the back.\"","\n","^Bex is quiet for a moment. \"What about them?\"","\n","^\"They looked at me. Through the window. No reaction at all.\"","\n","^\"Some people don't scare.\"","\n","^\"It wasn't that.\"","\n","^Bex doesn't respond.","\n",{"->":"night_1.the_figure_appears"},{"#f":5}]}],{"#f":1}],"the_figure_appears":[["^11:15 PM.","\n","^Between groups, you stretch your neck and roll your shoulders. The boo hole is cramped. Your knees are stiff from standing. The mask is damp with condensation from your breath.","\n","^You look down the corridor through the window slit, watching the fog drift.","\n","^Someone is standing in the corridor.","\n","^Not moving. Not approaching. Just standing at the far end, where the corridor curves. They're in full costume: black base layer, a mask you don't recognize. Not The Collapse's cracked skull design. Something older. Rougher. Like burlap pulled over a face.","\n","^They're facing you.","\n","^You wait for them to move, to do something, to walk a group through. But there are no guests. The corridor is empty. It's a gap between groups. Nobody should be out there except Bex, and Bex is at their position to your left, out of your line of sight.","\n","^The figure stands there. Ten seconds. Twenty.","\n","ev","str","^Radio Bex.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Step out of the boo hole for a closer look.","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^Stay still and watch.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["\n","ev",{"VAR?":"bex_relationship"},1,"+",{"VAR=":"bex_relationship","re":true},"/ev","^You key the radio to the zone channel. \"Bex. There's someone in my corridor. Far end, just standing there. Is that one of ours?\"","\n","^Two seconds of silence.","\n","^\"I don't see anyone.\"","\n","^You look again. The figure is still there.","\n","^\"End of the corridor. By the curve. They're in a mask I don't recognize.\"","\n","^A pause.","\n","^\"There's nobody scheduled past your position, Val. You're the last actor before the transition hallway.\"","\n",{"->":"night_1.figure_vanish"},{"#f":5}],"c-1":["\n","^You ease out of the alcove. The corridor stretches ahead of you, dimly lit, fog pooling on the floor. The figure is maybe forty feet away. You take a step toward them.","\n","^They don't move.","\n","^You take another step.","\n","^The ambient audio loops. The pickaxe sound. Dripping water. And underneath it, that hum. Louder down here than it was this afternoon.","\n",{"->":"night_1.figure_vanish"},{"#f":5}],"c-2":["\n","^You don't move. You watch through the slit. The figure doesn't move either. You try to make out details: height, build, anything. But the fog and the dim light flatten everything. They're just a shape. A silhouette that shouldn't be there.","\n",{"->":"night_1.figure_vanish"},{"#f":5}]}],{"#f":1}],"figure_vanish":[["^A group enters the corridor. You hear them coming: footsteps, whispers. The fog shifts.","\n","^You look back at the far end of the corridor.","\n","^The figure is gone.","\n","^Not walking away. Not stepping around the curve. Gone. The corridor is empty.","\n","^The group crosses your glow tape. Instinct takes over. You hit the window. You scream. They scream. Reset. Click.","\n","^But your hands are shaking.","\n","ev","str","^Finish the next few groups on autopilot.","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"night_1.the_shift_changes"},{"#f":5}]}],{"#f":1}],"the_shift_changes":[["^11:50 PM.","\n","^You're rattled, but you keep working. Window. Scream. Reset. The rhythm steadies you. It's mechanical now. Your body does the job while your mind cycles through what you saw.","\n","^A figure in a costume nobody assigned. Standing motionless. Watching you. Vanishing.","\n","^This is a haunted attraction. People are in costume everywhere. It could have been an actor from another zone cutting through. A manager doing a walkthrough. Someone testing a new mask.","\n","^You almost convince yourself.","\n","^Then the corridor changes.","\n","^Between groups, during a longer lull after midnight, you lean out of the boo hole to stretch. You look left, toward Bex's position.","\n","^The corridor is different.","\n","^Not dramatically. Not impossibly. But the timber support that was ten feet to your left is now further away. Twenty feet, maybe. And there's a doorway in the wall between your position and Bex's that wasn't there during the tour. A doorway with no door, just a dark opening.","\n","ev","str","^Walk to the doorway.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Radio Bex.","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^You remember what Bex said. The layout gets confusing after midnight. Stay in your zone.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["\n",{"->":"night_1.the_doorway"},{"#f":5}],"c-1":["\n","^\"Bex. Is there a doorway between our positions? In the left wall?\"","\n","^The radio hisses. Then: \"No.\"","\n","^\"I'm looking at one.\"","\n","^Silence. A long silence.","\n","^\"Stay in your hole, Val. Don't go through any doors that weren't there at the start of the shift.\"","\n","^The way they say it. Not confused. Not skeptical. Like this is advice they've had to give before.","\n",{"->":"night_1.post_midnight"},{"#f":5}],"c-2":["\n","^You pull back into the boo hole. You don't look at the doorway. The next group comes through and you hit the window and you scream and you do your job.","\n","^When you lean out again ten minutes later, the doorway is gone. The timber support is back where it was.","\n",{"->":"night_1.post_midnight"},{"#f":5}]}],{"#f":1}],"the_doorway":[["^You step into the corridor and walk to the doorway. Up close, it's rough stone. Not constructed. Carved, or maybe natural. The edges aren't clean. The air coming through it is warm and smells like copper.","\n","^Through the opening, you can see a narrow passage descending. No show lighting. No wiring. Just raw stone and darkness.","\n","^And the hum. Stronger here. Not just in your chest. In your teeth.","\n","ev","str","^Step through.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Look but don't enter.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["\n","^You take one step into the passage. The warmth wraps around you. The hum rises.","\n","^Then your radio crackles.","\n","^\"Zone 2 Bravo, we've got a group incoming. Return to your position.\" Floor manager. Routine voice. No urgency.","\n","^You step back out. The corridor is normal. Bex's timber support is where it should be. The doorway is still there. No. Wait.","\n","^It's gone.","\n","^You're standing in front of a solid stone wall.","\n","ev",{"VAR?":"erasure_level"},1,"+",{"VAR=":"erasure_level","re":true},"/ev",{"->":"night_1.post_midnight"},{"#f":5}],"c-1":["\n","^You stand at the threshold. The passage goes down. You can't see the bottom. The warm air pushes past you into the corridor, like breath from a mouth.","\n","^Your radio crackles. \"Group incoming, Zone 2.\"","\n","^You turn back. You return to your position. You don't look at the doorway again.","\n","^When the group has passed and you check, it's gone. Solid wall.","\n",{"->":"night_1.post_midnight"},{"#f":5}]}],{"#f":1}],"post_midnight":[["^The show runs until 2 AM.","\n","^The last two hours are a blur. Fewer groups, longer gaps. The energy in the attraction winds down. Your scream is hoarse. Your shoulder throbs. The edge of the mask has rubbed a raw line across the bridge of your nose.","\n","^Nothing else unusual happens. The corridor stays the way it should. No figure. No doorway. Just the job.","\n","^At 2:15, the house lights come on. The fog machines shut off. The ambient audio dies. The Hollows, in full fluorescent light, looks like what it is: a machine. Wiring. Plywood. Paint. The magic is gone. It's just a mine with props in it.","\n","^Bex appears next to you. They look the same as they did at 6 PM. Not tired. Not sweaty. Just present.","\n","^\"Good first night.\"","\n",["ev",{"^->":"night_1.post_midnight.0.12.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"Thanks. My shoulder's going to hate me tomorrow.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_1.post_midnight.0.13.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"I saw something.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_1.post_midnight.0.14.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"Does it always feel like that? After midnight?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"night_1.post_midnight.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.12.s"},[{"#n":"$r2"}],"\n","^\"Switch to your left hand for the window after midnight. Alternate the strain. You'll last longer.\"","\n",{"->":"night_1.post_shift_walk"},{"#f":5}],"c-1":["ev",{"^->":"night_1.post_midnight.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.13.s"},[{"#n":"$r2"}],"\n","ev",{"VAR?":"bex_relationship"},1,"+",{"VAR=":"bex_relationship","re":true},"/ev","^Bex's expression doesn't change. \"Yeah.\"","\n","^They don't ask what.","\n",{"->":"night_1.post_shift_walk"},{"#f":5}],"c-2":["ev",{"^->":"night_1.post_midnight.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.14.s"},[{"#n":"$r2"}],"\n","^Bex starts walking toward the break room. \"It always feels like something after midnight.\"","\n",{"->":"night_1.post_shift_walk"},{"#f":5}]}],{"#f":1}],"post_shift_walk":[["^You change out of costume in the break room. The other actors are winding down. Some are laughing, comparing scares, replaying the best reactions. A guy in a werewolf mask tells a story about a woman who punched him in the chest. \"Solid hit. Respect.\" Everyone laughs.","\n","^It feels normal. It feels like a job you've worked before: the post-shift decompression, the shared exhaustion, the camaraderie of people who just spent six hours screaming in the dark.","\n","^But you keep glancing at the corridor. The one that leads down to the lower levels. From here, in the break room light, it just looks like a hallway.","\n","^The other actors leave in ones and twos. Bex is gone. You didn't see them go.","\n","^Dale's office door is closed. The light is off.","\n","^The break room is empty.","\n","ev","str","^Now's your chance. Access the staff terminal.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^You're exhausted. Go back to the motel and regroup.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["\n",{"->":"night_1.employee_records"},{"#f":5}],"c-1":["\n","^You can barely keep your eyes open. You'll investigate tomorrow.","\n",{"->":"night_1.end_night_1"},{"#f":5}]}],{"#f":1}],"employee_records":["^There's a staff computer in the corner of the break room. Ancient desktop, logged into a shared account. A scheduling program, a time clock application, an internal messaging system. Basic stuff.","\n","^You check over your shoulder. The corridor is empty. The building is quiet except for the ventilation system and, underneath it, the hum.","\n","^You open the scheduling program. Employee directory. Search.","\n","^Mara Castillo. No results.","\n","^Elena Voss. No results.","\n","^You try a broader search. All employees hired in the past two months. A list comes up: twelve names. You recognize a few from tonight's briefing. Your name is there. Val Rowan, hired today.","\n","^No Mara. No Elena. No gap in the records where someone was removed. It's not that her file was deleted. It's like the system never knew she existed.","\n","ev",true,"/ev",{"VAR=":"employee_records_seen","re":true},{"->":".^.^.records_hub"},{"#f":1}],"records_hub":[["^The terminal is still open. The building is still quiet. For now.","\n","ev","str","^Check the messaging system.","/str",{"CNT?":".^.^.^.records_messages"},"!","/ev",{"*":".^.c-0","flg":21},"ev","str","^Search for deleted or archived records.","/str",{"CNT?":".^.^.^.records_files"},"!","/ev",{"*":".^.c-1","flg":21},"ev","str","^Look up Bex.","/str",{"CNT?":".^.^.^.records_bex"},"!","/ev",{"*":".^.c-2","flg":21},"ev","str","^Look up Dale.","/str",{"CNT?":".^.^.^.records_dale"},"!","/ev",{"*":".^.c-3","flg":21},"ev","str","^You've seen enough. Close out and leave.","/str",{"CNT?":".^.^.^.records_messages"},{"CNT?":".^.^.^.records_files"},"||",{"CNT?":".^.^.^.records_bex"},"||",{"CNT?":".^.^.^.records_dale"},"||","/ev",{"*":".^.c-4","flg":21},{"c-0":["\n",{"->":"night_1.records_messages"},{"#f":5}],"c-1":["\n",{"->":"night_1.records_files"},{"#f":5}],"c-2":["\n",{"->":"night_1.records_bex"},{"#f":5}],"c-3":["\n",{"->":"night_1.records_dale"},{"#f":5}],"c-4":["\n","^You clear the search history, close the programs, and step away from the terminal.","\n",{"->":"night_1.records_exit"},{"#f":5}]}],{"#f":1}],"records_messages":["^You open the internal messages. A shared inbox, mostly Dale sending shift reminders and schedule changes. You scroll back through three months of messages.","\n","^No mention of Mara. No mention of Elena. No mention of anyone leaving, being fired, or quitting. In three months of staffing a forty-person operation, not a single departure.","\n","^That's not normal.","\n",{"->":".^.^.records_hub"},{"#f":1}],"records_files":["^You poke around the file system. Temp folders, recycling bin, backup directories. You know what you're looking for: artifacts, fragments, anything that would indicate a record was removed.","\n","^Nothing. The database is clean. Too clean. Not scrubbed, but pristine, like it's never had an error, never had an edit, never had a correction.","\n","^No system that manages real humans looks like this.","\n",{"->":".^.^.records_hub"},{"#f":1}],"records_bex":["ev",true,"/ev",{"VAR=":"has_bex_file","re":true},"^You search for Bex. A single result: Bex. No last name. No hire date. The field is blank. Position: Rotating. Emergency contact: blank. Address: blank.","\n","^Every other employee has full records. Bex has a name and nothing else.","\n",{"->":".^.^.records_hub"},{"#f":1}],"records_dale":["ev",true,"/ev",{"VAR=":"has_dale_file","re":true},"^You search for Dale Ruskin. His file is immaculate.","\n","^Full name: Dale Arthur Ruskin. Position: General Manager. Hire date: March 3rd, 1998. The day The Hollows opened. Address: on-site staff housing. Emergency contact: HorrorCo Entertainment LLC, Corporate Office. No individual name. Salary: $187,000.","\n","^It's a lot of money for managing a haunted attraction in a town with one gas station.","\n","^You scroll down. Performance reviews. There are twenty-seven of them, one per year, going all the way back to 1998.","\n","^You open the most recent. \"Exceeds expectations. Dale continues to demonstrate exemplary leadership and operational excellence.\"","\n","^You open one from 2015. \"Exceeds expectations. Dale continues to demonstrate exemplary leadership and operational excellence.\"","\n","^Same. 2001. Same. 1999. Same. Word for word. Character for character.","\n","^You check his attendance record. No sick days. No vacation days. Not a single one. In twenty-seven years.","\n","^Either Dale Ruskin is the most dedicated employee in American history, or this file was written by something that doesn't understand what a real employment record looks like.","\n",{"->":".^.^.records_hub"},{"#f":1}],"records_exit":[["ev",{"VAR?":"dale_suspicion"},1,"+",{"VAR=":"dale_suspicion","re":true},"/ev","^You hear a sound from the corridor. Footsteps. Slow.","\n","^The break room door opens.","\n","^It's Dale. He glances at you.","\n","^\"Val!\"","\n","^\"Yeah. Just finishing up.\"","\n","^\"Building closes to staff at 3. Don't stay late.\" He holds the door open for you. It's not a suggestion.","\n","ev","str","^Leave.","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"night_1.end_night_1"},{"#f":5}]}],{"#f":1}],"end_night_1":[["^3 AM.","\n","^You walk back to the Mineshaft Inn under a sky full of stars. The desert air is cold and dry and clean. It feels like surfacing.","\n","^The mine entrance is dark behind you. No lights. No fog. No sound.","\n","^Except the hum. Faint now, almost below perception. But there. You realize you've been hearing it since you arrived. You'll hear it in your sleep, if you sleep.","\n","^Room 6. You lock the door. You sit on the bed.","\n","ev",{"VAR?":"priority"},"str","^find_mara","/str","==","/ev",[{"->":".^.b","c":true},{"b":["^ Mara was here. She worked here. She reported from inside this building. And now there's no record of her. Not deleted. Not hidden. Just... absent. Like she never was.",{"->":".^.^.^.18"},null]}],"nop","\n","ev",{"VAR?":"priority"},"str","^investigate_paranormal","/str","==","/ev",[{"->":".^.b","c":true},{"b":["^ The corridor changed. You saw it. A doorway that appeared and vanished. A figure that no one else saw. And underneath all of it, that hum. Something is down there.",{"->":".^.^.^.28"},null]}],"nop","\n","^You have questions. You don't have answers. But you have tomorrow.","\n","^You set your alarm for noon. You charge the burner phone on the nightstand.","\n","^You close your eyes.","\n","ev","str","^Day 2","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"day_2"},{"#f":5}]}],{"#f":1}],"#f":1}],"day_2":[{"->":".^.morning"},{"morning":[["^You wake up at noon. Your shoulder is stiff. Your throat is sore. Your nose has a raw stripe across the bridge from the mask.","\n","^Outside, the desert sun is high and white. Veinrock looks even smaller in daylight. Flat, bleached, empty.","\n","^You need towels. The ones in the room are thin and smell like dust. You walk to the motel office.","\n","^The owner is behind the counter. Same guy who checked you in. He looks up.","\n","^\"Help you?\"","\n",["ev",{"^->":"day_2.morning.0.10.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"Could I get some fresh towels for room 6?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_2.morning.0.11.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Morning.\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_2.morning.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.10.s"},[{"#n":"$r2"}],"\n","^He frowns. Looks at a clipboard.","\n","^\"Room 6? That room's vacant.\"","\n",{"->":"day_2.erasure_motel"},{"#f":5}],"c-1":["ev",{"^->":"day_2.morning.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.11.s"},[{"#n":"$r2"}],"\n","^He stares at you. Polite, blank, waiting. The way you'd look at a stranger.","\n","^\"We met yesterday. You checked me in. Room 6.\"","\n",{"->":"day_2.erasure_motel"},{"#f":5}]}],{"#f":1}],"erasure_motel":[["ev",{"VAR?":"erasure_level"},1,"+",{"VAR=":"erasure_level","re":true},"/ev","^He flips through the clipboard. Runs his finger down the page.","\n","^\"I don't have anyone in room 6. You sure you're at the right place?\" He chuckles. \"Not a lot of options in town, but maybe you're thinking of somewhere down the highway.\"","\n","^You're holding the key. You show it to him. Room 6.","\n","^He looks at it. Looks at you. Something flickers behind his eyes. Confusion, maybe. Or the edge of a memory that can't quite take shape.","\n","^\"Huh. Must have, uh... let me check the system.\"","\n","^He types something into an ancient computer. Squints at the screen.","\n","^\"Oh, here we go. Val Rowan. Room 6. Sorry about that. Don't know how I missed it.\" He laughs again, uneasy this time. \"Long nights.\"","\n","^He hands you two towels.","\n",["ev",{"^->":"day_2.erasure_motel.0.22.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"No problem.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_2.erasure_motel.0.23.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Has that happened before? Forgetting a guest?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_2.erasure_motel.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.22.s"},[{"#n":"$r2"}],"\n","^You take the towels. You walk back to room 6. You close the door.","\n","^He didn't recognize you. For a moment, you didn't exist in his records. Then you did.","\n",{"->":"day_2.day_2_plans"},{"#f":5}],"c-1":["ev",{"^->":"day_2.erasure_motel.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.23.s"},[{"#n":"$r2"}],"\n","^\"Can't say it has.\" He rubs the back of his neck. \"Probably just need more coffee. You have a good day now.\"","\n","^He's already turning away.","\n",{"->":"day_2.day_2_plans"},{"#f":5}]}],{"#f":1}],"day_2_plans":["^You stand in the room. Burner phone in hand.","\n","ev",{"VAR?":"priority"},"str","^find_mara","/str","==","/ev",[{"->":".^.b","c":true},{"b":["^ The motel owner forgot you. You've been here one night. Mara was here for ten days. If this happened to her too...",{"->":".^.^.^.10"},null]}],"nop","\n","ev",{"VAR?":"priority"},"str","^investigate_paranormal","/str","==","/ev",[{"->":".^.b","c":true},{"b":["^ The motel owner forgot you. You checked in less than thirty-six hours ago. Whatever is happening at The Hollows, it's not staying at The Hollows.",{"->":".^.^.^.20"},null]}],"nop","\n","^You have until 6 PM before your shift. Time to dig.","\n",{"->":".^.^.day_2_hub"},{"#f":1}],"day_2_hub":[["ev","str","^Go to Gloria's diner.","/str",{"CNT?":"day_2.day_2_gloria"},"!","/ev",{"*":".^.c-0","flg":21},"ev","str","^Look for a library or municipal office.","/str",{"CNT?":"day_2.day_2_library"},"!","/ev",{"*":".^.c-1","flg":21},"ev","str","^Call Silas.","/str",{"CNT?":"day_2.day_2_silas"},"!","/ev",{"*":".^.c-2","flg":21},"ev","str","^Head to The Hollows for your shift.","/str",{"CNT?":"day_2.day_2_gloria"},{"CNT?":"day_2.day_2_library"},"||",{"CNT?":"day_2.day_2_silas"},"||","/ev",{"*":".^.c-3","flg":21},{"c-0":["\n",{"->":"day_2.day_2_gloria"},{"#f":5}],"c-1":["\n",{"->":"day_2.day_2_library"},{"#f":5}],"c-2":["\n",{"->":"day_2.day_2_silas"},{"#f":5}],"c-3":["\n",{"->":"day_2.day_2_end"},{"#f":5}]}],{"#f":1}],"day_2_silas":[["ev",{"VAR?":"silas_trust"},1,"+",{"VAR=":"silas_trust","re":true},"/ev","^You dial the burner. It rings four times. That's new. He used to pick up in one or two.","\n","^\"Ward.\"","\n","^\"It's me. I need to report.\"","\n","^You tell him about Night 1. The figure in the corridor. The shifting layout. ","ev",{"VAR?":"employee_records_seen"},"/ev",[{"->":".^.b","c":true},{"b":["^ The employee records with no trace of Mara.",{"->":".^.^.^.17"},null]}],"nop","^ The motel owner forgetting you this morning.","\n","^Silence on the line. Not thoughtful silence. Empty silence, like the signal is struggling.","\n","^\"The erasure...\" His voice cuts out for a moment, then comes back. \"...consistent with what Mara described in her final reports. She said people in town started looking through her. Like she was becoming transparent.\"","\n",["ev",{"^->":"day_2.day_2_silas.0.24.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"That's what's happening to me?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_2.day_2_silas.0.25.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"What else did Mara say in those final reports?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_2.day_2_silas.0.26.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"You didn't tell me about this during the briefing.\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_2.day_2_silas.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.24.s"},[{"#n":"$r2"}],"\n","^\"I don't know. Maybe. She was there for ten days before it started. You're on day two.\" A pause. Static. \"It's accelerating.\"","\n",{"->":"day_2.silas_continued"},{"#f":5}],"c-1":["ev",{"^->":"day_2.day_2_silas.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.25.s"},[{"#n":"$r2"}],"\n","^\"She mentioned the hum. Said it was getting louder. She said she found a way into the lower levels but hadn't gone down yet. That was her last report.\"","\n",{"->":"day_2.silas_continued"},{"#f":5}],"c-2":["ev",{"^->":"day_2.day_2_silas.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.26.s"},[{"#n":"$r2"}],"\n","^A beat. When he speaks, his voice is careful.","\n","^\"I told you what I thought was relevant. I didn't want to bias your observations.\" Another beat. \"I should have told you.\"","\n","ev",{"VAR?":"silas_trust"},1,"+",{"VAR=":"silas_trust","re":true},"/ev",{"->":"day_2.silas_continued"},{"#f":5}]}],{"#f":1}],"silas_continued":["^\"Listen. I'm going to try to pull records on HorrorCo from our end. Corporate filings, property transfers, anything.\" The line crackles. \"But Val. The motel owner. If people are forgetting you already...\"","\n","^The signal drops to static for three full seconds.","\n","^\"...careful. Report again tomorrow.\"","\n","^The line goes dead. You're not sure if he hung up or if the call just stopped.","\n",{"->":".^.^.day_2_hub"},{"#f":1}],"day_2_gloria":["ev",{"VAR?":"day_1_gloria"},"/ev",[{"->":".^.b","c":true},{"b":["\n","^Gloria is behind the counter when you walk in. She glances up and, for just a moment, you think you see the same blankness the motel owner had. Then it clears.","\n","^\"You again.\" She pours you a coffee without asking. \"Sit down.\"","\n",{"->":".^.^.^.5"},null]}],[{"->":".^.b"},{"b":["\n","^The diner is called ALDRICH'S. Small, warm, mostly empty. Checkered floor, vinyl booths, a counter with stools. Hasn't been updated since the '80s.","\n","^The woman behind the counter is in her early sixties. She moves with careful precision. Sharp eyes. Her name tag reads GLORIA.","\n","^She sets a coffee down in front of you before you ask for one.","\n","^\"You're new.\"","\n","^It's not a question.","\n",["ev",{"^->":"day_2.day_2_gloria.4.b.11.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"I just started at The Hollows.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_2.day_2_gloria.4.b.12.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"I'm Val.\"",{"->":"$r","var":true},null]}],{"->":".^.^.^.5"},{"c-0":["ev",{"^->":"day_2.day_2_gloria.4.b.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.11.s"},[{"#n":"$r2"}],"\n","^Something crosses her face. Fast, then gone.","\n","^\"Another one.\"","\n","^\"My name is Val.\"","\n",{"->":"day_2.gloria_day_2_hub"},{"#f":5}],"c-1":["ev",{"^->":"day_2.day_2_gloria.4.b.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.12.s"},[{"#n":"$r2"}],"\n","^\"Gloria.\" She doesn't offer a handshake. \"You working up at the mine?\"","\n",{"->":"day_2.gloria_day_2_hub"},{"#f":5}]}]}],"nop","\n",{"#f":1}],"gloria_day_2_hub":[["ev","str","^Ask about the sinkhole.","/str",{"CNT?":"day_2.gloria_sinkhole"},"!","/ev",{"*":".^.c-0","flg":21},"ev","str","^Ask about HorrorCo.","/str",{"CNT?":"day_2.gloria_horrorco"},"!","/ev",{"*":".^.c-1","flg":21},"ev","str","^Ask about workers at The Hollows.","/str",{"CNT?":"day_2.gloria_workers"},"!","/ev",{"*":".^.c-2","flg":21},"ev","str","^Thank her and leave.","/str",{"CNT?":"day_2.gloria_sinkhole"},{"CNT?":"day_2.gloria_horrorco"},"||",{"CNT?":"day_2.gloria_workers"},"||","/ev",{"*":".^.c-3","flg":21},{"c-0":["\n",{"->":"day_2.gloria_sinkhole"},{"#f":5}],"c-1":["\n",{"->":"day_2.gloria_horrorco"},{"#f":5}],"c-2":["\n",{"->":"day_2.gloria_workers"},{"#f":5}],"c-3":["\n",{"->":"day_2.gloria_day_2_end"},{"#f":5}]}],{"#f":1}],"gloria_sinkhole":[["ev",{"VAR?":"day_1_gloria"},"/ev",[{"->":".^.b","c":true},{"b":["\n","^\"You told me yesterday your father owned the mine.\"","\n","^Gloria wraps her hands around her mug. \"I did.\"","\n","^\"You said a sinkhole doesn't breathe.\"","\n","^She's quiet for a long moment. Studying you. Deciding something.","\n",{"->":".^.^.^.5"},null]}],[{"->":".^.b"},{"b":["\n","^\"What do you know about the mine? Before it was The Hollows?\"","\n","^Gloria sets down the pot. Leans against the counter.","\n","^\"My father owned the Aldrich Silver Mine. I was nine years old when the ground opened up and took it.\"","\n",{"->":".^.^.^.5"},null]}],"nop","\n","^\"The official report said geological instability. Subsurface void collapse. Natural causes.\" She says the words like she's reading from a document she's memorized against her will.","\n","^\"But I was standing in the yard when it happened. I heard it. Everyone heard it. The ground shook and then there was a sound.\" She pauses. \"Not a collapse sound. Not rock breaking.\"","\n",["ev",{"^->":"day_2.gloria_sinkhole.0.11.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"What kind of sound?\"",{"->":"$r","var":true},null]}],"ev","str","^Wait.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["ev",{"^->":"day_2.gloria_sinkhole.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.11.s"},[{"#n":"$r2"}],"\n",{"->":"day_2.gloria_opened"},{"#f":5}],"c-1":["\n",{"->":"day_2.gloria_opened"},{"#f":5}]}],{"#f":1}],"gloria_opened":["^\"It opened.\" Her voice drops. \"That's the only word for it. The mine didn't collapse. It opened. Like something underneath had been pushing up for a long time and finally got through.\"","\n","^She looks at her hands.","\n","^\"Forty-eight men went down that shaft. The rescue teams went in three hours later. They found the shaft. They found the equipment. They found lunch pails sitting on rocks where the men had set them down.\"","\n","^\"But no bodies?\"","\n","^\"No bodies. No bones. No blood. Nothing. Forty-eight men, gone. Like they'd been erased.\"","\n","ev",{"VAR?":"gloria_trust"},1,"+",{"VAR=":"gloria_trust","re":true},"/ev","ev",true,"/ev",{"VAR=":"has_gloria_testimony","re":true},{"->":".^.^.gloria_day_2_hub"},{"#f":1}],"gloria_horrorco":[["^\"What do you know about the company that built The Hollows?\"","\n","^Gloria's mouth tightens.","\n","^\"HorrorCo.\" She says it like a curse. \"They showed up in '98. Bought the mine, bought the land around it, bought half the buildings in town. Paid cash. Didn't negotiate.\"","\n","^\"Who did they buy from?\"","\n","^\"The county. The land had been in foreclosure for twenty years. Nobody wanted it. A mine that swallowed forty-eight men doesn't attract buyers.\" She pauses. \"Until it did.\"","\n",["ev",{"^->":"day_2.gloria_horrorco.0.10.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"Did you ever meet anyone from HorrorCo?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_2.gloria_horrorco.0.11.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Why did you stay?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_2.gloria_horrorco.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.10.s"},[{"#n":"$r2"}],"\n","^\"Just Dale. He came into the diner the week they started construction. Introduced himself. Big smile. Told me they were going to put Veinrock back on the map.\" Her expression is flat. \"He looked exactly the same then as he does now. Twenty-seven years ago. Same face. Same smile. Same polo shirt.\"","\n","ev",{"VAR?":"gloria_trust"},1,"+",{"VAR=":"gloria_trust","re":true},"/ev",{"->":"day_2.gloria_day_2_hub"},{"#f":5}],"c-1":["ev",{"^->":"day_2.gloria_horrorco.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.11.s"},[{"#n":"$r2"}],"\n","^\"I left. After the mine. My mother took me to Reno. I grew up there. Went to school. Got married. Got divorced.\" She shrugs. \"But I kept coming back. Every few years, I'd drive out. Just to look. I can't explain it.\"","\n","^She stares at her coffee.","\n","^\"When HorrorCo opened the diner back up, they offered it to me. I don't know how they knew I existed. I don't know how they had my phone number. But they called, and I came back. And I've been here since.\"","\n",{"->":"day_2.gloria_day_2_hub"},{"#f":5}]}],{"#f":1}],"gloria_workers":[["^\"The people who work at The Hollows. Do they ever come in here?\"","\n","^\"Some of them. The new ones, mostly. They come in for a few weeks, excited, chatty. Then they come in less. Then they stop.\"","\n",["ev",{"^->":"day_2.gloria_workers.0.4.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"Where do they go?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_2.gloria_workers.0.5.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Have you noticed anyone disappear?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_2.gloria_workers.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.4.s"},[{"#n":"$r2"}],"\n","^\"Nowhere. They're still here. You'll see them walking to their shifts, walking back. But they stop coming in. Stop talking.\"","\n",{"->":"day_2.gloria_workers_more"},{"#f":5}],"c-1":["ev",{"^->":"day_2.gloria_workers.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.5.s"},[{"#n":"$r2"}],"\n","^Gloria is quiet for a while.","\n","^\"There was a young woman. A few weeks back. Came in a few times. Dark hair, sharp eyes. Ordered the same thing every time: black coffee and the meatloaf.\"","\n","^Your stomach drops.","\n",{"->":"day_2.gloria_mara"},{"#f":5}]}],{"#f":1}],"gloria_workers_more":[["^\"And some of them have been there since the beginning. Since '98. They don't age right. They don't change. Bex...\" She stops herself.","\n",["ev",{"^->":"day_2.gloria_workers_more.0.2.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"You know Bex?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_2.gloria_workers_more.0.3.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"What do you mean, they don't age right?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_2.gloria_workers_more.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.2.s"},[{"#n":"$r2"}],"\n","^\"Everyone in Veinrock knows Bex. Or knows of them. They've been at The Hollows as long as Dale has. Maybe longer, if that's possible.\" She leans forward. \"I don't think Bex knows how long they've been there. I think they've lost count. Or lost the ability to count.\"","\n","ev",{"VAR?":"gloria_trust"},1,"+",{"VAR=":"gloria_trust","re":true},"/ev",{"->":"day_2.gloria_day_2_hub"},{"#f":5}],"c-1":["ev",{"^->":"day_2.gloria_workers_more.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.3.s"},[{"#n":"$r2"}],"\n","^\"I mean Dale Ruskin looked fifty years old in 1998 and he looks fifty years old now. I mean Bex looked twenty-five when the place opened and they look twenty-five today.\" She sets her jaw. \"I'm sixty-one. I know what aging looks like. Those people aren't doing it.\"","\n","ev",{"VAR?":"gloria_trust"},1,"+",{"VAR=":"gloria_trust","re":true},"/ev",{"->":"day_2.gloria_day_2_hub"},{"#f":5}]}],{"#f":1}],"gloria_mara":[["ev",{"VAR?":"priority"},"str","^find_mara","/str","==","/ev",[{"->":".^.b","c":true},{"b":["^ Your heart rate spikes. That's Mara. That's her.",{"->":".^.^.^.8"},null]}],"nop","\n","^\"Do you remember her name?\"","\n","^Gloria thinks. Frowns. Shakes her head slowly.","\n","^\"I should. She told me. She sat right where you're sitting. We talked.\" Gloria stares at the counter like she's trying to see through it. \"I can picture her face. I can hear her voice. But the name is just... gone.\"","\n",["ev",{"^->":"day_2.gloria_mara.0.16.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"Her name was Mara.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_2.gloria_mara.0.17.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Did she say anything about the mine?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_2.gloria_mara.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.16.s"},[{"#n":"$r2"}],"\n","^Gloria looks at you sharply. \"How do you know that?\"","\n","^\"Because I'm here looking for her.\"","\n","^A long silence. Gloria's eyes are wet. Not crying. Just the strain of trying to hold onto something that's slipping away.","\n","^\"She asked me the same kinds of questions you're asking. About the mine. About HorrorCo.\" Her voice is barely above a whisper. \"And then she stopped coming in. And I forgot she existed until you just said her name.\"","\n","ev",{"VAR?":"gloria_trust"},2,"+",{"VAR=":"gloria_trust","re":true},"/ev","ev",{"VAR?":"mara_clues"},1,"+",{"VAR=":"mara_clues","re":true},"/ev",{"->":"day_2.gloria_day_2_hub"},{"#f":5}],"c-1":["ev",{"^->":"day_2.gloria_mara.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.17.s"},[{"#n":"$r2"}],"\n","^\"She was interested in the history. The sinkhole. Asked a lot of questions.\" Gloria pauses. \"Smart questions. Like she already knew some of the answers and was testing mine.\"","\n","ev",{"VAR?":"priority"},"str","^find_mara","/str","==","/ev",[{"->":".^.b","c":true},{"b":["^ That sounds like Mara.",{"->":".^.^.^.17"},null]}],"nop","\n","ev",{"VAR?":"mara_clues"},1,"+",{"VAR=":"mara_clues","re":true},"/ev",{"->":"day_2.gloria_day_2_hub"},{"#f":5}]}],{"#f":1}],"gloria_day_2_end":[["^Gloria clears your coffee cup.","\n","ev",{"VAR?":"gloria_trust"},3,">=","/ev",[{"->":".^.b","c":true},{"b":["^ \"Val.\" She says your name like she's committing it to memory. \"Be careful in that mine. And come back tomorrow. I have something to show you.\"",{"->":".^.^.^.8"},null]}],"nop","\n","ev",{"VAR?":"gloria_trust"},3,"<","/ev",[{"->":".^.b","c":true},{"b":["^ \"You should eat before your shift. You look thin.\" She slides a menu across the counter. It's not warmth, exactly. But it's close.",{"->":".^.^.^.16"},null]}],"nop","\n",["ev",{"^->":"day_2.gloria_day_2_end.0.18.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str",{"VAR?":"gloria_trust"},3,">=","/ev",{"*":".^.^.c-0","flg":19},{"s":["^\"I will.\"",{"->":"$r","var":true},null]}],"ev","str","^Eat and leave.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["ev",{"^->":"day_2.gloria_day_2_end.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.18.s"},[{"#n":"$r2"}],"\n",{"->":"day_2.day_2_hub"},{"#f":5}],"c-1":["\n","^The meatloaf is","ev",{"VAR?":"day_1_gloria"},"/ev",[{"->":".^.b","c":true},{"b":["^ still",{"->":".^.^.^.6"},null]}],"nop","^ decent.","\n",{"->":"day_2.day_2_hub"},{"#f":5}]}],{"#f":1}],"day_2_library":["^The Veinrock Public Library is a single room in the back of the municipal building, which is itself a converted house. The sign out front still says HENDERSON RESIDENCE underneath the county seal.","\n","^Inside: four shelves of donated paperbacks, a microfiche reader that probably hasn't been turned on since the '90s, and a desk where a part-time clerk sits reading a magazine. She doesn't look up when you enter.","\n","^The local history section is half a shelf. But it's enough.","\n",{"->":".^.^.library_hub"},{"#f":1}],"library_hub":[["ev","str","^Look for coverage of the 1973 sinkhole.","/str",{"CNT?":"day_2.library_sinkhole"},"!","/ev",{"*":".^.c-0","flg":21},"ev","str","^Look for records of HorrorCo's purchase.","/str",{"CNT?":"day_2.library_horrorco"},"!","/ev",{"*":".^.c-1","flg":21},"ev","str","^Check the town census or directories.","/str",{"CNT?":"day_2.library_census"},"!","/ev",{"*":".^.c-2","flg":21},"ev","str","^You've seen enough. Leave.","/str",{"CNT?":"day_2.library_sinkhole"},{"CNT?":"day_2.library_horrorco"},"||",{"CNT?":"day_2.library_census"},"||","/ev",{"*":".^.c-3","flg":21},{"c-0":["\n",{"->":"day_2.library_sinkhole"},{"#f":5}],"c-1":["\n",{"->":"day_2.library_horrorco"},{"#f":5}],"c-2":["\n",{"->":"day_2.library_census"},{"#f":5}],"c-3":["\n",{"->":"day_2.library_end"},{"#f":5}]}],{"#f":1}],"library_sinkhole":[["ev",true,"/ev",{"VAR=":"has_sinkhole_history","re":true},"^You find a bound collection of the Veinrock Gazette, which apparently ran from 1924 to 1974. The final year has only three issues.","\n","^The sinkhole is front page of the June 15, 1973 edition. ALDRICH MINE COLLAPSE KILLS 48. The article describes the event in dry, factual language. Geological instability. Emergency crews dispatched. No survivors recovered.","\n","^But there's a detail in the third paragraph that stops you.","\n","^\"Rescue teams reported that the main shaft, previously measured at 340 feet in depth, now extended beyond the reach of available sounding equipment. Foreman Bill Husted described the shaft as 'bottomless,' though county geologists attributed this to instrument malfunction.\"","\n","^The mine got deeper when it collapsed.","\n","ev","str","^Keep reading.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Note the depth detail and move on.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["\n","^The next issue, dated three weeks later, is mostly obituaries. Forty-eight names. Forty-eight families. The town's entire working-age male population.","\n","^The final issue, September 1974, is a single page. VEINROCK POST OFFICE TO CLOSE. The last sentence reads: \"No forwarding addresses were provided.\"","\n",{"->":"day_2.library_hub"},{"#f":5}],"c-1":["\n","^You write it down. 340 feet, then bottomless. Mines don't get deeper when they collapse. They get shallower.","\n",{"->":"day_2.library_hub"},{"#f":5}]}],{"#f":1}],"library_horrorco":[["ev",true,"/ev",{"VAR=":"has_horrorco_filing","re":true},"^The municipal records are in a filing cabinet by the desk. The clerk doesn't seem to care that you're going through them.","\n","^You find the property transfer. HorrorCo Entertainment LLC purchased the Aldrich Mine property and surrounding 200 acres from Nye County on February 12, 1998. Purchase price: $1.2 million, paid in full.","\n","^The filing includes HorrorCo's articles of incorporation. You check the date.","\n","^Incorporated in Delaware. June 22, 1973.","\n","^One week after the sinkhole.","\n","^HorrorCo was created seven days after forty-eight men vanished into the earth. Then it waited twenty-five years to come back and build on top of the hole.","\n","ev","str","^Look for any names on the incorporation documents.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Note the dates and move on.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["\n","^The incorporator is listed as \"M. Aldrich, Registered Agent.\" Aldrich, like the mine. ","ev",{"CNT?":"day_2.day_2_gloria"},{"VAR?":"day_1_gloria"},"||","/ev",[{"->":".^.b","c":true},{"b":["^ Like Gloria's family. But Gloria said her family left town after the collapse. Who is M. Aldrich?",{"->":".^.^.^.8"},null]}],"nop","^ ","ev",{"CNT?":"day_2.day_2_gloria"},"!",{"VAR?":"day_1_gloria"},"!","&&","/ev",[{"->":".^.b","c":true},{"b":["^ The same name as the mine. A relative of the original owners? Someone else entirely?",{"->":".^.^.^.18"},null]}],"nop","\n","ev",{"VAR?":"mara_clues"},1,"+",{"VAR=":"mara_clues","re":true},"/ev",{"->":"day_2.library_hub"},{"#f":5}],"c-1":["\n","^You write it down. Incorporated one week after the sinkhole. Purchased the land twenty-five years later. Whatever HorrorCo is, it's been planning this for a long time.","\n",{"->":"day_2.library_hub"},{"#f":5}]}],{"#f":1}],"library_census":[["ev",true,"/ev",{"VAR=":"has_census_data","re":true},"^You find a shelf of county directories going back to the 1960s. You pull a few.","\n","^1970 directory: Veinrock, population 203. Four pages of names, addresses, occupations. A living town.","\n","^1975 directory: Veinrock, population 0. The entry is a single line. \"No registered residents.\"","\n","^1999 directory: Veinrock, population 47. You scan the names. Dale Ruskin. Bex (no surname). Gloria Aldrich. The rest you don't recognize. Most list their employer as HorrorCo Entertainment.","\n","^You cross-reference with the 2010 directory. Population: 51. Many of the same names. Dale Ruskin. Bex. Gloria. A few additions. No deletions.","\n","^The 2020 directory. Population: 54. Same core names. Same addresses. A few more additions.","\n","^In two decades, the town has gained seven people and lost zero.","\n","^Nobody has died. Nobody has moved away. In a town of fifty people, over two decades, not a single person has left.","\n","ev",{"CNT?":"day_2.day_2_silas"},"/ev",[{"->":".^.b","c":true},{"b":["^ Except the ones who vanished.",{"->":".^.^.^.24"},null]}],"nop","\n","ev","str","^Check if any of the current residents match the 1970 names.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Note it and move on.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["\n","^You compare the lists. None of the 1999 names appear in 1970. The old Veinrock and the new Veinrock share nothing except the name and Gloria Aldrich.","\n",{"->":"day_2.library_hub"},{"#f":5}],"c-1":["\n","^You write it down. A town where nobody leaves and nobody dies. That's not a town. That's something else.","\n",{"->":"day_2.library_hub"},{"#f":5}]}],{"#f":1}],"library_end":["^You put the records back where you found them. The clerk is still reading her magazine. She hasn't looked at you once.","\n","^At the door, you glance back. The clerk is watching you. She looks away quickly.","\n","ev",true,"/ev",{"VAR=":"library_clerk_check","re":true},"ev",{"VAR?":"dale_suspicion"},1,"+",{"VAR=":"dale_suspicion","re":true},"/ev","^Or maybe she was never looking. Maybe you imagined it.","\n",{"->":".^.^.day_2_hub"},{"#f":1}],"day_2_end":[["^Late afternoon. The sun is dropping. The temperature is already falling. The desert cools fast.","\n","^You walk to The Hollows. The parking lot is starting to fill. A line is forming at the ticket booth. Families, couples, groups of teenagers. People who drove hours to be here. People who want to be scared.","\n","^You pass them on the way to the staff entrance. One of them, a kid maybe ten years old, watches you walk by.","\n","^\"Are you one of the monsters?\" he asks.","\n",["ev",{"^->":"day_2.day_2_end.0.8.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"Not yet.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_2.day_2_end.0.9.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Only at night.\"",{"->":"$r","var":true},null]}],"ev","str","^Just smile and keep walking.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["ev",{"^->":"day_2.day_2_end.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.8.s"},[{"#n":"$r2"}],"\n","^The kid grins. His mother pulls him back into line.","\n",{"->":"night_2"},{"#f":5}],"c-1":["ev",{"^->":"day_2.day_2_end.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.9.s"},[{"#n":"$r2"}],"\n","^The kid's grin falters for a second, then comes back wider.","\n",{"->":"night_2"},{"#f":5}],"c-2":["\n",{"->":"night_2"},{"#f":5}]}],{"#f":1}],"#f":1}],"night_2":[{"->":".^.costume_room_2"},{"costume_room_2":[["^The costume room is loud tonight. Music from someone's phone. Two actors arguing about the best way to do a drop scare. The woman with the ribcage piece is back, adjusting the lung mechanism with a screwdriver.","\n","^Bex is at their usual station. They nod when they see you.","\n","^\"You're in a new zone tonight. The Shaft. Dale wants to see how you handle movement.\"","\n",["ev",{"^->":"night_2.costume_room_2.0.6.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"What kind of movement?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_2.costume_room_2.0.7.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Why the move?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_2.costume_room_2.0.8.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"Are you in The Shaft too?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"night_2.costume_room_2.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.6.s"},[{"#n":"$r2"}],"\n","^\"Stalker walk. You follow groups through the corridor. Match their pace, stay behind them, don't make a sound until they notice you. When they run, you stop. Reset. Wait for the next group.\"","\n",{"->":"night_2.costume_2_continued"},{"#f":5}],"c-1":["ev",{"^->":"night_2.costume_room_2.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.7.s"},[{"#n":"$r2"}],"\n","^\"Dale rotates new hires through the zones. Wants to see what you're good at.\" Bex pauses. \"Also, The Shaft is short-staffed tonight.\"","\n",{"->":"night_2.costume_2_continued"},{"#f":5}],"c-2":["ev",{"^->":"night_2.costume_room_2.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.8.s"},[{"#n":"$r2"}],"\n","^\"No. I'm in The Collapse. Your old spot.\" Something in the way they say it. Like it's always been their spot. Like you were borrowing it.","\n",{"->":"night_2.costume_2_continued"},{"#f":5}]}],{"#f":1}],"costume_2_continued":["^The costume is the same mining jumpsuit, same mask, same greasepaint. Bex reapplies the prosthetic gash on your forehead, faster this time.","\n","^\"The Shaft is different from The Collapse. Longer corridors. Higher ceilings. You've got more room to work, but the guests can see further ahead, so you need to be smart about where you reveal.\"","\n","^They hand you a pair of soft-soled boots.","\n","^\"Swap these in. Your regular shoes are too loud on the stone. In The Shaft, silence is the whole game.\"","\n",{"->":".^.^.shaft_briefing"},{"#f":1}],"shaft_briefing":[[["ev",{"^->":"night_2.shaft_briefing.0.0.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str",{"CNT?":"night_2.shaft_technique"},"!","/ev",{"*":".^.^.c-0","flg":19},{"s":["^\"Any tips for the stalker walk?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_2.shaft_briefing.0.1.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str",{"CNT?":"night_2.shaft_layout"},"!","/ev",{"*":".^.^.c-1","flg":19},{"s":["^\"What's the layout?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_2.shaft_briefing.0.2.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str",{"CNT?":"night_2.shaft_partner"},"!","/ev",{"*":".^.^.c-2","flg":19},{"s":["^\"Am I working with a partner?\"",{"->":"$r","var":true},null]}],"ev","str","^Ready.","/str","/ev",{"*":".^.c-3","flg":20},{"c-0":["ev",{"^->":"night_2.shaft_briefing.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.0.s"},[{"#n":"$r2"}],"\n",{"->":"night_2.shaft_technique"},{"#f":5}],"c-1":["ev",{"^->":"night_2.shaft_briefing.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.1.s"},[{"#n":"$r2"}],"\n",{"->":"night_2.shaft_layout"},{"#f":5}],"c-2":["ev",{"^->":"night_2.shaft_briefing.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.2.s"},[{"#n":"$r2"}],"\n",{"->":"night_2.shaft_partner"},{"#f":5}],"c-3":["\n",{"->":"night_2.run_through_2"},{"#f":5}]}],{"#f":1}],"shaft_technique":["^\"Start far back. Twenty feet minimum. Match their speed exactly. Most groups walk slow in the dark, so you walk slow. Don't speed up until they do.\"","\n","^Bex demonstrates, taking three steps across the costume room floor. Completely silent. Their weight rolls from heel to toe. No impact. No scuff.","\n","^\"When the last person in the group notices you, freeze. Don't move. Half the time they'll convince themselves they imagined it and keep walking. Then you start again. Closer.\"","\n","^\"What if they freak out?\"","\n","^\"They will. When they run, you stop. You don't chase. Let the panic do the work. By the time they hit the next scare zone, they're already wired.\"","\n",{"->":".^.^.shaft_briefing"},{"#f":1}],"shaft_layout":["^\"One long main corridor, about a hundred and fifty feet. Curved slightly, so guests can't see the end from the entrance. There are three alcoves along the right wall where you can stage before stepping out. Your start position is alcove one, near the entrance.\"","\n","^Bex traces the layout on the makeup counter with their finger.","\n","^\"Guests enter from the south end. They walk through. You follow. At the north end, they turn left into the next zone. You peel off into the reset corridor and loop back to alcove one.\"","\n","^\"How long is the loop?\"","\n","^\"About forty-five seconds if you walk fast.\"","\n",{"->":".^.^.shaft_briefing"},{"#f":1}],"shaft_partner":[["^\"You're solo in The Shaft. There's a boo hole actor at the far end, but you won't interact with them. You're the only stalker.\"","\n",["ev",{"^->":"night_2.shaft_partner.0.2.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"Solo on my second night?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_2.shaft_partner.0.3.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Got it.\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"night_2.shaft_partner.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.2.s"},[{"#n":"$r2"}],"\n","^\"You'll be fine. The walk is instinct once you get the timing down. And if you're stuck, just stand still. Standing still in the dark is scary enough.\"","\n",{"->":"night_2.shaft_briefing"},{"#f":5}],"c-1":["ev",{"^->":"night_2.shaft_partner.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.3.s"},[{"#n":"$r2"}],"\n",{"->":"night_2.shaft_briefing"},{"#f":5}]}],{"#f":1}],"run_through_2":[["^6:45 PM. Pre-show briefing. Dale does the speech. Same words. Same clipboard. Same smile.","\n","^\"Make it real, people.\"","\n","^The actors disperse. You catch a glimpse of the guy from last night, the one in the werewolf getup who told the punching story. He's at a station across the room, pulling on the same suit.","\n","^You raise a hand. A wave, a nod, the kind of casual acknowledgment between coworkers on night two.","\n","^He looks at you. Blank. Friendly, but blank. The way you look at someone you've never met. He gives a polite half-wave back and turns to his mirror.","\n","ev","str","^Maybe he just didn't recognize you in makeup.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Play it cool. Note it.","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^Walk over and reintroduce yourself.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["\n","^That's possible. You look different in costume. Everyone does. It's only your second night. You barely spoke. There's no reason he'd remember you specifically.","\n","^That's probably all it is.","\n",{"->":"night_2.enter_shaft"},{"#f":5}],"c-1":["\n","^You file it away. The motel owner this morning. Now this. Maybe it's nothing. You're new. People don't always register new faces right away.","\n","^But that's twice today someone has looked right through you.","\n",{"->":"night_2.enter_shaft"},{"#f":5}],"c-2":["\n","^You walk to his station. \"Hey. Val. We met last night after the shift. You told the story about the woman who punched you.\"","\n","^He squints at you. Thinks. Then his face lights up.","\n","^\"Oh, right! Yeah, sorry. Didn't recognize you with the...\" He gestures at your makeup. \"Long nights, you know?\"","\n","^It sounds right. It probably is right.","\n","^Later, you see him chatting with a floor manager, gesturing in your direction. Small building. Word travels.","\n","ev",{"VAR?":"dale_suspicion"},1,"+",{"VAR=":"dale_suspicion","re":true},"/ev",{"->":"night_2.enter_shaft"},{"#f":5}]}],{"#f":1}],"enter_shaft":[["^The Shaft is deeper in the upper level than The Collapse. The ceilings are higher here, the walls further apart. The corridor stretches ahead of you in a gentle curve, lit in a faint blue-white wash that makes the fog look like smoke. The set dressing is sparse: timber supports, a few mining tools bolted to the walls, a rusted ore cart shoved into a recess. The design relies on the space itself. The emptiness. The length of the corridor and the darkness at the far end.","\n","^Your start position is alcove one: a shallow cutout in the right wall, about four feet deep. Enough to hide in if you press flat against the stone.","\n","^You test the acoustics. Clap once. The sound travels a long way down the corridor, bouncing off the stone, dying slowly. In here, every footstep matters.","\n","^You swap into the soft-soled boots. Step. Step. Nothing. Good.","\n","^Radio crackle. \"Doors open in two. Positions, everyone.\"","\n","^You press into alcove one. You wait.","\n","ev","str","^Showtime.","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"night_2.first_stalk"},{"#f":5}]}],{"#f":1}],"first_stalk":[["^The first group enters The Shaft at 8:04 PM.","\n","^Five people. Mid-twenties, mixed group. They're bunched together, moving cautiously. One of them has a hand on the person in front of them. The fog curls around their ankles. Their flashlight (phone, you realize, against the rules but nobody enforces it) throws a shaky beam that doesn't reach more than ten feet.","\n","^They pass alcove one. They don't see you.","\n","^You count to three. Then you step out.","\n","^The soft boots are silent on the stone. You match their pace. Slow. Deliberate. About fifteen feet behind the last person.","\n","^The corridor is long. They walk. You walk. The fog drifts between you and them. The ambient audio murmurs: dripping water, the groan of timber, a faint wind that doesn't exist.","\n","^The person at the back of the group glances over their shoulder.","\n","^You freeze.","\n","^They stare into the darkness behind them. The blue-white wash makes the fog glow. You're standing perfectly still, fifteen feet back, a dead miner in the haze.","\n","^\"There's something back there,\" they whisper.","\n","^\"Stop it,\" someone else says.","\n","^They turn forward. They keep walking. Faster now.","\n","^You wait two seconds. Then you start again. Closer. Ten feet.","\n","^The back person looks again. This time they see you clearly.","\n","^The scream is immediate. The group bolts. Their footsteps slap off the stone, echoing, overlapping. They round the curve and disappear into the next zone.","\n","^You stand in the empty corridor. Fog. Silence. The ambient audio loops.","\n","^You turn and walk back to alcove one.","\n","ev","str","^Reset. Wait. Do it again.","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"night_2.stalk_rhythm"},{"#f":5}]}],{"#f":1}],"stalk_rhythm":[["^The stalker walk is a different discipline than the boo hole. In the boo hole, you were a mechanism. Trigger, fire, reset. In The Shaft, you're a presence. You have to feel the group's energy, adjust your distance, control your breath. Move too fast and you break the tension. Move too slow and they never notice you.","\n","^After about ten groups, you start to find it.","\n","^The soft boots help. You learn to step on the exhale, to shift your weight without lifting your feet fully off the stone. You learn to read the groups by their silhouettes: the nervous ones (hunched, tight cluster, hands on shoulders) and the brave ones (spread out, talking, daring each other). The nervous ones you let get halfway down the corridor before you step out. The brave ones you start early and close distance fast.","\n","^One group, a pair of teenage boys, doesn't scare at all. They see you and laugh. \"Bro, he's just standing there.\" You don't react. You just follow. Silent. Matching their pace exactly. By the time they reach the curve, they're not laughing anymore.","\n","^This is the job. Patient. Physical. Precise. Your legs ache from the controlled pace. Your jaw is tight from clenching against the urge to breathe too loud. Sweat pools under the mask.","\n","^By 10 PM, you've done maybe thirty groups. You're in the rhythm.","\n","ev","str","^Keep working.","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"night_2.shaft_figure"},{"#f":5}]}],{"#f":1}],"shaft_figure":[["^10:40 PM.","\n","^A lull. Two minutes between groups. You're standing in alcove one, rolling your neck, flexing your toes in the soft boots.","\n","^You look down the corridor toward the far end. The blue-white wash fades to nothing around the curve. The fog is thin right now, pooling low.","\n","^Someone is standing in the corridor.","\n","^Not at the far end this time. Maybe thirty feet away. In the middle of the passage, directly in your sightline.","\n","^Same as last night. Black base layer. A mask that doesn't belong to any zone: rough, shapeless, like burlap stitched over a face. Standing perfectly still.","\n","^But tonight you're close enough to see what you couldn't at distance. The base layer is wrong. Not the stiff, fresh-issue black that The Hollows hands out. The fabric is worn thin. Faded unevenly, like it's been underground for much longer than any shift. The seams are fraying. There's a mineral crust along the hems, as if it got wet and dried and got wet again dozens of times.","\n","^Someone has been wearing this for weeks. Maybe longer.","\n","ev",{"VAR?":"mara_clues"},0,"==","/ev",[{"->":".^.b","c":true},{"b":["^ That's all you can make out. The light is too low for more detail.",{"->":".^.^.^.22"},null]}],"nop","\n","ev",{"VAR?":"mara_clues"},1,"==","/ev",[{"->":".^.b","c":true},{"b":["^ Something about the figure's build nags at you. The height. The posture. You can't place it, but there's a familiarity you can't explain. Like a face you've seen in a photograph but never in person.",{"->":".^.^.^.30"},null]}],"nop","\n","ev",{"VAR?":"mara_clues"},2,">=","/ev",[{"->":".^.b","c":true},{"b":["^ The figure's height. The way they hold their shoulders, slightly forward, like someone who's used to leaning over a desk. You've seen that posture before. In a photograph Silas showed you. Mara Castillo was 5'6\" and left-handed and stood exactly like that.",{"->":".^.^.^.38"},null]}],"nop","\n","ev","str","^Step toward them.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Radio the floor manager.","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^Stay in the alcove. Watch.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["\n","^You leave the alcove. One step. Two. The figure doesn't move. The fog curls between you.","\n","^You're close enough now to see that the burlap mask has no eye holes. The fabric is unbroken. Whoever is under there can't see.","\n","^But they're facing you.","\n",{"->":"night_2.figure_vanish_2"},{"#f":5}],"c-1":["\n","^You key the radio. \"Shaft stalker. I've got someone in my corridor. Thirty feet out. Not a scheduled actor.\"","\n","^Static. Then: \"Copy. We'll check it out.\"","\n","^Nobody comes.","\n",{"->":"night_2.figure_vanish_2"},{"#f":5}],"c-2":["\n","^You press against the stone and watch. The figure stands in the corridor. You count. Ten seconds. Twenty. Thirty. They don't shift their weight. They don't breathe visibly. They just stand.","\n","^The mineral crust on the fabric. It's not random. There's a pattern to the staining, concentrated at the hands, the knees, the hem. Whoever this is has been kneeling. Crawling. Working in the dark for a long time.","\n",{"->":"night_2.figure_vanish_2"},{"#f":5}]}],{"#f":1}],"figure_vanish_2":[["^Footsteps from the entrance. A new group. You hear them whispering, shuffling into The Shaft.","\n","^You look back at the figure.","\n","^Gone. Same as last night. Not departed. Just absent.","\n","^The group comes around the first bend. You step out. You follow. You do your job.","\n","^But your hands aren't shaking this time. Whatever this is, it's consistent. It follows a pattern. It appears in the gaps. It watches. It leaves.","\n","^You're not scared anymore. You're paying attention.","\n","ev","str","^Continue the shift.","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"night_2.maintenance_discovery"},{"#f":5}]}],{"#f":1}],"maintenance_discovery":[["^11:20 PM.","\n","^Between groups, you're in alcove three. The last staging point before the curve. You've been cycling through all three alcoves to vary your reveal points.","\n","^Alcove three is the deepest. You press against the back wall and feel something behind you that isn't stone. Metal. A grate.","\n","^You turn and look. It's a maintenance access panel, about two feet square, bolted into the wall at floor level. One of the bolts is missing. Two others are loose, the threads stripped. The fourth holds, barely.","\n","^Warm air pushes through the gaps in the grate. And the hum. Louder through the grate than anywhere else in The Shaft.","\n","^A group enters the corridor. You step out, do the walk, send them running. Loop back.","\n","^The grate is still there. You crouch and test the remaining bolt with your fingers. It turns.","\n","ev","str","^Pull the grate off and go through.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Leave it for now. You know it's here.","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^Radio Bex about it.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["\n","^You wait for a gap between groups. Radio chatter suggests a slowdown at the entrance. You have maybe three minutes.","\n","^You pull the last bolt free. The grate swings open on a corroded hinge you didn't see. The opening is tight. You set the grate against the wall, lower yourself to the ground, and squeeze through.","\n",{"->":"night_2.restricted_passage"},{"#f":5}],"c-1":["\n","^You memorize the location. Alcove three, The Shaft. You have a way in. But not tonight. Not in the middle of a shift with floor managers on the radio.","\n",{"->":"night_2.shaft_late"},{"#f":5}],"c-2":["\n","ev",{"VAR?":"bex_relationship"},1,"+",{"VAR=":"bex_relationship","re":true},"/ev","^You switch to a private channel. \"Bex. There's a maintenance access in alcove three of The Shaft. Grate's loose. Warm air coming through.","ev",{"VAR?":"bex_hum"},"/ev",[{"->":".^.b","c":true},{"b":["^ The hum is stronger here.",{"->":".^.^.^.12"},null]}],"nop","^\"","\n","^A long pause.","\n","^\"Don't go through it, Val.\"","\n","^\"Why?\"","\n","^\"Because you might not come back to the same corridor.\"","\n","^Another pause.","\n","^\"Or the same night.\"","\n",{"->":"night_2.maintenance_choice_2"},{"#f":5}]}],{"#f":1}],"maintenance_choice_2":[["ev","str","^Go through anyway.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Heed the warning. Leave it for now.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["\n","^You wait for a gap between groups. You pull the bolt. The grate swings open. You squeeze through.","\n",{"->":"night_2.restricted_passage"},{"#f":5}],"c-1":["\n",{"->":"night_2.shaft_late"},{"#f":5}]}],{"#f":1}],"restricted_passage":[["ev",true,"/ev",{"VAR=":"visited_restricted_passage","re":true},"^The passage is narrow. Not a vent. An old maintenance tunnel, maybe an air shaft for the original mine. The walls are rough stone, unfinished, no concrete or plywood. Your shoulders brush both sides. You half-crawl, half-shuffle forward.","\n","^The warm air is stronger here. It smells like copper and ozone. The hum fills the space, vibrating through the stone and into your palms where they press against the ground.","\n","^After about twenty feet, the passage opens up. You can stand. Barely.","\n","^You're in a section of tunnel that is not part of The Hollows.","\n","^No show lighting. No speakers. No fog machines. Just bare stone and a single emergency light mounted on the wall, casting a yellow circle on the ground. It buzzes faintly.","\n","^The floor is rough. Nobody has been through here recently. Except...","\n","ev","str","^Look around.","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"night_2.restricted_findings"},{"#f":5}]}],{"#f":1}],"restricted_findings":["^The walls.","\n","^Someone has carved symbols into the stone. Not scratched casually. Carved, with deliberation and force. They cover a section of wall about three feet wide, arranged in concentric arcs. Angular, geometric, nothing you recognize. Some are simple: intersecting lines, circles with radiating points. Others are dense and layered, shapes nested inside shapes. They have a structure to them, a grammar, even if you can't read it.","\n","^The stone around the carvings is smooth, almost polished, as if the symbols have been traced by hand over and over again. Or as if the stone itself has responded to them.","\n","^Below the symbols, scratched in a different hand, rougher, more recent: a single word. OPEN.","\n",{"->":".^.^.notebook_page"},{"#f":1}],"notebook_page":[["^Something on the ground catches your eye. A piece of paper, folded twice, wedged into a crack where the wall meets the floor. It's been here a while. The edges are soft with moisture.","\n","^You pull it out and unfold it.","\n","^It's a page from a notebook. The paper is gridded. The handwriting is small, precise, and partially smudged. Most of the text is in a shorthand you recognize immediately: Order notation. Mara's.","\n","ev",{"VAR?":"mara_clues"},1,"+",{"VAR=":"mara_clues","re":true},"/ev","^But the page isn't mostly text. It's a diagram. A copy of the symbols on the wall, painstakingly reproduced in hard pencil. She's drawn them arranged in their concentric arcs, same as the carvings, but on the page she's added annotations: small arrows connecting repeating elements, question marks next to symbols she couldn't identify, circles around patterns she thought were significant.","\n","^At the center of the diagram: a small, simple drawing. A circle with lines radiating downward from it. It takes you a moment to realize what it is.","\n","^A mine shaft opening. Viewed from above.","\n","^In the margin, in English, three notes in Mara's handwriting:","\n","^\"Found on wall in deep rooms. Repeated seven times.\"","\n","^\"Not decorative. Functional?\"","\n","^\"The symbols match the patterns in the stone around the\"","\n","^The sentence stops. The bottom of the page is torn.","\n","^She found these same symbols somewhere else first: the deep rooms. Then she found her way down here and found them again. She was mapping them. Comparing them.","\n","ev","str","^Pocket the page.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Study it for another moment.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["\n","ev",true,"/ev",{"VAR=":"has_notebook_page","re":true},"^You fold it carefully and tuck it inside your jumpsuit. This is evidence. Mara was here. Mara found these symbols. Mara was trying to understand them.","\n","ev",{"VAR?":"priority"},"str","^find_mara","/str","==","/ev",[{"->":".^.b","c":true},{"b":["^ She was this close. She made it further than you have. And then she stopped.",{"->":".^.^.^.15"},null]}],"nop","\n",{"->":"night_2.restricted_door"},{"#f":5}],"c-1":["\n","ev",true,"/ev",{"VAR=":"has_notebook_page","re":true},"^The symbols aren't random. Even without understanding them, you can see a structure. They repeat in sequences. They scale in size as they get closer to the center, as if describing something that narrows. Something that descends.","\n","^You pocket the page.","\n",{"->":"night_2.restricted_door"},{"#f":5}]}],{"#f":1}],"restricted_door":[["^The tunnel continues past the carved wall. You follow it for another ten feet.","\n","^It ends at a door.","\n","^Not a steel security door like the ones upstairs. A wooden door, old, heavy, set into a stone frame. The wood is dark and swollen with moisture. An iron handle, black with oxidation.","\n","^The door is warm. You hold your palm an inch from the surface. The heat radiates outward, steady, like a living thing on the other side is pressing against it.","\n","^The hum is loudest here. Not just in your chest and your teeth now. In your vision. The edges of the yellow light seem to pulse with it.","\n","ev","str","^Try the handle.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Don't touch it.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["\n","^The handle is warm to the touch. You grip it. Turn.","\n","^It doesn't move. Locked, or jammed, or held shut by something.","\n","^You press your ear against the wood. Through the door, underneath the hum, you hear something. Faint. Rhythmic. It could be machinery. It could be breathing. It could be footsteps, far below, going down.","\n",{"->":"night_2.leave_restricted"},{"#f":5}],"c-1":["\n","^Everything in you wants to try that handle. And something else in you, something older than curiosity, is telling you not to.","\n","^You stand in front of the door for ten seconds. The warmth washes over you. The hum fills the tunnel.","\n","^Then you turn around.","\n",{"->":"night_2.leave_restricted"},{"#f":5}]}],{"#f":1}],"leave_restricted":[["^Your radio crackles. Muffled through the stone, but audible.","\n","^\"All zones, we're in final push. Groups are still coming. Positions, everyone.\"","\n","^You need to get back.","\n","^You move through the maintenance tunnel, faster now. Squeeze through the grate. Pull it closed behind you. The bolt won't hold, but it sits in place well enough.","\n","^Alcove three. You press flat against the wall. Your heart is pounding. Your hands smell like copper from the stone.","\n","^A group enters the corridor. You step out. You follow.","\n","ev","str","^Finish the shift.","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"night_2.shaft_late"},{"#f":5}]}],{"#f":1}],"shaft_late":["^The last stretch of the shift is mechanical. You do the walk. You match the pace. You freeze. They scream. You reset.","\n","ev",{"CNT?":".^.^.restricted_passage"},"/ev",[{"->":".^.b","c":true},{"b":["^ But your mind is in the tunnel behind the grate. The symbols on the wall. The diagram. The door. The warmth.",{"->":".^.^.^.6"},null]}],"nop","\n","ev",{"CNT?":".^.^.restricted_passage"},"/ev",[{"->":".^.b","c":true},{"b":["^ Mara was down there. She found the symbols. She was documenting them, analyzing them, trying to determine if they were functional. She was doing exactly what you would have done.",{"->":".^.^.^.12"},null]}],"nop","\n","ev",{"CNT?":".^.^.restricted_passage"},"/ev",[{"->":".^.b","c":true},{"b":["^ And then she was gone.",{"->":".^.^.^.18"},null]}],"nop","\n","ev",{"CNT?":".^.^.restricted_passage"},"!","/ev",[{"->":".^.b","c":true},{"b":["^ But your mind keeps drifting to the grate in alcove three. The warm air. The hum. Whatever is behind that wall, it's close. You can feel it.",{"->":".^.^.^.25"},null]}],"nop","\n","^The show ends at 2 AM. House lights up. Fog off. Silence.","\n",{"->":".^.^.post_shift_2"},{"#f":1}],"post_shift_2":[["^The break room is quiet tonight. Fewer actors lingering. People are tired. The weekend rush takes a toll.","\n","^You change out of costume. Scrub the greasepaint off. Your face is raw.","\n","^Bex is at their station, removing their own makeup. They don't look at you.","\n","ev",{"CNT?":".^.^.^.restricted_passage"},"/ev",[{"->":".^.b","c":true},{"b":["\n","^You want to tell Bex what you found. The symbols. The diagram. The door. But something stops you. Bex told you not to go through the grate. If they know you did, what happens?","\n",{"->":".^.^.^.10"},null]}],"nop","\n","ev","str","^Tell Bex what you found.","/str",{"CNT?":".^.^.^.restricted_passage"},"/ev",{"*":".^.c-0","flg":21},"ev","str","^Keep it to yourself for now.","/str",{"CNT?":".^.^.^.restricted_passage"},"/ev",{"*":".^.c-1","flg":21},"ev","str","^Head out.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["\n","ev",true,"/ev",{"VAR=":"post_shift_2_tell_bex","re":true},"ev",{"VAR?":"bex_relationship"},1,"+",{"VAR=":"bex_relationship","re":true},"/ev","^You sit down next to them. \"I went through the grate.\"","\n","^Bex's hand stops mid-wipe. They don't look at you. A long silence.","\n","^\"What did you find?\"","\n","^\"Symbols carved into the wall. A page from a notebook. A door.\"","\n","^Bex's hand drops to the counter. They stare at the wall of the break room. Not at you.","\n","^\"The concentric ones.\" Not a question. \"I used to know what they...\" They stop. Start again. \"There was a reason I...\" They stop again. Their jaw works. Something behind their eyes reaching for a shelf that isn't there anymore.","\n","^\"Did you open the door?\"","\n","^\"It was locked.\"","\n","^Bex exhales. You're not sure if it's relief.","\n","^\"Don't go back down there, Val.\" Their voice is quiet. \"Please.\"","\n","^It's the first time they've said please about anything.","\n",{"->":"night_2.end_night_2"},{"#f":5}],"c-1":["\n","ev",true,"/ev",{"VAR=":"post_shift_2_keep_quiet","re":true},"ev",{"VAR?":"bex_relationship"},1,"-",{"VAR=":"bex_relationship","re":true},"/ev","^You don't mention the grate. You don't mention the tunnel. You sit and clean your makeup in silence.","\n","^Bex glances at you once. Their eyes drop to your hands. You realize too late that your fingers are still orange-brown from the copper dust on the tunnel walls.","\n","^Bex looks away. They don't say anything.","\n",{"->":"night_2.end_night_2"},{"#f":5}],"c-2":["\n",{"->":"night_2.end_night_2"},{"#f":5}]}],{"#f":1}],"end_night_2":[["^3 AM.","\n","^The walk back to the motel. Stars. Cold air. The mine entrance dark and still behind you.","\n","^The hum. It's louder now than last night. Or you're more attuned to it. You can't tell the difference and it might not matter.","\n","^Room 6. Door locked. Shades drawn.","\n","ev",{"VAR?":"has_notebook_page"},"/ev",[{"->":".^.b","c":true},{"b":["^ You take out Mara's notebook page and lay it on the nightstand. The diagram. The symbols. The torn edge where her thought was cut short.",{"->":".^.^.^.12"},null]}],"nop","\n","ev",{"VAR?":"has_notebook_page"},"/ev",[{"->":".^.b","c":true},{"b":["^ \"The symbols match the patterns in the stone around the\"",{"->":".^.^.^.18"},null]}],"nop","\n","ev",{"VAR?":"has_notebook_page"},"/ev",[{"->":".^.b","c":true},{"b":["^ Around the what? The portal? The door? The shaft itself?",{"->":".^.^.^.24"},null]}],"nop","\n","ev",{"VAR?":"priority"},"str","^find_mara","/str","==","/ev",[{"->":".^.b","c":true},{"b":["^ Mara was in that tunnel. She was doing the work. She was close to something. And then the work stopped and so did she. You're following her footsteps. You need to make sure they don't lead to the same place.",{"->":".^.^.^.34"},null]}],"nop","\n","ev",{"VAR?":"priority"},"str","^investigate_paranormal","/str","==","/ev",[{"->":".^.b","c":true},{"b":["^ Symbols copied from the deep rooms. A door that radiates heat. The pieces are starting to connect, but the picture they're forming isn't one you recognize yet.",{"->":".^.^.^.44"},null]}],"nop","\n","^You set your alarm for noon.","\n","ev","str","^Day 3","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"day_3"},{"#f":5}]}],{"#f":1}],"#f":1}],"day_3":[{"->":".^.morning_3"},{"morning_3":[["^You wake up at noon. Or you try to.","\n","^The alarm goes off. You reach for the nightstand. The burner phone is there.","\n","^But the room is wrong.","\n","^The bed is made. Not slept-in-and-you-got-up made. Hotel made. Tight corners, crisp fold, a mint on the pillow. Your bag, which you left open on the chair, is zipped and standing by the door. The shades you drew shut are open. The bathroom has been cleaned. Fresh towels on the rack. Your toothbrush is gone.","\n","^Someone came in while you slept and reset the room. Or the room reset itself.","\n","ev",{"VAR?":"erasure_level"},1,"+",{"VAR=":"erasure_level","re":true},"/ev","^You check the nightstand drawer. Your notebook is still there, written in Order shorthand. The burner phone still works. ","ev",{"VAR?":"has_notebook_page"},"/ev",[{"->":".^.b","c":true},{"b":["^ Mara's page is still in your hand, where you fell asleep holding it.",{"->":".^.^.^.21"},null]}],"nop","\n","^But everything else. The lived-in evidence of a person staying in this room. Gone.","\n","^You walk to the office. The motel owner looks up. This time he recognizes you, but barely. His eyes take a moment to focus, like you're a word on the tip of his tongue.","\n","^\"Room 6. Right. You need something?\"","\n",["ev",{"^->":"day_3.morning_3.0.29.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"Did housekeeping come through my room?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_3.morning_3.0.30.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Never mind.\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_3.morning_3.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.29.s"},[{"#n":"$r2"}],"\n","^He frowns. \"We don't have housekeeping. Haven't for years.\"","\n",{"->":"day_3.morning_3_continued"},{"#f":5}],"c-1":["ev",{"^->":"day_3.morning_3.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.30.s"},[{"#n":"$r2"}],"\n",{"->":"day_3.morning_3_continued"},{"#f":5}]}],{"#f":1}],"morning_3_continued":["^You stand in the parking lot. The sun is high. The mine entrance squats at the end of the road.","\n","ev",{"VAR?":"erasure_level"},3,">=","/ev",[{"->":".^.b","c":true},{"b":["^ Three days. The motel owner, the werewolf guy, and now the room itself. You're not just being forgotten. The physical traces of your presence are disappearing.",{"->":".^.^.^.8"},null]}],"nop","\n","ev",{"VAR?":"erasure_level"},3,"<","/ev",[{"->":".^.b","c":true},{"b":["^ The room was cleaned. Your things were packed. As if you'd checked out. As if you were already gone.",{"->":".^.^.^.16"},null]}],"nop","\n",{"->":".^.^.day_3_hub"},{"#f":1}],"day_3_hub":[["ev","str","^Go to Gloria's. She said she had something to show you.","/str",{"CNT?":"day_3.day_3_gloria"},"!",{"VAR?":"gloria_trust"},3,">=","&&","/ev",{"*":".^.c-0","flg":21},"ev","str","^Go to the diner.","/str",{"CNT?":"day_3.day_3_gloria"},"!",{"VAR?":"gloria_trust"},3,"<","&&","/ev",{"*":".^.c-1","flg":21},"ev","str","^Call Silas.","/str",{"CNT?":"day_3.day_3_silas"},"!","/ev",{"*":".^.c-2","flg":21},"ev","str","^Walk the town. Clear your head.","/str",{"CNT?":"day_3.day_3_walk"},"!","/ev",{"*":".^.c-3","flg":21},"ev","str","^Head to The Hollows for your shift.","/str","/ev",{"*":".^.c-4","flg":20},{"c-0":["\n",{"->":"day_3.day_3_gloria"},{"#f":5}],"c-1":["\n",{"->":"day_3.day_3_gloria_low"},{"#f":5}],"c-2":["\n",{"->":"day_3.day_3_silas"},{"#f":5}],"c-3":["\n",{"->":"day_3.day_3_walk"},{"#f":5}],"c-4":["\n",{"->":"day_3.day_3_end"},{"#f":5}]}],{"#f":1}],"day_3_silas":["^You dial. Six rings. Each one stretches longer than the last. You're about to hang up when the line connects.","\n","^Static. Then, distantly, Silas's voice. Like he's talking from the bottom of a well.","\n","^\"...Ward.\"","\n","^\"Silas. It's me.\"","\n","^\"Val.\" A pause. Crackling. \"...harder to reach you. The signal...\"","\n","^You tell him about Night 2. ","ev",{"VAR?":"has_notebook_page"},"/ev",[{"->":".^.b","c":true},{"b":["^ The maintenance tunnel, the symbols, Mara's notebook page.",{"->":".^.^.^.15"},null]}],"nop","^ ","ev",{"VAR?":"has_notebook_page"},"!","/ev",[{"->":".^.b","c":true},{"b":["^ The Shaft, the figure appearing closer.",{"->":".^.^.^.22"},null]}],"nop","^ The motel room resetting itself this morning.","\n","ev",{"VAR?":"silas_trust"},4,">=","/ev",[{"->":".^.b","c":true},{"b":["^ The static clears. Just for a moment, like Silas is pushing through it by sheer force of will.",{"->":".^.^.^.31"},null]}],"nop","\n","ev",{"VAR?":"silas_trust"},4,">=","/ev",[{"->":".^.b","c":true},{"b":["^ \"Listen. I found something. The Order's archives. There's a file on the Aldrich Mine predating the sinkhole. One of our field agents investigated the site in 1971. Two years before the collapse.\"",{"->":".^.^.^.39"},null]}],"nop","\n","ev",{"VAR?":"silas_trust"},4,">=","/ev",[{"->":".^.b","c":true},{"b":["^ Your pulse quickens. \"What did they find?\"",{"->":".^.^.^.47"},null]}],"nop","\n","ev",{"VAR?":"silas_trust"},4,">=","/ev",[{"->":".^.b","c":true},{"b":["^ \"The miners had been reporting anomalies for months. Warm air from below. Equipment malfunctioning. And sounds. A hum.\" His voice is strained, fighting the static. \"The agent's report describes carvings in the deepest tunnels. Symbols. He sketched a few of them. Val, the report says they were consistent with containment sigils. Whoever carved them wasn't worshipping something. They were keeping something shut.\" ",["ev","visit",1,"seq","/ev","ev","du",0,"==","/ev",{"->":".^.s0","c":true},"nop",{"s0":["pop","^ has_portal_mechanics = true",{"->":".^.^.11"},null],"#f":5}],"^ ",{"->":".^.^.^.55"},null]}],"nop","\n","ev",{"VAR?":"silas_trust"},4,">=","/ev",[{"->":".^.b","c":true},{"b":["^ \"The agent recommended sealing the lower shaft. The Order filed the report and... nothing. No follow-up. Two years later, forty-eight men died.\"",{"->":".^.^.^.63"},null]}],"nop","\n","ev",{"VAR?":"silas_trust"},4,">=","/ev",[{"->":".^.b","c":true},{"b":["^ The static surges.",{"->":".^.^.^.71"},null]}],"nop","\n","ev",{"VAR?":"silas_trust"},4,">=","/ev",[{"->":".^.b","c":true},{"b":["^ \"The symbols Mara found. If they're the same ones... the portal isn't new. It's been down there for a long time. Someone tried to contain it. And in 1973, the containment failed.\"",{"->":".^.^.^.79"},null]}],"nop","\n","ev",{"VAR?":"silas_trust"},4,"<","/ev",[{"->":".^.b","c":true},{"b":["^ The static is worse than yesterday. You catch fragments.",{"->":".^.^.^.87"},null]}],"nop","\n","ev",{"VAR?":"silas_trust"},4,"<","/ev",[{"->":".^.b","c":true},{"b":["^ \"...records on HorrorCo... nothing... shell company goes back...\"",{"->":".^.^.^.95"},null]}],"nop","\n","ev",{"VAR?":"silas_trust"},4,"<","/ev",[{"->":".^.b","c":true},{"b":["^ \"Silas, I can barely hear you.\"",{"->":".^.^.^.103"},null]}],"nop","\n","ev",{"VAR?":"silas_trust"},4,"<","/ev",[{"->":".^.b","c":true},{"b":["^ \"...be careful... the erasure is... accelerating...\"",{"->":".^.^.^.111"},null]}],"nop","\n","^The line dies. Not a click. Not a hang-up. The signal just stops, like a light going out.","\n","ev",{"VAR?":"silas_trust"},4,">=","/ev",[{"->":".^.b","c":true},{"b":["^ You sit with what he told you. Containment sigils. Someone tried to seal the portal before, and it failed. The symbols aren't decoration. They're a lock. A broken one.",{"->":".^.^.^.121"},null]}],"nop","\n",{"->":".^.^.day_3_hub"},{"#f":1}],"day_3_gloria":[["^Gloria is behind the counter. When you walk in, she looks at you. Really looks. Not the flickering half-recognition of the past two days. She's expecting you.","\n","^\"Sit down. Lock the door.\"","\n","^You lock the diner door. She flips the sign from OPEN to CLOSED.","\n","^From under the counter, she produces a shoebox. Old, battered, held shut with a rubber band. She sets it in front of you.","\n","^\"That woman. The one you said was named Mara.\"","\n","^\"You remember?\"","\n","^\"I wrote it down.\" She holds up a napkin with MARA in shaky block letters. \"After you told me yesterday. I wrote it down and I put it in my pocket and every time I felt the name slipping, I looked at it.\"","\n","^She opens the shoebox.","\n","^\"She left this. Last time she was in here. Tucked it under the booth when she thought I wasn't looking. I found it after she stopped coming in. I didn't know what it was. I almost threw it out. But something told me to keep it.\"","\n","^Inside the box: a small digital voice recorder. Black, pocket-sized, the kind the Order issues for field work. And three folded pages of notebook paper, covered in Mara's handwriting.","\n","ev","str","^Pick up the recorder.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Read the pages first.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["\n",{"->":"day_3.mara_recorder"},{"#f":5}],"c-1":["\n",{"->":"day_3.mara_pages"},{"#f":5}]}],{"#f":1}],"mara_recorder":["^You press play.","\n","^Mara's voice. Low, steady, the careful cadence of someone making a report they might not get to file.","\n","^\"Day eight. I've confirmed access to the lower levels through a maintenance shaft on the mid-level. The symbols are everywhere down here. Carved into the stone, not painted. Old. Much older than the mine.\"","\n","^A pause. The hum is audible in the background. Louder than you've ever heard it.","\n","^\"The attraction isn't just built on top of something. It's built to feed something. The fear. The guests' fear. It's not a byproduct. It's the product. Every scream, every panic response, every spike of adrenaline. It all goes down. Into the portal.\"","\n","ev",true,"/ev",{"VAR=":"has_mara_recording","re":true},"ev",{"VAR?":"mara_clues"},1,"+",{"VAR=":"mara_clues","re":true},"/ev","^Another pause. When she speaks again, her voice is different. Quieter.","\n","^\"I've seen something in the deep rooms. A figure. It stands in the corridor and watches me. I don't think it's a person. I think it's what's left of someone after the portal takes them. A residue. An echo.\"","\n","ev",{"VAR?":"priority"},"str","^find_mara","/str","==","/ev",[{"->":".^.b","c":true},{"b":["^ You grip the recorder tighter. She's describing exactly what you've seen. The figure. The one that might be her.",{"->":".^.^.^.32"},null]}],"nop","\n","^\"Day nine. The erasure is accelerating. Gloria almost didn't recognize me today. My name was missing from the schedule. I'm running out of time.\"","\n","^The recording clicks. Silence.","\n","^\"Day ten. I've found the door. The real one. Below everything. I'm going through tomorrow.\"","\n","^That's the last entry.","\n",{"->":".^.^.mara_reveal_continued"},{"#f":1}],"mara_pages":["^The pages are dense with Mara's handwriting. Order shorthand mixed with English, diagrams in the margins. You scan them quickly.","\n","^Page one: a map. Rough, hand-drawn, showing the layout of The Hollows across all three levels. She's marked the restricted doors, the maintenance shafts, the stairways between levels. At the bottom, below the deep rooms, she's drawn a large circle with a question mark inside it. The portal.","\n","^Page two: notes on the symbols. She's categorized them into three types. The first she calls \"containment\" glyphs: they appear around the portal and seem designed to limit it. The second she calls \"feeding\" glyphs: these appear in the scare zones and seem to channel energy downward. The third she calls \"opening\" glyphs: she found these only in the deepest tunnels, and she believes they were carved to widen the portal.","\n","^\"Someone is deliberately opening it wider. The containment is being undermined from inside.\"","\n","^Page three: a timeline. She's mapped the disappearances against the expansion of The Hollows. Every time a new scare zone was added, someone vanished within the following month. The attraction isn't just feeding the portal. It's growing it.","\n","ev",true,"/ev",{"VAR=":"has_mara_pages","re":true},"ev",{"VAR?":"mara_clues"},1,"+",{"VAR=":"mara_clues","re":true},"/ev","^At the bottom of the third page, a final note:","\n","^\"If I don't come back, give this to whoever comes looking for me. They will come. The Order doesn't leave people behind.\"","\n","ev",{"VAR?":"priority"},"str","^find_mara","/str","==","/ev",[{"->":".^.b","c":true},{"b":["^ She wrote that for you. She knew someone would follow her. She was counting on it.",{"->":".^.^.^.32"},null]}],"nop","\n",{"->":".^.^.mara_reveal_continued"},{"#f":1}],"mara_reveal_continued":[["ev","str","^Now read the pages.","/str",{"CNT?":"day_3.mara_recorder"},{"CNT?":"day_3.mara_pages"},"!","&&","/ev",{"*":".^.c-0","flg":21},"ev","str","^Now listen to the recorder.","/str",{"CNT?":"day_3.mara_pages"},{"CNT?":"day_3.mara_recorder"},"!","&&","/ev",{"*":".^.c-1","flg":21},"ev","str","^You've seen enough.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["\n",{"->":"day_3.mara_pages_after"},{"#f":5}],"c-1":["\n",{"->":"day_3.mara_recorder_after"},{"#f":5}],"c-2":["\n",{"->":"day_3.gloria_day_3_response"},{"#f":5}]}],{"#f":1}],"mara_pages_after":["ev",true,"/ev",{"VAR=":"has_mara_pages","re":true},"^You unfold the pages. A hand-drawn map of all three levels, with the portal marked at the bottom. Notes categorizing the symbols into three types: containment, feeding, and opening. A timeline connecting new scare zones to disappearances.","\n","^At the bottom: \"If I don't come back, give this to whoever comes looking for me.\"","\n",{"->":".^.^.gloria_day_3_response"},{"#f":1}],"mara_recorder_after":["ev",true,"/ev",{"VAR=":"has_mara_recording","re":true},"^You press play. Mara's voice, steady and careful. She describes the attraction feeding fear to the portal. A figure watching her in the deep rooms. The erasure accelerating. A door she plans to go through.","\n","^The last entry is Day 10. Then nothing.","\n",{"->":".^.^.gloria_day_3_response"},{"#f":1}],"gloria_day_3_response":[["^Gloria is watching you.","\n","^\"Is she dead?\"","\n",["ev",{"^->":"day_3.gloria_day_3_response.0.4.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"I don't know.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_3.gloria_day_3_response.0.5.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"I don't think it's that simple.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_3.gloria_day_3_response.0.6.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"I'm going to find out.\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_3.gloria_day_3_response.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.4.s"},[{"#n":"$r2"}],"\n","^\"But you think she might be.\"","\n","^\"I think she went somewhere she couldn't come back from.\"","\n","^Gloria is quiet for a long time.","\n",{"->":"day_3.gloria_day_3_continued"},{"#f":5}],"c-1":["ev",{"^->":"day_3.gloria_day_3_response.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.5.s"},[{"#n":"$r2"}],"\n","^Gloria looks at you steadily. \"Things die or they don't. What's not simple?\"","\n","^\"I think the mine takes people somewhere. I don't know if it's death.\"","\n",{"->":"day_3.gloria_day_3_continued"},{"#f":5}],"c-2":["ev",{"^->":"day_3.gloria_day_3_response.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.6.s"},[{"#n":"$r2"}],"\n","ev",{"VAR?":"gloria_trust"},1,"+",{"VAR=":"gloria_trust","re":true},"/ev","^Gloria studies your face. Whatever she's looking for, she finds it.","\n",{"->":"day_3.gloria_day_3_continued"},{"#f":5}]}],{"#f":1}],"gloria_day_3_continued":[["^\"My father's name was Martin Aldrich.\" She says it carefully. \"M. Aldrich.\"","\n","ev",{"VAR?":"has_horrorco_filing"},"/ev",[{"->":".^.b","c":true},{"b":["^ The name on the incorporation documents. M. Aldrich, Registered Agent. HorrorCo was filed under her father's name. One week after he died in the sinkhole.",{"->":".^.^.^.6"},null]}],"nop","\n","^\"After the collapse, my mother found papers in his desk. Engineering surveys, geological reports, things he'd brought home from the mine. But some of them weren't engineering documents. They were older. Hand-copied from something else. Symbols.\"","\n","^She pauses.","\n","^\"I was nine. I didn't understand what they were. My mother burned most of them. She said they were cursed. But I kept a few pages. I hid them in a book.\"","\n",["ev",{"^->":"day_3.gloria_day_3_continued.0.14.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"Do you still have them?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_3.gloria_day_3_continued.0.15.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"The symbols on those pages. Were they the same as the ones in the mine?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_3.gloria_day_3_continued.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.14.s"},[{"#n":"$r2"}],"\n","^\"I have one page. I'll show you tomorrow. I need to find it first. It's been... a long time since I looked at it.\" Her hands are shaking slightly.","\n","ev",{"VAR?":"gloria_trust"},1,"+",{"VAR=":"gloria_trust","re":true},"/ev",{"->":"day_3.gloria_day_3_end"},{"#f":5}],"c-1":["ev",{"^->":"day_3.gloria_day_3_continued.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.15.s"},[{"#n":"$r2"}],"\n","^\"I don't know. I was a child. But I remember the shapes. Circles inside circles. Lines pointing down.\" She meets your eyes. \"Like something trying to reach the bottom of something that has no bottom.\"","\n","ev",{"VAR?":"gloria_trust"},1,"+",{"VAR=":"gloria_trust","re":true},"/ev",{"->":"day_3.gloria_day_3_end"},{"#f":5}]}],{"#f":1}],"gloria_day_3_end":["^Gloria puts the shoebox on the counter between you.","\n","^\"Take it. Whatever's on that recorder, whatever she wrote. It's yours now. Or whoever she wanted it to go to.\"","\n","^You take the box. Mara's voice. Mara's map. Mara's notes. The closest you've been to her since you arrived.","\n","ev",{"VAR?":"priority"},"str","^find_mara","/str","==","/ev",[{"->":".^.b","c":true},{"b":["^ She was sitting right here. Two weeks ago. Making plans. Hiding evidence. Preparing for what came next. And then she walked into the mine and didn't walk out.",{"->":".^.^.^.14"},null]}],"nop","\n","^Gloria unlocks the door. Flips the sign back to OPEN.","\n","^\"Val.\" She doesn't look at you. \"If you go where she went. Come back.\"","\n",{"->":".^.^.day_3_hub"},{"#f":1}],"day_3_gloria_low":["^The diner is open. Gloria is behind the counter. She pours you coffee without a word.","\n","^The conversation is shorter today. She asks about your shifts. You give vague answers. She doesn't press.","\n","ev",{"VAR?":"gloria_trust"},2,"==","/ev",[{"->":".^.b","c":true},{"b":["^ She's warmer than before. Not open, but watching you differently. Like she's making up her mind about something. ",["ev","visit",1,"seq","/ev","ev","du",0,"==","/ev",{"->":".^.s0","c":true},"nop",{"s0":["pop","^ gloria_trust += 1",{"->":".^.^.11"},null],"#f":5}],"^ ",{"->":".^.^.^.10"},null]}],"nop","\n","ev",{"VAR?":"gloria_trust"},2,"<","/ev",[{"->":".^.b","c":true},{"b":["^ She's polite but guarded. You're still a stranger who works at the place that swallowed her town.",{"->":".^.^.^.18"},null]}],"nop","\n","^You eat. You leave.","\n",{"->":".^.^.day_3_hub"},{"#f":1}],"day_3_walk":[["^The town is three blocks long. You walk it end to end in ten minutes.","\n","^The gas station is open. A teenager behind the counter doesn't look up from their phone. The gift shop sells Hollows merchandise: t-shirts, mugs, a plastic miner's helmet with LED eyes. YOU SURVIVED THE HOLLOWS printed on everything.","\n","^At the far end of town, past the diner, the road continues into the desert. Flat, straight, empty for as far as you can see. The highway back to Vegas. Back to the Order. Back to a world where people remember your name.","\n","^You could leave right now.","\n","ev","str","^You could. But you won't.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Think about what it would take to leave.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["\n","ev",{"VAR?":"priority"},"str","^find_mara","/str","==","/ev",[{"->":".^.b","c":true},{"b":["^ Mara didn't leave. You won't either. Not until you know what happened to her.",{"->":".^.^.^.9"},null]}],"nop","\n","ev",{"VAR?":"priority"},"str","^investigate_paranormal","/str","==","/ev",[{"->":".^.b","c":true},{"b":["^ Something is underneath this town. Something old and hungry and growing. Leaving doesn't stop it. Understanding it might.",{"->":".^.^.^.19"},null]}],"nop","\n",{"->":"day_3.day_3_hub"},{"#f":5}],"c-1":["\n","^Your car is at the motel. Your keys are in your pocket. The highway is right there. You could drive to Vegas in six hours and be sitting in Silas's office by midnight.","\n","^But what would you bring? A story about a hum and a doorway that disappeared? A notebook page in someone else's handwriting? The Order needs evidence. Recordings. Documents. Something that proves this isn't just a haunted house with good marketing.","\n","^And if the erasure is real, if people forget you the further you get from this place, would anyone in Vegas even know who you are when you arrived?","\n","^You file the thought away. Not today. But the road is there. You can see it from here.","\n",{"->":"day_3.day_3_hub"},{"#f":5}]}],{"#f":1}],"day_3_end":["^Late afternoon. You walk to The Hollows.","\n","ev",{"VAR?":"dale_suspicion"},5,">=","/ev",[{"->":".^.b","c":true},{"b":["^ ",{"->":"day_3.dale_warning"},{"->":".^.^.^.8"},null]}],"nop","\n","ev",{"VAR?":"dale_suspicion"},5,"<","/ev",[{"->":".^.b","c":true},{"b":["^ ",{"->":"day_3.day_3_arrival"},{"->":".^.^.^.16"},null]}],"nop","\n",{"#f":1}],"dale_warning":[["^You're halfway across the parking lot when Dale appears. Not from the entrance. From the side of the building, like he was waiting.","\n","^\"Val! Got a minute?\"","\n","^He falls into step beside you. Same smile. Same polo. But the energy is different tonight. Focused.","\n","^\"I wanted to check in. How are you finding it? The work, the town, the whole experience?\"","\n",["ev",{"^->":"day_3.dale_warning.0.8.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"It's good. I'm settling in.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_3.dale_warning.0.9.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Intense. But I like it.\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_3.dale_warning.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.8.s"},[{"#n":"$r2"}],"\n","^\"Great. Great. That's what I like to hear.\" He walks a few more steps. \"Because some people, they come here and they start... asking questions. Poking around. Staying late. Looking at things that aren't part of the job.\"","\n",{"->":"day_3.dale_warning_continued"},{"#f":5}],"c-1":["ev",{"^->":"day_3.dale_warning.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.9.s"},[{"#n":"$r2"}],"\n","^\"It is intense. This place has that effect.\" He pauses. Looks at the mine entrance. \"The trick is knowing where the intensity comes from. It comes from the show. The performance. Not from...\" He waves a hand vaguely at the mountain. \"Not from the building itself.\"","\n",{"->":"day_3.dale_warning_continued"},{"#f":5}]}],{"#f":1}],"dale_warning_continued":[["^He stops walking. Turns to face you. The smile is still there, but his eyes are flat.","\n","^\"I like you, Val. You're a good worker. Bex says you've got instincts.\" He leans forward, just slightly. \"But I need my people focused on the job. Not on... other things. The history, the tunnels, the filing cabinets.\" He says this last one casually, but it lands.","\n","ev",{"VAR?":"employee_records_seen"},"/ev",[{"->":".^.b","c":true},{"b":["^ He knows you were on the terminal. He knows what you looked for.",{"->":".^.^.^.8"},null]}],"nop","\n","^\"This is a haunted attraction. It's a business. And businesses work best when everyone stays in their lane.\" He claps you on the shoulder. \"You understand, right?\"","\n",["ev",{"^->":"day_3.dale_warning_continued.0.12.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"Crystal clear.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_3.dale_warning_continued.0.13.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Is this a warning?\"",{"->":"$r","var":true},null]}],"ev","str","^Say nothing. Just nod.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["ev",{"^->":"day_3.dale_warning_continued.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.12.s"},[{"#n":"$r2"}],"\n","^\"Good.\" The smile broadens. \"Have a great shift tonight.\" He turns and walks to the entrance. Casual. Unhurried. Like the conversation never happened.","\n",{"->":"day_3.day_3_arrival"},{"#f":5}],"c-1":["ev",{"^->":"day_3.dale_warning_continued.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.13.s"},[{"#n":"$r2"}],"\n","ev",{"VAR?":"dale_suspicion"},1,"+",{"VAR=":"dale_suspicion","re":true},"/ev","^Dale's smile doesn't flicker. \"It's friendly advice from your manager. That's all it is.\" A beat. \"That's all it needs to be.\"","\n","^He turns and walks to the entrance.","\n",{"->":"day_3.day_3_arrival"},{"#f":5}],"c-2":["\n","^You nod. Dale watches your face for a moment. Then he nods back.","\n","^\"Good talk.\" He walks to the entrance.","\n",{"->":"day_3.day_3_arrival"},{"#f":5}]}],{"#f":1}],"day_3_arrival":["^The staff entrance. The corridor. The fluorescent lights. The hum.","\n","^You check the schedule board outside the costume room. Your name is there. Val Rowan. Zone 3: The Buried.","\n","^A new zone. Deeper than The Collapse or The Shaft, but still upper level. You've walked through it on the tour but haven't worked it.","\n","ev",{"VAR?":"dale_suspicion"},5,">=","/ev",[{"->":".^.b","c":true},{"b":["^ Dale moved you again. Two zone changes in three nights. Is he testing you or isolating you?",{"->":".^.^.^.12"},null]}],"nop","\n",{"->":"night_3"},{"#f":1}],"#f":1}],"night_3":[{"->":".^.costume_room_3"},{"costume_room_3":[["^The costume room is quieter tonight. Fewer actors. The energy is different: loose, unhurried. Someone checks their phone openly. The woman with the ribcage piece isn't here.","\n","^\"Wednesday,\" the guy at the next station says to nobody in particular. \"Wednesdays are dead.\"","\n","^Bex is at their station.","\n","ev",{"VAR?":"visited_restricted_passage"},"/ev",[{"->":".^.b","c":true},{"b":["\n","ev",{"VAR?":"post_shift_2_tell_bex"},"/ev",[{"->":".^.b","c":true},{"b":["^ They work fast. Prosthetic gash, greasepaint, mask. Efficient hands, no eye contact. The \"please\" from last night sits between you like something neither of you wants to pick up.",{"->":".^.^.^.5"},null]}],"nop","\n","ev",{"VAR?":"post_shift_2_keep_quiet"},"/ev",[{"->":".^.b","c":true},{"b":["^ They work at normal pace. Professional. But once, when they hand you the mask, their eyes drop to your hands. The copper stains are gone. Bex remembers them anyway.",{"->":".^.^.^.11"},null]}],"nop","\n","ev",{"VAR?":"post_shift_2_tell_bex"},"!",{"VAR?":"post_shift_2_keep_quiet"},"!","&&","/ev",[{"->":".^.b","c":true},{"b":["^ They work at their usual pace. Prosthetic gash, greasepaint, mask. You feel the weight of what you found last night, but Bex's expression gives nothing away. Same routine.",{"->":".^.^.^.21"},null]}],"nop","\n",{"->":".^.^.^.10"},null]}],"nop","\n","ev",{"VAR?":"visited_restricted_passage"},"!","/ev",[{"->":".^.b","c":true},{"b":["^ They work at their usual pace. Prosthetic gash, greasepaint, mask. Same routine, third night running.",{"->":".^.^.^.17"},null]}],"nop","\n","^\"New zone again. The Buried.\"","\n",["ev",{"^->":"night_3.costume_room_3.0.21.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"What's The Buried?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_3.costume_room_3.0.22.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Dale's rotating me again?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_3.costume_room_3.0.23.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"How's the crowd tonight?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"night_3.costume_room_3.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.21.s"},[{"#n":"$r2"}],"\n","^\"Tightest zone in the uppers. Cave-in aftermath. Low ceilings, rubble walls, squeeze-throughs. Guests hate it.\" A beat. \"That's the point.\"","\n",{"->":"night_3.buried_briefing"},{"#f":5}],"c-1":["ev",{"^->":"night_3.costume_room_3.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.22.s"},[{"#n":"$r2"}],"\n","^\"Standard for new hires. Three zones in three nights. He wants to see where you fit.\" Bex pauses. \"Or where to put you.\"","\n",{"->":"night_3.buried_briefing"},{"#f":5}],"c-2":["ev",{"^->":"night_3.costume_room_3.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.23.s"},[{"#n":"$r2"}],"\n","^\"Light. Wednesday. You'll get maybe twenty groups all night.\" Bex shrugs. \"Slow nights are their own thing. More time in the dark.\"","\n",{"->":"night_3.buried_briefing"},{"#f":5}]}],{"#f":1}],"buried_briefing":[["^\"Your position is a rubble gap. There's a slit in the debris wall, about shoulder-width, stone behind you and foam in front. You wedge yourself in sideways and wait. When a group passes, you push through the rubble into the corridor.\"","\n","^Bex demonstrates with their hands, one flat surface pressing through another.","\n","^\"Arms first. Then shoulders. The foam shifts when you come through. Pieces fall. The guests hear the wall moving before they see you. On a slow night like this, take it deliberate. Let them watch the rubble shift. Let them figure out what's happening. By the time you're through, they've had three seconds of knowing something is coming out of the wall and not being able to do anything about it.\"","\n",["ev",{"^->":"night_3.buried_briefing.0.6.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"More dread than startle.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_3.buried_briefing.0.7.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"What if I get stuck?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"night_3.buried_briefing.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.6.s"},[{"#n":"$r2"}],"\n","^\"Exactly. Slow nights, you lean into the dread. The gaps between groups are long. Use the silence. The zone does half the work for you. The ceilings are low enough that everyone's already uncomfortable before you do anything.\"","\n",{"->":"night_3.buried_briefing_2"},{"#f":5}],"c-1":["ev",{"^->":"night_3.buried_briefing.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.7.s"},[{"#n":"$r2"}],"\n","^\"You won't. The gap is tight but the foam gives. Just don't overthink it. Push and commit.\" They almost smile. \"If you can breathe, you can fit.\"","\n",{"->":"night_3.buried_briefing_2"},{"#f":5}]}],{"#f":1}],"buried_briefing_2":["^\"Three other actors in The Buried tonight. Adjacent positions, same corridor. You'll be able to hear each other between groups. That's normal. Keep the chatter quiet.\"","\n","^Bex hands you the soft-soled boots again.","\n","^\"Same rules as always. Don't leave your zone. Don't break character in front of guests.\" They hesitate, then add: \"The Buried can feel... close. More than the other zones. The ceilings, the walls. If you need to step out for air, tell your floor manager. Nobody will judge you.\"","\n","^It sounds like standard advice. It also sounds like it isn't.","\n",{"->":".^.^.run_through_3"},{"#f":1}],"run_through_3":["^6:45 PM. Pre-show briefing. Thinner crowd than the past two nights. Dale does the speech. Same words. Same clipboard.","\n","^\"Light house tonight. Stay sharp anyway. Make it real, people.\"","\n","^The actors disperse. Fewer of them tonight. You count maybe twenty-five, down from thirty-five on Night 1. The zones will be spread thin.","\n","^You follow the markers to Zone 3: The Buried.","\n",{"->":".^.^.enter_buried"},{"#f":1}],"enter_buried":["^The Buried earns its name.","\n","^The transition from the main corridor is immediate. The ceiling drops. Not gradually. One step you're in a standard tunnel, the next you're ducking. The clearance is maybe five and a half feet, and the set dressing makes it feel lower: cracked timber supports bowed under the weight of foam rock, dangling cables (fake, but convincing), a fine dust haze in the air that catches the dim amber light.","\n","^The corridor is narrow. Two people can't walk abreast. The walls are dressed as collapsed rubble: foam boulders, splintered wood, twisted metal brackets. But behind the dressing, you can feel the real stone. The mine walls are right there, inches behind the set.","\n","^Your position is about forty feet in. The rubble gap.","\n","^It's exactly what Bex described. A vertical slit in the debris wall, maybe eighteen inches wide. Behind it, a pocket of space between the foam dressing and the real stone wall. You turn sideways and squeeze in.","\n","^Stone against your back. Cool, rough, real. Foam rubble against your chest and face. Through a gap in the debris, you can see the corridor: a narrow strip of amber light, fog pooling on the ground, the low ceiling pressing down.","\n","^The space is tight enough that your breathing moves the foam in front of you. You can feel your ribs expand against the stone on each inhale.","\n","^You test the emergence. Push forward with your hips and shoulders. The foam shifts, pieces tumbling. Your arms come through first, fingers scraping the corridor floor, then your shoulders, then the rest of you, spilling out of the wall in a cascade of debris.","\n","^You pull yourself back in. Reset the foam pieces. Wedge back into the gap.","\n","^To your left, maybe fifteen feet away, you can hear someone else settling into their position. A cough. The scrape of boots on stone.","\n","^Radio crackle. \"Doors open in five. Positions.\"","\n","^You press into the gap. You wait.","\n",{"->":".^.^.first_buried_groups"},{"#f":1}],"first_buried_groups":[["^The first group enters The Buried at 8:11 PM.","\n","^You hear them before you see them. The sounds are different in here: muffled, close, compressed by the low ceiling. Footsteps on gravel. Someone saying \"oh my God, it's so small in here.\" Nervous laughter.","\n","^They pass your position. Through the gap in the foam, you see them: four people, hunched, one hand on the ceiling, moving slowly. They're already scared. The zone is doing the work.","\n","^You push.","\n","^Arms first. The foam shifts. A chunk of rubble (lightweight, painted gray) tumbles into the corridor. The person at the back of the group hears it and turns.","\n","^You keep pushing. Shoulders through. The debris cascades. You're emerging from the wall, slow, deliberate, a dead miner pulling itself free from the collapse that killed it.","\n","^The person at the back stares. One second. Two. Processing. Then the scream.","\n","^The group doesn't run. There's nowhere to run. The corridor is too tight. They compress forward, stumbling, ducking, hands on each other's backs. You hold the position: half out of the wall, arms extended, mask facing them. They scramble around the corner and are gone.","\n","^You pull back in. Reset the foam. Wedge into the gap.","\n","^Silence. The dust settles. The amber light is steady.","\n","ev","str","^Wait for the next group.","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"night_3.slow_night_rhythm"},{"#f":5}]}],{"#f":1}],"slow_night_rhythm":[["^The next group doesn't come for four minutes.","\n","^Four minutes in the gap. Stone behind you. Foam in front. The mask fogs with your breath. Your shoulders ache from the narrow space. Dust from the foam settles on your tongue whenever you inhale through your mouth.","\n","^This is the slow night. The full houses on Nights 1 and 2 were machines: group after group, scream after scream, no time to think. Tonight there's nothing but time. The mine fills the gaps. You hear the timber creak. Water dripping somewhere below. And the hum, always the hum, louder in the silence than it ever was under the noise of a full crowd.","\n","^You start to find the pace. When a group comes, you emerge slow. Let them see the wall move. Let the foam tumble. Let the dread build. On a full night you'd need speed. Tonight you have the luxury of patience, and patience is worse.","\n","^Between groups, you stand in the dark and listen to the mine breathe.","\n","^By 9:30, you've done maybe ten groups. On a full night you'd be at thirty by now.","\n","^The actor in the next position over is bored. You can hear them shifting, tapping a rhythm on the stone with their fingernails. During a long lull, a whisper comes through the wall.","\n","^\"Hey. New hire, right?\"","\n",["ev",{"^->":"night_3.slow_night_rhythm.0.16.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"Yeah. Third night.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_3.slow_night_rhythm.0.17.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Val.\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"night_3.slow_night_rhythm.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.16.s"},[{"#n":"$r2"}],"\n","^\"Third night Wednesday. Lucky you.\" A quiet laugh. \"I'm Tuck.\"","\n",{"->":"night_3.tuck_banter_hub"},{"#f":5}],"c-1":["ev",{"^->":"night_3.slow_night_rhythm.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.17.s"},[{"#n":"$r2"}],"\n","^\"Tuck.\" A pause. \"Slow one tonight. You holding up?\"","\n",{"->":"night_3.tuck_banter_hub"},{"#f":5}]}],{"#f":1}],"tuck_banter_hub":[["^Tuck is two positions down, close enough to whisper between groups. You can't see each other. Just voices through the rubble wall.","\n","ev","str","^Ask about Dale.","/str",{"CNT?":".^.^.^.tuck_dale"},"!","/ev",{"*":".^.c-0","flg":21},"ev","str","^Ask about Bex.","/str",{"CNT?":".^.^.^.tuck_bex"},"!","/ev",{"*":".^.c-1","flg":21},"ev","str","^Ask how long they've been here.","/str",{"CNT?":".^.^.^.tuck_staying"},"!","/ev",{"*":".^.c-2","flg":21},"ev","str","^Ask if they've noticed anything strange.","/str",{"CNT?":".^.^.^.tuck_strange"},"!","/ev",{"*":".^.c-3","flg":21},"ev","str","^A group is coming. Back to work.","/str",{"CNT?":".^.^.^.tuck_dale"},{"CNT?":".^.^.^.tuck_bex"},"||",{"CNT?":".^.^.^.tuck_staying"},"||",{"CNT?":".^.^.^.tuck_strange"},"||","/ev",{"*":".^.c-4","flg":21},{"c-0":["\n",{"->":"night_3.tuck_dale"},{"#f":5}],"c-1":["\n",{"->":"night_3.tuck_bex"},{"#f":5}],"c-2":["\n",{"->":"night_3.tuck_staying"},{"#f":5}],"c-3":["\n",{"->":"night_3.tuck_strange"},{"#f":5}],"c-4":["\n",{"->":"night_3.buried_mid_shift"},{"#f":5}]}],{"#f":1}],"tuck_dale":[["^\"What's the deal with Dale?\"","\n","^A pause. You hear Tuck shift in their position.","\n","^\"Dale's Dale. Always smiling. Always has the clipboard. He's fine.\" Another pause. \"I've been here... I think about eight months? Maybe longer. And he's never had a bad day. Like, never. Not one.\"","\n",["ev",{"^->":"night_3.tuck_dale.0.6.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"That's a little weird.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_3.tuck_dale.0.7.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Does he ever talk about the company? HorrorCo?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"night_3.tuck_dale.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.6.s"},[{"#n":"$r2"}],"\n","^\"I guess? Some people are just like that. Positive energy or whatever.\" You can hear the shrug in their voice. \"He's not a bad boss. Pays on time. Doesn't micromanage. Just... don't be late and don't wander.\"","\n","ev",{"VAR?":"dale_suspicion"},5,">=","/ev",[{"->":".^.b","c":true},{"b":["^ Then, quieter: \"He's been asking about you, though. Just heads up.\"",{"->":".^.^.^.15"},null]}],"nop","\n",{"->":"night_3.tuck_banter_hub"},{"#f":5}],"c-1":["ev",{"^->":"night_3.tuck_dale.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.7.s"},[{"#n":"$r2"}],"\n","^\"Not really. You get the briefing, you get the schedule, you get the 'make it real' speech. That's about it. Corporate is...\" Tuck trails off. \"I don't think anyone's actually met anyone from corporate. Dale's the whole chain of command.\"","\n","ev",{"VAR?":"dale_suspicion"},5,">=","/ev",[{"->":".^.b","c":true},{"b":["^ Then, quieter: \"He's been asking about you, though. Just so you know.\"",{"->":".^.^.^.15"},null]}],"nop","\n",{"->":"night_3.tuck_banter_hub"},{"#f":5}]}],{"#f":1}],"tuck_bex":[["^\"Do you know Bex?\"","\n","^\"Bex is Bex.\" Tuck says it the same way everyone says it. Like a fact of geography. \"They've been here longer than anyone. Someone told me they were here when the place opened, but that can't be right. They'd have to be... I don't know. They don't look old enough.\"","\n",["ev",{"^->":"night_3.tuck_bex.0.4.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"Do they ever talk about how long they've been here?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_3.tuck_bex.0.5.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Are they always that quiet?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"night_3.tuck_bex.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.4.s"},[{"#n":"$r2"}],"\n","^\"I asked once. They got this look. Not angry. More like...\" Tuck pauses. \"Like I'd asked them what year it was and they weren't sure of the answer. I didn't ask again.\"","\n",{"->":"night_3.tuck_banter_hub"},{"#f":5}],"c-1":["ev",{"^->":"night_3.tuck_bex.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.5.s"},[{"#n":"$r2"}],"\n","^\"Pretty much. They do their job. They help new hires. But they're kind of... apart. Like they're on a different frequency than everyone else.\"","\n",{"->":"night_3.tuck_banter_hub"},{"#f":5}]}],{"#f":1}],"tuck_staying":[["^\"How long have you been at The Hollows?\"","\n","^\"Eight months. I think. Maybe nine.\" A beat. \"Came out from Reno for a couple weeks. Just needed the money. Then I stayed.\"","\n",["ev",{"^->":"night_3.tuck_staying.0.4.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"You like it that much?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_3.tuck_staying.0.5.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Ever think about leaving?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"night_3.tuck_staying.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.4.s"},[{"#n":"$r2"}],"\n","^\"I don't know if 'like' is the word. It's just... there's always another shift. And the town is easy. Cheap motel. The diner's fine. You don't really need much out here.\"","\n",{"->":"night_3.tuck_leaving"},{"#f":5}],"c-1":["ev",{"^->":"night_3.tuck_staying.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.5.s"},[{"#n":"$r2"}],"\n",{"->":"night_3.tuck_leaving"},{"#f":5}]}],{"#f":1}],"tuck_leaving":["^\"Leaving?\" Tuck repeats the word slowly. \"I don't know. I guess I haven't really thought about it. Huh.\"","\n","^They say this without concern. Without any weight at all. The way you'd say you hadn't thought about what to have for breakfast. Not a decision. Just an absence where a decision should be.","\n","^\"There's always another shift,\" they say again. Like a refrain they don't know they're repeating.","\n",{"->":".^.^.tuck_banter_hub"},{"#f":1}],"tuck_strange":[["^\"You ever see anything strange in here? Like, anything that's not part of the show?\"","\n","^\"Strange like what? It's a haunted house.\" Tuck laughs softly. \"Everything's strange. That's the product.\"","\n",["ev",{"^->":"night_3.tuck_strange.0.4.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"I mean the corridors. Have they ever seemed... different?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_3.tuck_strange.0.5.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Never mind.\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"night_3.tuck_strange.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.4.s"},[{"#n":"$r2"}],"\n","^A longer pause. \"Sometimes. Like, I'll come back from the reset loop and my gap feels a few feet off from where I left it. Or a turn I don't remember will be there and then it won't.\" You hear Tuck shift their weight. \"But it's dark. And you're tired. And you've been standing in a slit in the wall for four hours. Your brain does things.\"","\n",{"->":"night_3.tuck_banter_hub"},{"#f":5}],"c-1":["ev",{"^->":"night_3.tuck_strange.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.5.s"},[{"#n":"$r2"}],"\n","^\"Okay.\" Tuck doesn't push. The lull stretches. Somewhere down the corridor, a timer clicks and a strobe flashes once, uselessly, in the empty passage.","\n",{"->":"night_3.tuck_banter_hub"},{"#f":5}]}],{"#f":1}],"buried_mid_shift":["^Groups keep coming. Slowly. You push through the wall, they scream, you reset. The rhythm is sparse and steady. Your core aches from the repeated push-and-wedge. The mask has rubbed a second raw line across your forehead, parallel to the first.","\n","^Between scares, you listen. The mine. The hum. Tuck humming tunelessly in the next gap over. The other two actors are further down and you only hear them as distant thumps and muffled shouts.","\n","^Around 10:30, you notice something. The gap between your last two groups was seven minutes. Before that, five. The crowd is thinning. The show is winding down early tonight.","\n","^Then the radio.","\n","^\"Val Rowan, Zone 3. Report to the main corridor. Manager request.\"","\n","^You push out of the gap. Stretch your shoulders. Walk to the corridor intersection where the amber light meets the fluorescent white of the service hallway.","\n","^Dale is waiting.","\n","ev",{"VAR?":"dale_suspicion"},5,">=","/ev",[{"->":".^.b","c":true},{"b":["^ ",{"->":"night_3.dale_perimeter"},{"->":".^.^.^.20"},null]}],"nop","\n","ev",{"VAR?":"dale_suspicion"},5,"<","/ev",[{"->":".^.b","c":true},{"b":["^ ",{"->":"night_3.dale_zone_5"},{"->":".^.^.^.28"},null]}],"nop","\n",{"#f":1}],"dale_perimeter":[["^His smile is thinner tonight. Not gone. Just thinner.","\n","^\"Change of plans, Val. I'm pulling you off the floor. Need you on perimeter.\"","\n","^Perimeter. Parking lot duty. Crowd control outside the building.","\n","^\"Take a radio. Direct traffic. Make sure nobody parks in the fire lanes.\"","\n",["ev",{"^->":"night_3.dale_perimeter.0.8.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"On a Wednesday?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_3.dale_perimeter.0.9.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Understood.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_3.dale_perimeter.0.10.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"Is there a reason I'm being pulled?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"night_3.dale_perimeter.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.8.s"},[{"#n":"$r2"}],"\n","^\"Every night, full or slow. Insurance requirement.\" He holds your gaze. \"You can handle it.\"","\n",{"->":"night_3.perimeter_assignment"},{"#f":5}],"c-1":["ev",{"^->":"night_3.dale_perimeter.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.9.s"},[{"#n":"$r2"}],"\n",{"->":"night_3.perimeter_assignment"},{"#f":5}],"c-2":["ev",{"^->":"night_3.dale_perimeter.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.10.s"},[{"#n":"$r2"}],"\n","ev",{"VAR?":"dale_suspicion"},1,"+",{"VAR=":"dale_suspicion","re":true},"/ev","^\"Overstaffed for the house size. Happens on slow nights.\" His smile doesn't change. \"Don't read into it.\"","\n",{"->":"night_3.perimeter_assignment"},{"#f":5}]}],{"#f":1}],"perimeter_assignment":["^He hands you a reflective vest. Neon yellow, cheap, the kind road crews wear. Over your dead miner costume, it looks absurd.","\n","^\"Leave the mask. Keep the radio on channel 1.\"","\n","^He turns and walks back into the tunnels. His footsteps are unhurried. He doesn't look back.","\n","^You walk to the staff exit. Push through the door. Outside.","\n",{"->":".^.^.perimeter_shift"},{"#f":1}],"perimeter_shift":["^The parking lot is less than a third full. Maybe twenty cars, scattered across a lot built for two hundred. The ticket booth is dark. The queue barriers stand empty, casting long shadows under the pole lights.","\n","^It's cold. Desert cold, the kind that drops fast after sunset. The reflective vest does nothing for warmth. You stand at the edge of the lot, radio in hand, directing nobody.","\n","^A car pulls in. Parks. A couple gets out, walks to the entrance. They don't look at you.","\n","^Silence.","\n","^The building sits against the mountain, a dark mass of concrete and stone. You can hear the muffled bass of the attraction's audio through the walls. Somewhere inside, thirty actors are scaring the last few dozen guests of the night. You're out here watching an empty parking lot.","\n","ev",{"VAR?":"dale_suspicion"},6,">=","/ev",[{"->":".^.b","c":true},{"b":["^ Dale didn't pull you for staffing reasons. He pulled you because you're asking questions.","ev",{"VAR?":"employee_records_seen"},"/ev",[{"->":".^.b","c":true},{"b":["^ Because you stayed late at the terminal.",{"->":".^.^.^.5"},null]}],"nop","ev",{"VAR?":"library_clerk_check"},"/ev",[{"->":".^.b","c":true},{"b":["^ Because the library clerk reported back.",{"->":".^.^.^.10"},null]}],"nop","^ Because you pushed. This is the parking lot version of a corner office with no phone.",{"->":".^.^.^.16"},null]}],"nop","\n","^You walk the perimeter. Slowly. Observing.","\n","^The front of the building is all show: the arch, the lights (half of them off tonight), the fog machines (silent). The loading dock on the east side is padlocked. Ventilation ducts hum on the roof.","\n","^You circle around to the back.","\n",{"->":".^.^.perimeter_discovery"},{"#f":1}],"perimeter_discovery":[["^The back of the building faces the mountain. No lights. No signage. Just raw concrete meeting raw stone where the structure transitions into the mine itself.","\n","^Three emergency exits, evenly spaced. Steel doors, crash bars, marked with small red signs. The first two are shut. The third is propped open with a rock. Just a few inches. Enough for a thin line of warm air to spill out into the cold.","\n","^The hum is louder here. Not the muffled version from the parking lot. Clear and present, like standing next to a transformer.","\n","^You put your hand near the gap. The air is warm, almost hot. It smells like copper and ozone.","\n","ev","str","^Go through.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Note the location. Stay outside.","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^Close the door.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["\n","^You glance back toward the parking lot. Empty. Nobody watching. The radio crackles with routine chatter from inside.","\n","^You pull the door open enough to slip through. The warm air wraps around you.","\n",{"->":"night_3.service_corridor"},{"#f":5}],"c-1":["\n","^You memorize the position. Third exit from the east side, propped open, warm air. You can come back. But not tonight. Not in a reflective vest with a radio tuned to Dale's channel.","\n",{"->":"night_3.perimeter_late"},{"#f":5}],"c-2":["\n","^You kick the rock out and let the door shut. The crash bar engages with a heavy click. The warm air cuts off. The hum fades.","\n","^Whatever was supposed to be going in or out of that door tonight, it isn't anymore.","\n",{"->":"night_3.perimeter_late"},{"#f":5}]}],{"#f":1}],"service_corridor":[["ev",{"VAR?":"erasure_level"},1,"+",{"VAR=":"erasure_level","re":true},"/ev","^A service corridor. Not part of the attraction. No set dressing, no speakers, no fog. Just poured concrete floor, utility lighting, exposed pipes along the ceiling. A fire extinguisher on the wall. An electrical panel. The bones of the building, stripped of performance.","\n","^The corridor runs deeper into the mountain. The concrete floor gives way to stone after about thirty feet. The utility lights continue but they're spaced further apart, pools of yellow in growing darkness.","\n","^You're behind the show. This is the space between the walls, the infrastructure that guests never see and actors aren't supposed to either. Service access for the mid-level.","\n","ev",{"VAR?":"has_mara_pages"},"/ev",[{"->":".^.b","c":true},{"b":["^ Mara's map showed the service corridors. She marked them in blue. You're standing on a blue line right now.",{"->":".^.^.^.16"},null]}],"nop","\n","^The walls transition. Concrete to stone. New construction to old mine. You can see the seam where the building ends and the earth begins. Someone has bolted a steel bracket to the stone with a sign: AUTHORIZED PERSONNEL ONLY BEYOND THIS POINT.","\n","^Past the sign, the corridor opens slightly. The ceiling is higher here, natural rock instead of poured concrete. Two passages branch off: one left, one right. Both dark. The hum comes from the left passage, steady and low.","\n","^The right passage has a light at the far end. A single bulb, caged, the kind used in maintenance areas. Under it, on the stone wall, you can see marks. Scratches. No. Carvings.","\n","^Symbols.","\n","ev",{"VAR?":"has_notebook_page"},"/ev",[{"->":".^.b","c":true},{"b":["^ The same angular, geometric patterns from the maintenance tunnel. Mara's notebook page. But these are larger. Deeper. Cut into the stone with something heavy. And there are more of them, covering a wider area.",{"->":".^.^.^.30"},null]}],"nop","\n","ev",{"VAR?":"has_portal_mechanics"},"/ev",[{"->":".^.b","c":true},{"b":["^ Containment sigils. That's what Silas said the Order's 1971 agent called them. These are part of the same system. The lock that was supposed to keep the portal shut.",{"->":".^.^.^.36"},null]}],"nop","\n","ev",{"VAR?":"has_notebook_page"},"!",{"VAR?":"has_portal_mechanics"},"!","&&","/ev",[{"->":".^.b","c":true},{"b":["^ You don't recognize them. But they're deliberate. Someone carved these with purpose. They cover a section of wall maybe six feet wide, arranged in concentric arcs, like a target. Or a diagram. Or a map of something that spirals downward.",{"->":".^.^.^.46"},null]}],"nop","\n","^You step closer. The carvings are old. The stone around them is smooth, worn. But at the bottom of the arrangement, newer scratches. Sharper. Fresh stone showing white against the dark surface.","\n","^Someone has been adding to them. Recently.","\n","^Your radio crackles. Loud in the silence.","\n","^\"All perimeter, status check.\"","\n","^You key the radio. \"Perimeter clear.\" Your voice sounds wrong in here. Flat. Absorbed by the stone.","\n","ev","str","^Keep exploring.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Head back. You've seen enough.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["\n","ev",{"VAR?":"dale_suspicion"},1,"+",{"VAR=":"dale_suspicion","re":true},"/ev","^You move down the right passage toward the symbols. The hum from the left passage vibrates through the floor. The air is warm. Your skin prickles.","\n","^The carvings extend further than you thought. They continue around a corner, down a short flight of rough-cut steps, and stop at a steel door. Modern. Heavy. A keycard reader blinks red on the wall beside it.","\n","^The door to mid-level. One of them, anyway.","\n","^You don't have a keycard. But you know it's here. You know the path.","\n",{"->":"night_3.leave_service"},{"#f":5}],"c-1":["\n","^You've pushed your luck. The radio check means someone is tracking positions. If you don't appear at the parking lot soon, questions get asked.","\n","^You turn and walk back through the service corridor, through the propped exit, into the cold night air. The warm air cuts off behind you like a held breath releasing.","\n",{"->":"night_3.perimeter_late"},{"#f":5}]}],{"#f":1}],"leave_service":["^You retrace your steps. Service corridor. Concrete floor. The propped exit. Cold air.","\n","^You pull the door almost closed, leaving the rock in place. Whatever reason it was propped open, you don't want to be the one who changed things.","\n",{"->":".^.^.perimeter_late"},{"#f":1}],"dale_zone_5":[["^His smile is full. Operational, not personal.","\n","^\"Light night. I'm consolidating zones. Need you to cover second half in Zone 5.\"","\n","^Zone 5. You haven't worked it. Deeper in the uppers, past The Shaft, past The Collapse.","\n","^\"Simple step-out. Behind the support beam at position C. You'll see the mark.\" He checks his clipboard. \"Should be quiet the rest of the night. We're winding down early.\"","\n",["ev",{"^->":"night_3.dale_zone_5.0.8.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"Got it.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_3.dale_zone_5.0.9.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Where is Zone 5 exactly?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"night_3.dale_zone_5.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.8.s"},[{"#n":"$r2"}],"\n",{"->":"night_3.zone_5_transition"},{"#f":5}],"c-1":["ev",{"^->":"night_3.dale_zone_5.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.9.s"},[{"#n":"$r2"}],"\n","^\"Follow the main corridor past The Shaft. Take the second left. You'll see the signage.\" He's already turning away, already on to the next task. \"Radio if you need anything.\"","\n",{"->":"night_3.zone_5_transition"},{"#f":5}]}],{"#f":1}],"zone_5_transition":["^You walk. Past The Shaft, where you worked last night. The blue-white wash is dimmer tonight, the fog thinner. The skeleton crew shows: gaps between scare positions, empty alcoves, zones running on half power.","\n","^Zone 5 is called THE DRIFT. The set dressing suggests a different section of the mine: rougher walls, an ore cart track running along the floor, the sound of pickaxes echoing from hidden speakers. The ceiling is normal height here. After The Buried, it feels cavernous.","\n","^Your position is behind a timber support beam at a bend in the corridor. Simple mechanics: wait for the group to pass, step out behind them, stand still until the last person notices you. The stalker walk from Night 2, but stationary.","\n","^Easy work. Especially on a slow night.","\n","^But that's not what holds your attention.","\n","^At the far end of Zone 5, past the final scare position, the corridor ends at a door. Not a set piece. A real door. Steel frame, simple latch, no keycard reader. A sign reads: STAFF ONLY - LOWER LEVEL ACCESS.","\n","^The stairwell to mid-level.","\n","^From your position, you can see it during every lull between groups. The door. The latch. The thin line of warm air seeping from underneath it.","\n",{"->":".^.^.zone_5_shift"},{"#f":1}],"zone_5_shift":[["^You work the zone. Groups come through, sparse and scattered. The step-out is easy after three nights of boo holes and stalker walks and squeeze-throughs. You stand behind the beam. They pass. You step out. They notice. They scream or they don't. You step back.","\n","^Between groups, you watch the door.","\n","^The warm air from underneath it pulses. Not steadily. Rhythmically. Like breathing. In. Out. The gap between the door and the floor glows faintly on the exhale, warm air catching the amber light.","\n","^A group passes. You do the scare. Reset.","\n","^The door.","\n","^Another group. Scare. Reset.","\n","^The door. Five minutes without a group. The radio is quiet. The show is winding down.","\n","ev","str","^Try the door.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Stay at your position. Note the door for later.","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^Listen at the door.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["\n","^You walk to the end of the corridor. Fifteen steps past your position. You check the radio: silent. You check the corridor behind you: empty.","\n","^The latch is warm. You push it.","\n",{"->":"night_3.stairwell_descent"},{"#f":5}],"c-1":["\n","^You know where it is. Zone 5, end of the corridor. Simple latch. You can come back. During the day, maybe. Or tomorrow night, if Dale puts you back here.","\n","^The warm air pulses under the door. In. Out.","\n","^You watch it until the next group comes.","\n",{"->":"night_3.zone_5_late"},{"#f":5}],"c-2":["\n","^You walk to the door and press your ear against the steel.","\n","^The hum. Louder than anywhere in the upper zones. And underneath it, sounds. Footsteps, maybe. Or water. Or machinery. Something moving below you, steady and purposeful.","\n","^Then a sound you recognize: a door opening and closing, somewhere down the stairwell. Someone is down there.","\n","^You step back to your position before the next group arrives.","\n",{"->":"night_3.zone_5_late"},{"#f":5}]}],{"#f":1}],"stairwell_descent":[["ev",{"VAR?":"erasure_level"},1,"+",{"VAR=":"erasure_level","re":true},"/ev","^The door opens onto a concrete stairwell. Utility lighting. The air is noticeably warmer. The hum is immediate, present, vibrating through the handrail when you grip it.","\n","^Down. One flight. A landing. Another flight.","\n","^The stairwell opens onto a corridor that is wider than anything in the upper zones. The ceiling is high. The walls are stone, not set-dressed. No plywood, no paint. Show lighting bleeds in from somewhere to the left: red and purple washes, fog drifting. To the right, the corridor is dark. Unlit. Raw mine tunnel continuing into the mountain.","\n","^This is mid-level. You're standing at the boundary between the attraction and the mine.","\n","ev",{"VAR?":"has_mara_pages"},"/ev",[{"->":".^.b","c":true},{"b":["^ Mara's map. You can picture it. The stairwell connects to the junction between Zones 7 and 8. The mid-level scare zones are to the left. The path to the deep rooms is to the right. Down.",{"->":".^.^.^.18"},null]}],"nop","\n","^You can hear the show from here. Muffled screams. A bass hit from a speaker. The mechanical clank of an animatronic. The attraction is running, even on a slow night, even half-staffed, the machine keeps going.","\n","^To the right: darkness. The hum. The pull.","\n","^Your radio crackles.","\n","^\"All zones, fifteen minutes to close. Last groups coming through.\"","\n","ev","str","^Go back up. You know the way now.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Take one more look to the right.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["\n","^You climb the stairs. Close the door behind you. Walk back to position C. Your heart is pounding. Your hands are warm from the handrail.","\n","^A group comes through. You step out from behind the beam. They scream. You reset.","\n","^The door is right there. You know what's behind it. You know the way down.","\n",{"->":"night_3.zone_5_late"},{"#f":5}],"c-1":["\n","ev",{"VAR?":"dale_suspicion"},1,"+",{"VAR=":"dale_suspicion","re":true},"/ev","^You step into the dark corridor. The hum wraps around you. The air smells like copper. Ten steps. Twenty.","\n","^The walls narrow. The ceiling drops. You're leaving mid-level and entering something older. The stone is different here: darker, smoother, like it's been polished by water or time or something else.","\n","^Then footsteps. Above you. In the stairwell. Someone coming down.","\n","^You press flat against the wall. A flashlight beam sweeps the junction. A floor manager, doing rounds.","\n","^They don't see you. The beam passes. Footsteps continue down the left corridor, toward the scare zones.","\n","^You wait thirty seconds, then move. Back to the junction. Up the stairs. Through the door. Back to position C.","\n",{"->":"night_3.zone_5_late"},{"#f":5}]}],{"#f":1}],"perimeter_late":["^The rest of the perimeter shift is cold and empty. Two more cars arrive. One leaves. The radio chatters with floor manager updates that have nothing to do with you.","\n","^At 1 AM, the last guests exit. The parking lot empties. The lights over the entrance shut off one by one.","\n","ev",{"CNT?":".^.^.service_corridor"},"!","/ev",[{"->":".^.b","c":true},{"b":["^ You circle the building one more time. The third emergency exit is still propped open. The warm air still spills out. You leave it.",{"->":".^.^.^.9"},null]}],"nop","\n","^At 1:30, the radio crackles: \"Perimeter, you're clear. Come on in.\"","\n",{"->":".^.^.post_shift_3"},{"#f":1}],"zone_5_late":["^The show closes early tonight. 1:30 AM instead of 2. The last group comes through at 1:15, a couple who barely react. Too tired or too drunk to be scared.","\n","^House lights up. Fog off. The ambient audio dies. Zone 5, in full light, is just a corridor with a beam in it.","\n","^The door at the far end is still there. The warm air still pulses underneath it. In the fluorescent light, you can see scuff marks on the floor in front of it. Someone uses this door regularly.","\n",{"->":".^.^.post_shift_3"},{"#f":1}],"post_shift_3":["^Break room.","\n","^Tuck is there, changed out of costume, eating chips from a vending machine bag. They wave. \"Survive the night?\"","\n","^\"Barely.\"","\n","^Tuck laughs. Easy, unbothered. Same person who said \"I guess I haven't thought about it\" when asked about leaving. They seem fine. They seem normal. That's the thing.","\n","ev",{"VAR?":"dale_suspicion"},5,">=","/ev",[{"->":".^.b","c":true},{"b":["\n","^Bex appears. They look at you, then at the reflective vest you're still wearing.","\n","^\"Dale pulled you outside?\"","\n","^Their voice is flat. But their eyes say something else.","\n",["ev",{"^->":"night_3.post_shift_3.13.b.7.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"Yeah. Perimeter duty.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_3.post_shift_3.13.b.8.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Is that bad?\"",{"->":"$r","var":true},null]}],"ev","str","^Say nothing.","/str","/ev",{"*":".^.c-2","flg":20},{"->":".^.^.^.14"},{"c-0":["ev",{"^->":"night_3.post_shift_3.13.b.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.7.s"},[{"#n":"$r2"}],"\n","^Bex nods slowly. \"He did that to someone else. A while ago.\" They pause. \"Dark hair. She had dark hair. And she...\" Bex closes their eyes. Opens them. \"I can't remember her name. I should remember her name.\"","\n",{"->":"night_3.post_shift_3_bex"},{"#f":5}],"c-1":["ev",{"^->":"night_3.post_shift_3.13.b.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.8.s"},[{"#n":"$r2"}],"\n","^\"It's not good.\" Bex sits down. \"It means he's decided something about you.\"","\n",{"->":"night_3.post_shift_3_bex"},{"#f":5}],"c-2":["\n","^Bex looks at you for a long moment. Then they turn and start removing their makeup.","\n",{"->":"night_3.post_shift_3_end"},{"#f":5}]}]}],"nop","\n","ev",{"VAR?":"dale_suspicion"},5,"<","/ev",[{"->":".^.b","c":true},{"b":["\n","^Bex is at their station. Quiet. Routine.","\n","ev",{"CNT?":"night_3.stairwell_descent"},"/ev",[{"->":".^.b","c":true},{"b":["\n","^Your hands are warm. You can still feel the hum in your fingertips from the handrail. You found the way down. Mid-level. The junction. The path to the deep rooms.","\n","^Bex glances at you once. Their eyes linger on your hands, still flushed from the warmth below.","\n",{"->":"night_3.post_shift_3_bex"},{"->":".^.^.^.7"},null]}],"nop","\n","ev",{"CNT?":"night_3.stairwell_descent"},"!","/ev",[{"->":".^.b","c":true},{"b":["\n",{"->":"night_3.post_shift_3_end"},{"->":".^.^.^.14"},null]}],"nop","\n",{"->":".^.^.^.22"},null]}],"nop","\n",{"->":".^.^.post_shift_3_end"},{"#f":1}],"post_shift_3_bex":[["ev","str","^Tell Bex what you saw.","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^Keep it to yourself.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["\n","ev",{"VAR?":"bex_relationship"},1,"+",{"VAR=":"bex_relationship","re":true},"/ev","ev",{"CNT?":"night_3.service_corridor"},"/ev",[{"->":".^.b","c":true},{"b":["^ \"I found a service corridor. Behind the building. It connects to mid-level. There are symbols carved into the walls. The same kind I found in the maintenance tunnel.\"",{"->":".^.^.^.11"},null]}],"nop","\n","ev",{"CNT?":"night_3.stairwell_descent"},"/ev",[{"->":".^.b","c":true},{"b":["^ \"I found the stairwell to mid-level. Zone 5. I went down. I saw the junction.\"",{"->":".^.^.^.17"},null]}],"nop","\n","ev",{"CNT?":"night_3.service_corridor"},"!",{"CNT?":"night_3.stairwell_descent"},"!","&&","/ev",[{"->":".^.b","c":true},{"b":["^ \"I walked the perimeter. There's an emergency exit propped open on the back side. Warm air coming out.","ev",{"VAR?":"bex_hum"},"/ev",[{"->":".^.b","c":true},{"b":["^ The hum is stronger there.\"",{"->":".^.^.^.5"},null]}],"nop",{"->":".^.^.^.27"},null]}],"nop","\n","^Bex listens. Their expression doesn't change.","\n","^\"You're going deeper.\"","\n","^It's not a question.","\n","^\"Be careful, Val. The deeper you go, the harder it is to come back. And I don't mean physically.\"","\n",{"->":"night_3.post_shift_3_end"},{"#f":5}],"c-1":["\n","ev",{"VAR?":"bex_relationship"},1,"-",{"VAR=":"bex_relationship","re":true},"/ev","^You shrug. \"Just a slow night.\"","\n","^Bex watches you for a moment. They know you're not telling them something. You can see it in the way they hold still, the way their eyes track your face.","\n","^They don't push.","\n",{"->":"night_3.post_shift_3_end"},{"#f":5}]}],{"#f":1}],"post_shift_3_end":[{"->":".^.^.figure_absence"},{"#f":1}],"figure_absence":["ev",{"VAR?":"dale_suspicion"},5,">=","/ev",[{"->":".^.b","c":true},{"b":["\n","^You realize it as you're walking out. The building. The parking lot. The corridors in the first half of the shift, the long cold silence of the perimeter in the second.","\n",{"->":".^.^.^.6"},null]}],"nop","\n","ev",{"VAR?":"dale_suspicion"},5,"<","/ev",[{"->":".^.b","c":true},{"b":["\n","^You realize it as you're walking out. The corridor. The zones. The gaps between groups, the long slow silences.","\n",{"->":".^.^.^.14"},null]}],"nop","\n","^No figure.","\n","^Night 1, the Figure appeared in The Collapse. Night 2, in The Shaft, closer. Tonight: nothing. No motionless shape at the end of a corridor. No burlap mask. No faded silhouette standing in the dark.","\n","^You expected it. You were watching for it. Every long lull, every empty stretch, you found yourself scanning the shadows for something that shouldn't be there.","\n","^It wasn't.","\n","ev",{"VAR?":"mara_clues"},3,">=","/ev",[{"->":".^.b","c":true},{"b":["^ You wonder where Mara is tonight. If the Figure is what's left of her, if it's some kind of echo or residue, then its absence means something. She's not here. She's somewhere else. Deeper, maybe. Or further gone.",{"->":".^.^.^.30"},null]}],"nop","\n","ev",{"VAR?":"mara_clues"},3,"<","/ev",[{"->":".^.b","c":true},{"b":["^ The corridors were just corridors tonight. The dark was just dark. You should be relieved. You're not.",{"->":".^.^.^.38"},null]}],"nop","\n",{"->":".^.^.end_night_3"},{"#f":1}],"end_night_3":[["^The walk back to the motel. Stars. Cold. The hum.","\n","^Room 6. The room accepted your existence today. Your bag is where you left it after re-unpacking this morning. Small comfort. You wonder if it will remember you tomorrow.","\n","ev",{"VAR?":"has_mara_recording"},"/ev",[{"->":".^.b","c":true},{"b":["^ You take out the recorder. Press play. Mara's voice, low and steady.",{"->":".^.^.^.8"},null]}],"nop","\n","ev",{"VAR?":"has_mara_recording"},"/ev",[{"->":".^.b","c":true},{"b":["^ \"The attraction isn't just built on top of something. It's built to feed something. The fear. The guests' fear. It's not a byproduct. It's the product.\"",{"->":".^.^.^.14"},null]}],"nop","\n","ev",{"VAR?":"has_mara_recording"},"/ev",[{"->":".^.b","c":true},{"b":["^ On a slow night, with a thin crowd and half the zones running on skeleton crew, the machine still ran. Still harvested. Whatever is below this mine, it ate less tonight. But it still ate.",{"->":".^.^.^.20"},null]}],"nop","\n","ev",{"CNT?":".^.^.^.service_corridor"},"/ev",[{"->":".^.b","c":true},{"b":["^ The symbols in the service corridor. ","ev",{"VAR?":"visited_restricted_passage"},"/ev",[{"->":".^.b","c":true},{"b":["^ Larger than the ones in the maintenance tunnel. Older.",{"->":".^.^.^.5"},null]}],"nop","^ And someone is adding to them.",{"->":".^.^.^.26"},null]}],"nop","\n","ev",{"CNT?":".^.^.^.stairwell_descent"},"/ev",[{"->":".^.b","c":true},{"b":["^ Mid-level. The junction. The path to the right, into the dark, toward the deep rooms. You know the way now. Tomorrow night, you can go further.",{"->":".^.^.^.32"},null]}],"nop","\n","ev",{"CNT?":".^.^.^.service_corridor"},"!",{"CNT?":".^.^.^.stairwell_descent"},"!","&&","/ev",[{"->":".^.b","c":true},{"b":["^ You didn't go deeper tonight. You stayed where you were told. But you know where the doors are. Tomorrow night.",{"->":".^.^.^.42"},null]}],"nop","\n","^You set your alarm for noon.","\n","ev","str","^Day 4","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"day_4"},{"#f":5}]}],{"#f":1}],"#f":1}],"day_4":[{"->":".^.morning_4"},{"morning_4":["^You wake up before the alarm.","\n","^Something is wrong. Not wrong like the room resetting. Wrong like you.","\n","^You're lying in bed, staring at the ceiling, and you can't remember what your car looks like. You know you drove here. You know you have a car. You can feel the keys in your jacket pocket, hanging on the chair. But the color, the make, the shape of the steering wheel under your hands: gone. Like a word you can almost say but can't.","\n","^You get up. Walk to the window. Pull the shade.","\n","^The parking spot where you parked four days ago is empty. Not just empty. Clean. The asphalt is uniform, unbroken, the same shade as the rest of the lot. No oil stain. No tire marks. No indent from four days of weight.","\n","^Your car was there last night. You're almost sure. You walked past it coming back from the shift. Didn't you?","\n","^The keys are in your jacket pocket. You check. They're there. Heavy, real, the fob smooth under your thumb. Keys to a car that doesn't exist anymore.","\n","ev",{"VAR?":"erasure_level"},1,"+",{"VAR=":"erasure_level","re":true},"/ev","^You sit on the bed. Pick up your notebook. Open it to the first page of notes, the ones you wrote at Silas's office before the drive.","\n","^The shorthand is there. Your handwriting. Your marks. But the fluency is stuttering. You look at a line you wrote five days ago and you have to concentrate to read it, trace each symbol deliberately, the way you did when you were first learning the system. The knowledge is still there but it's receding, like a tide pulling back from a shore.","\n","ev",{"VAR?":"erasure_level"},5,">=","/ev",[{"->":".^.b","c":true},{"b":["^ You can't remember the drive. You know you drove from Las Vegas to Veinrock. You know it took hours. But the memory is flat, dimensionless, like reading about something that happened to someone else. The desert. The highway. The turn onto the two-lane road. All of it is there, technically, but drained of the feeling of having been there.",{"->":".^.^.^.30"},null]}],"nop","\n","ev",{"VAR?":"erasure_level"},4,"==","/ev",[{"->":".^.b","c":true},{"b":["^ You open your notebook. The shorthand is there, your handwriting, your marks. You can still read it, but you have to concentrate in a way you didn't three days ago. And there's something else. You try to picture your apartment in Las Vegas. The layout. The color of the walls. The view from the window. You know you have one. You know you've lived there. But the image won't form. It's not gone — it's fading, like a photograph left in the sun.",{"->":".^.^.^.38"},null]}],"nop","\n","ev",{"VAR?":"erasure_level"},4,"<","/ev",[{"->":".^.b","c":true},{"b":["^ You force yourself through the notes. Line by line. The shorthand comes back as you work, grudgingly, like a muscle warming up. But the ease is gone. What used to be second nature now requires effort.",{"->":".^.^.^.46"},null]}],"nop","\n","^You have been undermined. Something below this town has been eating upward through the rock, the roads, the memories, and now through you.","\n","^The portal isn't just erasing you from other people's memories. It's erasing you from yourself.","\n",{"->":".^.^.bex_arrival"},{"#f":1}],"bex_arrival":["^You open the motel room door to go to the office. To ask about the car. To do something.","\n","^Bex is standing in the parking lot.","\n","^In daylight. In the sun. Squinting against it like it hurts.","\n","^They're wearing the same black clothes they always wear: black jeans, black shirt, the work boots. No jacket. Their skin is pale in a way you haven't noticed under the fluorescent lights of the costume room. Out here, in the desert morning, they look bleached. Washed out. Like a photograph left in a window.","\n","^They've never been outside The Hollows. Not once, in all the time you've known them. Not once, in all the time anyone has known them. Bex lives inside the mine. Bex works inside the mine. Bex, as far as anyone can tell, does not exist outside the mine.","\n","^They're here.","\n","^\"Val.\"","\n","ev",{"VAR?":"bex_relationship"},5,">=","/ev",[{"->":".^.b","c":true},{"b":["^ ",{"->":"day_4.bex_ally"},{"->":".^.^.^.20"},null]}],"nop","\n","ev",{"VAR?":"bex_relationship"},1,">=",{"VAR?":"bex_relationship"},5,"<","&&","/ev",[{"->":".^.b","c":true},{"b":["^ ",{"->":"day_4.bex_neutral"},{"->":".^.^.^.32"},null]}],"nop","\n","ev",{"VAR?":"bex_relationship"},0,"<=","/ev",[{"->":".^.b","c":true},{"b":["^ ",{"->":"day_4.bex_warning"},{"->":".^.^.^.40"},null]}],"nop","\n",{"#f":1}],"bex_ally":[["ev",{"VAR?":"bex_relationship"},1,"+",{"VAR=":"bex_relationship","re":true},"/ev","^\"Can I come in?\"","\n","^You step aside. They walk into the motel room. They move carefully, looking at the walls, the bed, the window, like someone entering a building they've only seen from outside. They sit in the chair by the desk. Their hands are in their lap. They don't fidget. They don't blink enough.","\n","^\"I don't come out here,\" they say. \"I don't... I haven't been outside in a long time. I don't know how long.\" They look at the window. The sun. \"It's bright.\"","\n",["ev",{"^->":"day_4.bex_ally.0.12.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"How long, Bex?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_4.bex_ally.0.13.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"What brought you here?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_4.bex_ally.0.14.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"You look like you haven't seen the sun in years.\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_4.bex_ally.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.12.s"},[{"#n":"$r2"}],"\n","^They're quiet for a moment. \"I was here when the mine was a mine. Before The Hollows. Before HorrorCo. Before Dale.\" They say this carefully, like someone walking on ice. \"I was here when it opened. Not the attraction. The thing underneath.\"","\n",{"->":"day_4.bex_story"},{"#f":5}],"c-1":["ev",{"^->":"day_4.bex_ally.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.13.s"},[{"#n":"$r2"}],"\n","^\"Tonight is the last night. For you. Maybe for everyone.\" They look at you directly. \"I came to tell you something I should have told you on your first shift.\"","\n",{"->":"day_4.bex_story"},{"#f":5}],"c-2":["ev",{"^->":"day_4.bex_ally.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.14.s"},[{"#n":"$r2"}],"\n","^\"I haven't.\" No humor. No deflection. Just the fact. \"I don't remember the last time I was outside. I don't remember a lot of things. But I remember the important ones.\"","\n",{"->":"day_4.bex_story"},{"#f":5}]}],{"#f":1}],"bex_story":[["^\"I've been maintaining the carvings,\" Bex says. \"In the tunnels. Deep in the mine, on the walls. There are symbols carved into the stone. Old ones. Much older than the mine.\"","\n","ev",{"VAR?":"has_mara_pages"},"/ev",[{"->":".^.b","c":true},{"b":["^ Mara's pages. The symbols she categorized: containment, feeding, opening. The containment ones. Bex has been maintaining them.",{"->":".^.^.^.6"},null]}],"nop","\n","ev",{"VAR?":"has_notebook_page"},{"VAR?":"has_mara_pages"},"!","&&","/ev",[{"->":".^.b","c":true},{"b":["^ Mara's notebook page. The symbols she was mapping. \"Not decorative. Functional?\" Now Bex is telling you what they're for.",{"->":".^.^.^.15"},null]}],"nop","\n","ev",{"VAR?":"has_portal_mechanics"},"/ev",[{"->":".^.b","c":true},{"b":["^ Silas's intel. The 1971 field agent. Containment sigils. Someone tried to keep the portal shut. That someone is sitting in your motel room.",{"->":".^.^.^.21"},null]}],"nop","\n","ev",{"VAR?":"has_notebook_page"},"!",{"VAR?":"has_mara_pages"},"!","&&",{"VAR?":"has_portal_mechanics"},"!","&&","/ev",[{"->":".^.b","c":true},{"b":["^ You haven't seen them. But Bex talks about them the way an engineer talks about load-bearing walls: with the certainty of someone who knows what happens if they fail.",{"->":".^.^.^.34"},null]}],"nop","\n","^\"Someone carved them a long time ago. Before the mine. Before the town. They were meant to hold it closed. When the mine broke through, in '73, the sigils cracked. Not all of them. Enough.\" Bex's voice is steady. Practiced. Like they've rehearsed this in their head for years, waiting for someone to tell.","\n","^\"I found them. After. I don't remember exactly when. I started tracing them. In the dark, after shifts, when nobody was watching. Reinforcing the lines. Keeping the pattern intact. Every time HorrorCo carves new glyphs to widen the portal, I go back and repair the containment.\"","\n","^\"For how long?\"","\n","^\"Since the beginning.\" They pause. \"I think. I've lost some of the years. They blur. But the work hasn't stopped. Every night. Every night for...\" They trail off. Their hands are trembling slightly.","\n","^\"I had a...\" They stop. Look at the motel room wall. The cheap print of a desert landscape. \"I had a name. A real one. Not Bex. I had a place I was going back to. I think there was a...\" Their voice catches. Not on emotion. On absence. The sentence has a hole in it where the next word should be and Bex is standing at the edge of it looking down.","\n","^They look at their hands. Turn them over. The way you check your pockets for something you know you had a moment ago.","\n","^\"I'm not enough anymore. The opening glyphs are winning. There are more of them every month and fewer of me. The signal's still there but it's mostly noise now.\"","\n",["ev",{"^->":"day_4.bex_story.0.50.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"What happens if the containment fails?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_4.bex_story.0.51.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"How do I stop it?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_4.bex_story.0.52.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"You've been doing this alone. All this time.\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_4.bex_story.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.50.s"},[{"#n":"$r2"}],"\n","^\"It opens. All the way. Everything on this side gets pulled through. Not just people. Memory. History. The town. The mine. Everything that was ever here.\" Their voice doesn't waver. \"It's been getting closer for years. Tonight might be the night.\"","\n",{"->":"day_4.bex_ritual"},{"#f":5}],"c-1":["ev",{"^->":"day_4.bex_story.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.51.s"},[{"#n":"$r2"}],"\n",{"->":"day_4.bex_ritual"},{"#f":5}],"c-2":["ev",{"^->":"day_4.bex_story.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.52.s"},[{"#n":"$r2"}],"\n","^Bex looks at you. Something shifts behind their eyes. Not quite gratitude. More like the recognition of being seen.","\n","^\"Yes.\"","\n",{"->":"day_4.bex_ritual"},{"#f":5}]}],{"#f":1}],"bex_ritual":[["^\"The portal breathes,\" Bex says. \"It has a rhythm. Like a heartbeat, but slower. Much slower. When it exhales, it's strong. The pull, the hum, the heat. That's when it takes people. That's when it erases.\"","\n","^They lean forward.","\n","^\"But between the exhales, there's a pause. A moment when it's pulling inward, contracting, before the next push. In that moment, the containment can be restored. The original symbols, carved in the right pattern, in the right places, can push it back. Constrict it. Maybe close it.\"","\n","ev",true,"/ev",{"VAR=":"has_ritual_knowledge","re":true},"^\"You need to be at the portal. At the bottom. During the pause between breaths. And you need the pattern. The complete pattern, not fragments.\" They look at you. \"Can you remember things? Still? Or is that going too?\"","\n","^\"It's getting harder.\"","\n","^\"Then don't write this down. Writing fades. Memorize it in your hands. In the movement. Like muscle memory.\"","\n","^Bex draws on the motel notepad. Their hand moves with the certainty of long practice. Concentric arcs. Angular intersections. The same language as the symbols on the tunnel walls, but complete. A full circuit. A lock.","\n","^\"This is the containment pattern. The whole thing. I've been tracing fragments of it for decades. This is what it's supposed to look like when it's whole.\"","\n","^You watch. You memorize. Not the shorthand. The shape.","\n",["ev",{"^->":"day_4.bex_ritual.0.22.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"What happens to you if the portal closes?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_4.bex_ritual.0.23.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Will you come with me? Tonight?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_4.bex_ritual.0.24.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"Thank you.\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_4.bex_ritual.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.22.s"},[{"#n":"$r2"}],"\n","^Bex doesn't answer immediately. They set down the pen. They look at their hands.","\n","^\"I don't know. I've been part of it for a long time. Part of the system. If the system ends...\" They stop. \"I don't know.\"","\n",{"->":"day_4.bex_ally_end"},{"#f":5}],"c-1":["ev",{"^->":"day_4.bex_ritual.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.23.s"},[{"#n":"$r2"}],"\n","^\"I'll be there. I'm always there.\" A pause. \"But I don't know how much help I'll be. The closer I am to it, the less of me there is. At the portal itself, I might not be anything at all.\"","\n",{"->":"day_4.bex_ally_end"},{"#f":5}],"c-2":["ev",{"^->":"day_4.bex_ritual.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.24.s"},[{"#n":"$r2"}],"\n","^Bex looks at you. The sun is coming through the window, and in the light, you can see through them. Not literally. But almost. The edges of their outline are soft. Uncertain.","\n","^\"Don't thank me. Come back.\"","\n",{"->":"day_4.bex_ally_end"},{"#f":5}]}],{"#f":1}],"bex_ally_end":["^Bex stands. They look at the door like it's a long way away.","\n","^\"I need to go back. Before Dale notices.\" They pause at the threshold. \"Tonight, Val. Whatever you're going to do. Tonight.\"","\n","^They walk across the parking lot. Toward the mine. They don't look back. In the bright sun, they cast almost no shadow.","\n",{"->":".^.^.day_4_hub"},{"#f":1}],"bex_neutral":[["ev",{"VAR?":"bex_relationship"},1,"+",{"VAR=":"bex_relationship","re":true},"/ev","^They don't come closer. They stand in the lot, arms at their sides, looking at you from twenty feet away.","\n","^\"It's louder today,\" they say. \"The hum. Can you feel it?\"","\n","^You can. Even out here, in the open air, you can feel it in your back teeth. In the soles of your feet. The mine is a mile away and the hum is here.","\n","^\"Something is different. I don't know what's going to happen tonight. But the rhythm is changing. It's been getting faster.\"","\n",["ev",{"^->":"day_4.bex_neutral.0.14.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"What do you mean, the rhythm?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_4.bex_neutral.0.15.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Why are you here, Bex?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_4.bex_neutral.0.16.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"You've never been outside The Hollows before.\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_4.bex_neutral.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.14.s"},[{"#n":"$r2"}],"\n","^\"The portal breathes. Slow. I've felt it for a long time. But today it's faster. Shorter intervals. Like something is building.\" They shake their head. \"I don't know what that means. But it's not good.\"","\n",{"->":"day_4.bex_neutral_advice"},{"#f":5}],"c-1":["ev",{"^->":"day_4.bex_neutral.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.15.s"},[{"#n":"$r2"}],"\n","^\"Because something is going to happen tonight and I wanted to tell you before it did.\" They don't elaborate. They don't explain how they know. \"I owed you that much.\"","\n",{"->":"day_4.bex_neutral_advice"},{"#f":5}],"c-2":["ev",{"^->":"day_4.bex_neutral.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.16.s"},[{"#n":"$r2"}],"\n","^\"No.\" They say it flatly. \"I don't like it out here. It's too open.\" They look at the sky like it might fall. \"I won't stay long.\"","\n",{"->":"day_4.bex_neutral_advice"},{"#f":5}]}],{"#f":1}],"bex_neutral_advice":[["^\"If you're going deeper tonight, stay on the left passages. Past the stairwell, past mid-level, when the tunnel forks. Stay left. The right passages loop. You'll walk for hours and end up where you started.\"","\n",["ev",{"^->":"day_4.bex_neutral_advice.0.2.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"How do you know that?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_4.bex_neutral_advice.0.3.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Come with me.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_4.bex_neutral_advice.0.4.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"Thank you.\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_4.bex_neutral_advice.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.2.s"},[{"#n":"$r2"}],"\n","^\"I've been working there for a long time, Val.\" That's all they'll say.","\n",{"->":"day_4.bex_neutral_end"},{"#f":5}],"c-1":["ev",{"^->":"day_4.bex_neutral_advice.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.3.s"},[{"#n":"$r2"}],"\n","^\"I'll be there. I'm always there.\" The same words they'd say at high trust, but here they sound different. Resigned. Not a promise. A fact.","\n",{"->":"day_4.bex_neutral_end"},{"#f":5}],"c-2":["ev",{"^->":"day_4.bex_neutral_advice.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.4.s"},[{"#n":"$r2"}],"\n","^They nod. Once.","\n",{"->":"day_4.bex_neutral_end"},{"#f":5}]}],{"#f":1}],"bex_neutral_end":["^Bex turns and walks toward the mine. Their gait is steady, unhurried, the same pace they use in the costume room. Comfortable in motion. Uncomfortable standing still in daylight.","\n","^They don't look back.","\n",{"->":".^.^.day_4_hub"},{"#f":1}],"bex_warning":[["^Bex stands in the parking lot. Their face is flat. Empty. Not hostile. Just closed.","\n","^\"Leave tonight.\"","\n","^No preamble. No greeting. Four days of working together and this is what they came to say.","\n","^\"Don't go to your shift. Don't go to the mine. Get in your car and drive.\"","\n",["ev",{"^->":"day_4.bex_warning.0.8.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"My car is gone.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_4.bex_warning.0.9.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"I'm not leaving.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_4.bex_warning.0.10.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"Why do you care?\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_4.bex_warning.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.8.s"},[{"#n":"$r2"}],"\n","^Bex blinks. Looks at the empty parking spot. Back at you. Something passes across their face. Not surprise. Sorrow.","\n","^\"Then find another way. The woman at the diner. Someone. Get out of Veinrock before tonight.\"","\n",{"->":"day_4.bex_warning_continued"},{"#f":5}],"c-1":["ev",{"^->":"day_4.bex_warning.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.9.s"},[{"#n":"$r2"}],"\n","^\"Then you won't be here tomorrow. You understand that, right? You won't be here. You won't be anywhere. Nobody will remember your name.\"","\n",{"->":"day_4.bex_warning_continued"},{"#f":5}],"c-2":["ev",{"^->":"day_4.bex_warning.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.10.s"},[{"#n":"$r2"}],"\n","^\"Because I've watched it happen before. More times than I can count. And every time, I remember for a while, and then I don't. And then someone new shows up and it starts again.\"","\n",{"->":"day_4.bex_warning_continued"},{"#f":5}]}],{"#f":1}],"bex_warning_continued":["^\"If you're still here tomorrow, you won't be here the day after.\"","\n","^They turn and walk toward the mine. They don't look back. In the sun, their outline looks thin. Insubstantial. Like something that's been here too long and is wearing away.","\n","ev",{"VAR?":"bex_relationship"},0,"<=","/ev",[{"->":".^.b","c":true},{"b":["^ Even at the end, Bex came. Walked out of the mine for the first time in years. Decades, maybe. Stood in a parking lot and told you to run. They care. They've always cared. They just can't do more than this.",{"->":".^.^.^.10"},null]}],"nop","\n",{"->":".^.^.day_4_hub"},{"#f":1}],"day_4_hub":["^The sun is high. You have hours before your shift. Not many.","\n","ev",{"VAR?":"day_4_visits"},2,"<","/ev",[{"->":".^.b","c":true},{"b":["\n","ev","str","^Go to Gloria's diner.","/str",{"CNT?":"day_4.day_4_gloria"},"!","/ev",{"*":".^.c-0","flg":21},"ev","str","^Call Silas.","/str",{"CNT?":"day_4.day_4_silas"},"!","/ev",{"*":".^.c-1","flg":21},"ev","str","^Go to The Hollows. Search the lower tunnels while it's closed.","/str",{"CNT?":"day_4.day_4_tunnels"},"!","/ev",{"*":".^.c-2","flg":21},"ev","str","^Stay here. Go through your evidence. Make a plan.","/str",{"CNT?":"day_4.day_4_prepare"},"!","/ev",{"*":".^.c-3","flg":21},{"->":".^.^.^.8"},{"c-0":["\n","ev",{"VAR?":"day_4_visits"},1,"+",{"VAR=":"day_4_visits","re":true},"/ev",{"->":"day_4.day_4_gloria"},{"#f":5}],"c-1":["\n","ev",{"VAR?":"day_4_visits"},1,"+",{"VAR=":"day_4_visits","re":true},"/ev",{"->":"day_4.day_4_silas"},{"#f":5}],"c-2":["\n","ev",{"VAR?":"day_4_visits"},1,"+",{"VAR=":"day_4_visits","re":true},"/ev",{"->":"day_4.day_4_tunnels"},{"#f":5}],"c-3":["\n","ev",{"VAR?":"day_4_visits"},1,"+",{"VAR=":"day_4_visits","re":true},"/ev",{"->":"day_4.day_4_prepare"},{"#f":5}]}]}],"nop","\n","ev",{"VAR?":"day_4_visits"},2,">=","/ev",[{"->":".^.b","c":true},{"b":["\n","^The sun is dropping. Orange light on the mountains. The shadows are stretching across the parking lot, across the empty space where your car used to be.","\n","^You're out of time.","\n","ev","str","^Head to The Hollows for your shift.","/str","/ev",{"*":".^.c-0","flg":20},{"->":".^.^.^.16"},{"c-0":["\n",{"->":"day_4.day_4_end"},{"#f":5}]}]}],"nop","\n",{"#f":1}],"day_4_gloria":["^The diner door is unlocked. Gloria is behind the counter. She looks up when you walk in and her face does something complicated.","\n","ev",{"VAR?":"gloria_trust"},7,">=","/ev",[{"->":".^.b","c":true},{"b":["^ ",{"->":"day_4.gloria_papers"},{"->":".^.^.^.8"},null]}],"nop","\n","ev",{"VAR?":"gloria_trust"},5,">=",{"VAR?":"gloria_trust"},7,"<","&&","/ev",[{"->":".^.b","c":true},{"b":["^ ",{"->":"day_4.gloria_escape"},{"->":".^.^.^.20"},null]}],"nop","\n","ev",{"VAR?":"gloria_trust"},3,">=",{"VAR?":"gloria_trust"},5,"<","&&","/ev",[{"->":".^.b","c":true},{"b":["^ ",{"->":"day_4.gloria_worried"},{"->":".^.^.^.32"},null]}],"nop","\n","ev",{"VAR?":"gloria_trust"},3,"<","/ev",[{"->":".^.b","c":true},{"b":["^ ",{"->":"day_4.gloria_guarded"},{"->":".^.^.^.40"},null]}],"nop","\n",{"#f":1}],"gloria_papers":[["ev",true,"/ev",{"VAR=":"has_ritual_knowledge","re":true},"ev",true,"/ev",{"VAR=":"has_escape_route","re":true},"^\"Sit down. Close the door.\"","\n","^She locks it. Same as last time. But today she doesn't go behind the counter. She goes to the booth in the back, the one furthest from the windows, and sits down across from you. On the table between you: a manila envelope, yellowed, soft at the edges from decades of handling.","\n","^\"My father's papers.\"","\n","^She opens the envelope. Inside: three sheets of drafting paper, the kind used for engineering blueprints. Martin Aldrich's handwriting, neat and precise. The first two sheets are mine surveys: tunnel depths, load-bearing calculations, ventilation routes. Normal mining documents from the 1940s.","\n","^The third sheet is different.","\n","^Symbols. Hand-copied, painstakingly, with the careful strokes of an engineer reproducing something he didn't understand. Concentric arcs. Angular intersections. The same language as the carvings in the tunnels, as Mara's notebook, as the fragments you've been collecting for four days.","\n","^But this is the complete pattern. Or close to it. Martin Aldrich found the symbols in the deepest tunnels when they were first dug. He didn't know what they meant. He copied them because that's what engineers do: they document what they find.","\n","ev",{"VAR?":"has_mara_pages"},"/ev",[{"->":".^.b","c":true},{"b":["^ Mara categorized the symbols into three types: containment, feeding, opening. Martin's page shows the containment pattern. The full circuit. The lock that was supposed to hold the portal shut.",{"->":".^.^.^.26"},null]}],"nop","\n","ev",{"VAR?":"has_notebook_page"},{"VAR?":"has_mara_pages"},"!","&&","/ev",[{"->":".^.b","c":true},{"b":["^ Mara's notebook page showed fragments of this same pattern. Martin's page shows the whole thing. The full circuit. The lock that was supposed to hold the portal shut.",{"->":".^.^.^.35"},null]}],"nop","\n","ev",{"VAR?":"has_portal_mechanics"},"/ev",[{"->":".^.b","c":true},{"b":["^ The 1971 agent found fragments of this pattern and recommended sealing the shaft. If the Order had listened, the full pattern might have been preserved. Instead, the sinkhole broke it. Martin's copy is the only record of what it looked like before.",{"->":".^.^.^.41"},null]}],"nop","\n","^\"My mother wanted to burn these with the rest. I hid them.\" Gloria touches the edge of the drafting paper. \"I was nine. I didn't know what I was saving. But I knew it mattered.\"","\n",["ev",{"^->":"day_4.gloria_papers.0.45.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"This is what I need. To close the portal.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_4.gloria_papers.0.46.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Your father documented the containment system.\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_4.gloria_papers.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.45.s"},[{"#n":"$r2"}],"\n","^Gloria looks at you steadily. \"Then take it. And come back alive so I can stop worrying.\"","\n",{"->":"day_4.gloria_escape_offer"},{"#f":5}],"c-1":["ev",{"^->":"day_4.gloria_papers.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.46.s"},[{"#n":"$r2"}],"\n","^\"He was an engineer. He documented everything.\" She pauses. \"I don't think he understood what he was looking at. But he knew it was important. He wrote in his diary that the tunnels had been carved before the mine. That someone had been there first.\"","\n",{"->":"day_4.gloria_escape_offer"},{"#f":5}]}],{"#f":1}],"gloria_escape_offer":[["^Gloria reaches across the table and puts her hand on the envelope.","\n","^\"Take the papers. And listen to me.\" She holds your eyes. \"My truck is behind the diner. Keys under the floor mat. If tonight goes wrong. If you can't close it. If you need to run. You come here, you take the truck, and you drive. Don't stop until you can't hear the hum.\"","\n",["ev",{"^->":"day_4.gloria_escape_offer.0.4.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"I will.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_4.gloria_escape_offer.0.5.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Come with me. If I have to run.\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_4.gloria_escape_offer.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.4.s"},[{"#n":"$r2"}],"\n","^\"You better.\"","\n",{"->":"day_4.gloria_papers_end"},{"#f":5}],"c-1":["ev",{"^->":"day_4.gloria_escape_offer.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.5.s"},[{"#n":"$r2"}],"\n","^Gloria shakes her head. \"This is my town. My father's mine. I'm not leaving again.\" She squeezes your hand once, then lets go. \"But you are. If it comes to that.\"","\n",{"->":"day_4.gloria_papers_end"},{"#f":5}]}],{"#f":1}],"gloria_papers_end":["^You take the envelope. Martin Aldrich's engineering surveys. The complete containment pattern. Eighty years old and still legible.","\n","^Gloria unlocks the door. Flips the sign to OPEN.","\n","^\"Tonight, Val.\"","\n","^Everyone keeps saying that. Tonight.","\n",{"->":".^.^.day_4_hub"},{"#f":1}],"gloria_escape":[["ev",true,"/ev",{"VAR=":"has_escape_route","re":true},"ev",{"VAR?":"gloria_trust"},1,"+",{"VAR=":"gloria_trust","re":true},"/ev","^Gloria pours you coffee without asking. She stands across the counter and watches you drink it.","\n","^\"You look thin,\" she says. \"Thinner than yesterday.\"","\n","^\"I'm fine.\"","\n","^\"You're not fine. You look like you're disappearing.\" She says it matter-of-factly. The way she says everything. \"I've seen it before. In the workers. In Mara. It starts at the edges and works its way in.\"","\n",["ev",{"^->":"day_4.gloria_escape.0.18.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"My car is gone. Just vanished from the parking lot.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_4.gloria_escape.0.19.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"I need to know if you're with me, Gloria.\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_4.gloria_escape.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.18.s"},[{"#n":"$r2"}],"\n","^Gloria's face tightens. \"Then it's happening faster than I thought.\"","\n",{"->":"day_4.gloria_escape_offer_2"},{"#f":5}],"c-1":["ev",{"^->":"day_4.gloria_escape.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.19.s"},[{"#n":"$r2"}],"\n","^She puts down the coffee pot. Looks at you.","\n",{"->":"day_4.gloria_escape_offer_2"},{"#f":5}]}],{"#f":1}],"gloria_escape_offer_2":[["^\"My truck is behind the diner. I'll leave the keys in it.\" She says this firmly. A decision made. \"If things go wrong tonight. If you need to leave. You come here. You don't go to the mine. You come here and you take the truck and you drive.\"","\n",["ev",{"^->":"day_4.gloria_escape_offer_2.0.2.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"What about you?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_4.gloria_escape_offer_2.0.3.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Thank you, Gloria.\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_4.gloria_escape_offer_2.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.2.s"},[{"#n":"$r2"}],"\n","^\"I'll be here. I'm always here.\" She pauses. \"Somebody has to be.\"","\n",{"->":"day_4.gloria_escape_end"},{"#f":5}],"c-1":["ev",{"^->":"day_4.gloria_escape_offer_2.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.3.s"},[{"#n":"$r2"}],"\n","^\"Don't thank me. Just come back.\" She turns back to the counter. \"I'm tired of people not coming back.\"","\n",{"->":"day_4.gloria_escape_end"},{"#f":5}]}],{"#f":1}],"gloria_escape_end":[["^You finish the coffee. Gloria watches you go.","\n","^\"Val.\" You stop at the door. \"If you can't close it, run. Promise me.\"","\n",["ev",{"^->":"day_4.gloria_escape_end.0.4.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"I promise.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_4.gloria_escape_end.0.5.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"I'll do what I have to do.\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_4.gloria_escape_end.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.4.s"},[{"#n":"$r2"}],"\n","^She nods. Once.","\n",{"->":"day_4.day_4_hub"},{"#f":5}],"c-1":["ev",{"^->":"day_4.gloria_escape_end.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.5.s"},[{"#n":"$r2"}],"\n","^\"That's not a promise.\"","\n","^\"No.\"","\n","^She nods anyway.","\n",{"->":"day_4.day_4_hub"},{"#f":5}]}],{"#f":1}],"gloria_worried":[["ev",{"VAR?":"gloria_trust"},1,"+",{"VAR=":"gloria_trust","re":true},"/ev","^Gloria is behind the counter. She pours you coffee. Sits down across from you in the booth.","\n","^\"You look different today.\"","\n","^\"Different how?\"","\n","^\"Thinner. Paler.\" She studies your face. \"Like there's less of you.\"","\n","^You tell her about the car. About the shorthand slipping. About the way the motel room reset itself yesterday.","\n","^Gloria listens. Her hands are wrapped around her own mug, knuckles white.","\n","^\"It happened to Mara. The same way. She came in one morning and she couldn't remember her own phone number. Two days later she was gone.\" Gloria's voice is steady but her hands are not. \"You need to be careful tonight.\"","\n",["ev",{"^->":"day_4.gloria_worried.0.20.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"I need more than careful. I need help.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"day_4.gloria_worried.0.21.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"I'll be careful.\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"day_4.gloria_worried.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.20.s"},[{"#n":"$r2"}],"\n","^\"I know.\" She looks away. Out the window. At the mine. \"I'm not ready yet. Give me one more day.\"","\n","^You don't have one more day. You both know that. But you don't say it.","\n",{"->":"day_4.day_4_hub"},{"#f":5}],"c-1":["ev",{"^->":"day_4.gloria_worried.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.21.s"},[{"#n":"$r2"}],"\n","^\"Be more than careful.\" She reaches across the table and squeezes your wrist. Brief, hard. \"Be smart.\"","\n",{"->":"day_4.day_4_hub"},{"#f":5}]}],{"#f":1}],"gloria_guarded":["^The diner is open. Gloria is behind the counter. She pours you coffee. You drink it. The conversation is thin. Weather. The crowd at The Hollows. Nothing.","\n","^She watches you, but from a distance. You're still a stranger who works at the place that swallowed her town. Four days isn't enough to change that.","\n","^You leave. The coffee was good. It's the only thing that still tastes like anything.","\n",{"->":".^.^.day_4_hub"},{"#f":1}],"day_4_silas":["^You sit on the motel bed. Burner phone in hand.","\n","ev",{"VAR?":"silas_trust"},4,">=","/ev",[{"->":".^.b","c":true},{"b":["^ ",{"->":"day_4.silas_high"},{"->":".^.^.^.8"},null]}],"nop","\n","ev",{"VAR?":"silas_trust"},2,">=",{"VAR?":"silas_trust"},4,"<","&&","/ev",[{"->":".^.b","c":true},{"b":["^ ",{"->":"day_4.silas_mid"},{"->":".^.^.^.20"},null]}],"nop","\n","ev",{"VAR?":"silas_trust"},2,"<","/ev",[{"->":".^.b","c":true},{"b":["^ ",{"->":"day_4.silas_gone"},{"->":".^.^.^.28"},null]}],"nop","\n",{"#f":1}],"silas_high":["^You dial. It rings eight times. Each ring stretches longer than the last, the intervals filling with static.","\n","^On the ninth ring, the line connects. Or something connects. The static is a wall. Silas's voice comes through it in pieces, fragments thrown against interference.","\n","^\"...Val... can you...\"","\n","^\"Silas. I'm here.\"","\n","^\"...the team... I've been trying to... can't find Veinrock on...\" A burst of static. \"...the maps don't show it anymore. The town. It's not on any map. GPS shows... nothing. Desert. Empty...\"","\n","^The hum bleeds through the phone. You've never heard it on the line before. It's always been static. Now the hum is there too, underneath everything, like it's traveling through the signal.","\n","^\"...sent coordinates to... but the road doesn't... Ward out.\"","\n","^The line dies.","\n","ev",{"VAR?":"priority"},"str","^find_mara","/str","==","/ev",[{"->":".^.b","c":true},{"b":["^ Silas is still trying. He hasn't forgotten you. He hasn't forgotten Mara. But the town itself is being erased from the outside world. Veinrock is disappearing from maps, from GPS, from the landscape itself.",{"->":".^.^.^.24"},null]}],"nop","\n","ev",{"VAR?":"priority"},"str","^investigate_paranormal","/str","==","/ev",[{"->":".^.b","c":true},{"b":["^ The erasure isn't just affecting people. It's affecting geography. Veinrock is being removed from the map. If the portal opens fully, the town won't just be forgotten. It will never have existed.",{"->":".^.^.^.34"},null]}],"nop","\n","^He's still out there. Still fighting. That matters, even if the signal is dying.","\n",{"->":".^.^.day_4_hub"},{"#f":1}],"silas_mid":["^You dial. The phone rings. And rings. The tone is clear, clean, no static. The connection is fine. Nobody answers.","\n","^You hang up. Dial again. Same.","\n","^The phone rings into nothing. Silas isn't gone. The line connects. The system works. But on the other end, silence. As if the person who used to answer this number has forgotten why it matters.","\n","^You try a third time. On the fourth ring, you hear something. Not a voice. Not static. A click, like someone picking up and then setting the phone down without speaking. Then the line goes dead.","\n","^Maybe he answered and couldn't hear you. Maybe he answered and didn't know why he'd picked up.","\n","^Maybe he's already forgetting.","\n",{"->":".^.^.day_4_hub"},{"#f":1}],"silas_gone":["^You pick up the burner phone. Open the contacts. One number. No name.","\n","^You stare at it. You know this number is important. You know you've called it before, many times, and someone answered, and they told you things that mattered. But the name. The voice. The face of the person on the other end.","\n","^It's there. Somewhere. Behind a door that's closing.","\n","^S-something. A man's name. Dry voice. Careful.","\n","^You dial. No signal. The screen shows nothing. No bars. No network. As if the phone has forgotten how to connect to the outside world.","\n","^You set it down. You pick it up again. The number is still there. You should remember whose it is. You should.","\n","ev",{"VAR?":"erasure_level"},6,">=","/ev",[{"->":".^.b","c":true},{"b":["^ You can't. The name is gone. You know it was there this morning. You know it was there yesterday. But now there's just a number, and a feeling: someone, somewhere, once cared about what happened to you.",{"->":".^.^.^.18"},null]}],"nop","\n",{"->":".^.^.day_4_hub"},{"#f":1}],"day_4_tunnels":["ev",true,"/ev",{"VAR=":"visited_tunnels","re":true},"ev",{"VAR?":"dale_suspicion"},1,"+",{"VAR=":"dale_suspicion","re":true},"/ev","ev",{"VAR?":"erasure_level"},1,"+",{"VAR=":"erasure_level","re":true},"/ev","ev",{"VAR?":"mara_clues"},1,"+",{"VAR=":"mara_clues","re":true},"/ev","^The Hollows is closed. The parking lot is empty except for two vehicles: a white van marked HORRORCO ENTERTAINMENT and Dale's truck. The building is dark. No fog, no lights, no screaming. The mine entrance is just a hole in the mountain.","\n","^You circle to the back. Find the way in. You've done this before, or something close enough. The building accepts your entry the way it accepts everything: silently.","\n","^Inside, the attraction is skeletal. House lights off. Work lights on in scattered utility bays, casting yellow pools. The fog machines are silent. The speakers are dead. Without the show, you can see the infrastructure: plywood walls, painted foam, electrical conduit taped to stone. The mine behind the performance. The bones.","\n","^You move quickly. Past the upper zones. Past The Collapse, The Shaft, The Buried, The Drift. Names on placards in the dark. You find the way down.","\n","^Mid-level. You've been here before, briefly. On Night 3, a glimpse. Now you're walking it.","\n","^The tunnels are wider here. The ceiling is higher. The set dressing is sparser: fewer props, less paint, more raw stone. The transition from attraction to mine is gradual but unmistakable. The air is warmer. The hum is a constant now, not a background presence but the dominant sound, vibrating through the floor and walls.","\n","^You pass through zones you haven't seen: names you don't recognize on placards, scare positions empty and dark. The mid-level attractions are more intense, built for the premium ticket holders who pay extra for deeper access. Tighter corridors. More contact. Signs warning of claustrophobia, panic attacks, cardiac events.","\n","^Past the last mid-level zone, the attraction ends. No more placards. No more set dressing. Just a corridor of raw stone continuing deeper into the mountain, lit by caged utility bulbs spaced twenty feet apart.","\n","^On the wall, at the boundary between show and mine: a handprint in copper-colored dust. Small. A woman's hand.","\n","ev",{"VAR?":"has_mara_pages"},"/ev",[{"->":".^.b","c":true},{"b":["^ Mara's hand. She came this way. Through the show, past the mid-level, to the edge of the deep rooms. Following the same path you're following now.",{"->":".^.^.^.44"},null]}],"nop","\n","^Below the handprint, scratched into the stone with something sharp: an arrow. Pointing down.","\n","^You follow it.","\n","^The corridor descends. The utility lights thin out. The last one illuminates a steel door, open, hanging on its hinges. Past the door: darkness. But not total darkness. A faint glow from below, amber, pulsing. The hum is so strong here that your vision blurs at the edges. Your teeth ache. Your skin prickles with static.","\n","^The deep rooms.","\n","^You stand at the threshold. The air rushing upward from below is hot, almost scalding. It smells like copper and ozone and something older, something mineral and deep. The glow pulses in rhythm: brighter, dimmer, brighter, dimmer. The breathing that Bex described. The portal's respiration.","\n","^You can't go further. Not now. Not alone. Not without a plan.","\n","^But you can see the path. Steps cut into the stone, rough, old, descending in a spiral. At the bottom, somewhere below, the source of the hum. The source of the heat. The thing that's been eating this town for fifty years.","\n","^You memorize the route. You turn. You climb back up.","\n","^The daylight hits you like a wall when you step outside. You blink. Your hands are shaking. Your skin is flushed from the heat below and the cold desert air raises goosebumps across your arms.","\n","^You check your phone. Two hours until your shift. You walked deeper than you realized. The time evaporated.","\n",{"->":".^.^.day_4_hub"},{"#f":1}],"day_4_prepare":["^You close the motel room door. Sit on the bed. Spread everything out.","\n","ev",{"VAR?":"has_mara_recording"},"/ev",[{"->":".^.b","c":true},{"b":["^ Mara's voice recorder. You press play. Her voice fills the room, steady and professional. \"Day eight. I've confirmed access to the lower levels...\" You listen to the whole thing again. Day eight. Day nine. Day ten. Then silence.",{"->":".^.^.^.6"},null]}],"nop","\n","ev",{"VAR?":"has_mara_pages"},"/ev",[{"->":".^.b","c":true},{"b":["^ Mara's pages. A hand-drawn map of all three levels, the portal marked at the bottom. Three types of symbols: containment, feeding, opening. A timeline connecting each new scare zone to a disappearance. \"The containment is being undermined from inside.\"",{"->":".^.^.^.12"},null]}],"nop","\n","ev",{"VAR?":"has_notebook_page"},"/ev",[{"->":".^.b","c":true},{"b":["^ Mara's notebook page from the maintenance tunnel. The diagram of symbols, painstakingly copied. Her annotations: arrows, question marks, circles around patterns. \"Not decorative. Functional?\" And the torn sentence that stops mid-thought.",{"->":".^.^.^.18"},null]}],"nop","\n","ev",{"VAR?":"has_portal_mechanics"},"/ev",[{"->":".^.b","c":true},{"b":["^ Silas's intel, written down in your own shorthand (you have to concentrate to read it now): the Order investigated the mine in 1971. Containment sigils. Field agent recommended sealing the shaft. The Order filed the report and did nothing.",{"->":".^.^.^.24"},null]}],"nop","\n","ev",{"VAR?":"has_sinkhole_history"},"/ev",[{"->":".^.b","c":true},{"b":["^ The newspaper clipping. June 15, 1973. The Aldrich Silver Mine. Forty-eight dead. Rescue teams found the shaft had grown deeper, not shallower — \"beyond the reach of available sounding equipment.\"",{"->":".^.^.^.30"},null]}],"nop","\n","ev",{"VAR?":"has_horrorco_filing"},"/ev",[{"->":".^.b","c":true},{"b":["^ HorrorCo Entertainment, LLC. Incorporated June 22, 1973. One week after the sinkhole. M. Aldrich, Registered Agent. A dead man's name on a company that wouldn't arrive for twenty-five years.",{"->":".^.^.^.36"},null]}],"nop","\n","ev",{"VAR?":"has_dale_file"},"/ev",[{"->":".^.b","c":true},{"b":["^ Dale Ruskin. Hired March 3, 1998. $187,000 salary. Twenty-seven identical performance reviews. Zero sick days. Zero vacation days.",{"->":".^.^.^.42"},null]}],"nop","\n","ev",{"VAR?":"has_census_data"},"/ev",[{"->":".^.b","c":true},{"b":["^ Veinrock, Nevada. Population 0 in 1975. Population 47 in 1999. Population 54 in 2020. Nobody has died or moved away in two decades.",{"->":".^.^.^.48"},null]}],"nop","\n","ev",{"VAR?":"has_gloria_testimony"},"/ev",[{"->":".^.b","c":true},{"b":["^ Gloria: \"It opened. Like something underneath had been pushing up for a long time and the mine finally gave it room.\"",{"->":".^.^.^.54"},null]}],"nop","\n","ev",{"VAR?":"has_ritual_knowledge"},"/ev",[{"->":".^.b","c":true},{"b":["^ The containment pattern. Complete. Either from Bex's decades of firsthand knowledge or from Martin Aldrich's engineering documents. The lock that's supposed to hold the portal shut.",{"->":".^.^.^.60"},null]}],"nop","\n","ev",{"VAR?":"has_escape_route"},"/ev",[{"->":".^.b","c":true},{"b":["^ Gloria's truck. Behind the diner. Keys under the mat. The way out.",{"->":".^.^.^.66"},null]}],"nop","\n","^You lay it all out. Every piece. Every fragment. And you look at what you have and what you don't.","\n","ev",{"VAR?":"has_ritual_knowledge"},{"VAR?":"has_notebook_page"},"&&",{"VAR?":"has_portal_mechanics"},"&&","/ev",[{"->":".^.b","c":true},{"b":["^ You could seal it. The containment pattern, the symbol mechanics, the portal's history. You have the knowledge to attempt the ritual. You'd need to be at the portal itself, during the pause between breaths, and you'd need to survive long enough to complete the pattern. But you could try.",{"->":".^.^.^.78"},null]}],"nop","\n","ev",{"VAR?":"has_escape_route"},{"VAR?":"has_dale_file"},{"VAR?":"has_horrorco_filing"},"||",{"VAR?":"has_sinkhole_history"},"||","&&","/ev",[{"->":".^.b","c":true},{"b":["^ You could run. Gloria's truck, the evidence you've gathered. Drive to Vegas. Call the Order. Turn over everything and let someone else finish it. You'd survive. Probably. If the erasure doesn't follow you. If anyone remembers you when you arrive.",{"->":".^.^.^.90"},null]}],"nop","\n","ev",{"VAR?":"has_notebook_page"},{"VAR?":"has_portal_mechanics"},"||",{"VAR?":"has_ritual_knowledge"},"!","&&","/ev",[{"->":".^.b","c":true},{"b":["^ You could go to the portal. But you don't know how to close it. You'd be going in blind, with knowledge but no method. You could try to understand it. You could try to go through it. You don't know what's on the other side.",{"->":".^.^.^.101"},null]}],"nop","\n","ev",{"VAR?":"has_notebook_page"},"!",{"VAR?":"has_portal_mechanics"},"!","&&",{"VAR?":"has_ritual_knowledge"},"!","&&","/ev",[{"->":".^.b","c":true},{"b":["^ You don't have enough. Not enough to seal it, not enough to understand it, not enough to bring back to the Order. You're going into tonight with instinct and stubbornness and not much else.",{"->":".^.^.^.114"},null]}],"nop","\n","^You close the notebook. You know what you know. You know what you don't.","\n","^Tonight.","\n",{"->":".^.^.day_4_hub"},{"#f":1}],"day_4_end":[["^Late afternoon. The sun drops fast in the desert. One minute it's above the mountains and the next it's behind them and the sky is going orange and purple and the shadows stretch across the lot.","\n","^You walk to The Hollows.","\n","^Four days. Four nights. Your shoulders ache from the costumes. Your throat is raw from the masks. The bridge of your nose has a permanent red stripe. Your hands smell like copper and greasepaint no matter how many times you wash them.","\n","^The hum is louder today. Louder than it's ever been. You can feel it in the road, in the soles of your boots, traveling up through your bones. The building at the end of the road seems larger tonight. Darker. The mine entrance swallows light.","\n","^The queue is building. Thursday night crowd, decent. Families. Couples. Groups of friends with the nervous laughter of people about to pay money to be frightened. They don't know what they're feeding.","\n","ev",{"VAR?":"has_mara_recording"},"/ev",[{"->":".^.b","c":true},{"b":["^ Mara knew. \"The fear is not a byproduct. It's the product.\" Every scream tonight goes down. Into the mine. Into the portal.",{"->":".^.^.^.14"},null]}],"nop","\n","^The staff entrance. The corridor. The fluorescent lights.","\n","ev",{"VAR?":"dale_suspicion"},5,">=","/ev",[{"->":".^.b","c":true},{"b":["^ Dale is at the check-in desk. He sees you. His smile is the same smile it always is. He doesn't say anything. He doesn't need to. You both know tonight is different.",{"->":".^.^.^.24"},null]}],"nop","\n","ev",{"VAR?":"dale_suspicion"},5,"<","/ev",[{"->":".^.b","c":true},{"b":["^ Dale is at the check-in desk. \"Val! Big night tonight. Full house. Make it real, people.\" Same words. Same clipboard. Same Dale.",{"->":".^.^.^.32"},null]}],"nop","\n","^You walk to the costume room.","\n","ev","str","^Tonight.","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"night_4"},{"#f":5}]}],{"#f":1}],"#f":1}],"night_4":[{"->":".^.costume_room_4"},{"costume_room_4":["^The schedule board outside the costume room. Your name is there. Val Rowan. Zone 8.","\n","^Mid-level.","\n","^You've never been assigned mid-level. Three nights in the uppers: The Collapse, The Shaft, The Buried. Entry-level zones. Tonight, for the first time, you're going deeper.","\n","ev",{"VAR?":"dale_suspicion"},5,">=","/ev",[{"->":".^.b","c":true},{"b":["^ You read the assignment twice. Zone 8 is mid-level. More cameras. More floor managers. More eyes on you. Dale put you here because he wants you close. Where he can see you. A promotion that feels like a leash.",{"->":".^.^.^.12"},null]}],"nop","\n","ev",{"VAR?":"dale_suspicion"},5,"<","/ev",[{"->":".^.b","c":true},{"b":["^ Mid-level is normal progression. Three nights in the uppers, you've proven you can handle the work. Zone 8. Closer to the deep rooms than you've ever been during a live show.",{"->":".^.^.^.20"},null]}],"nop","\n","^The costume room is full tonight. Thursday crowd means a full roster. Actors at every station, pulling on base layers, testing prosthetics, checking masks. The energy is different from the slow Wednesday you worked last night. Louder. More electric.","\n","^Bex is at their station.","\n","ev",{"VAR?":"bex_relationship"},5,">=","/ev",[{"->":".^.b","c":true},{"b":["^ ",{"->":"night_4.costume_bex_ally"},{"->":".^.^.^.32"},null]}],"nop","\n","ev",{"VAR?":"bex_relationship"},1,">=",{"VAR?":"bex_relationship"},5,"<","&&","/ev",[{"->":".^.b","c":true},{"b":["^ ",{"->":"night_4.costume_bex_neutral"},{"->":".^.^.^.44"},null]}],"nop","\n","ev",{"VAR?":"bex_relationship"},0,"<=","/ev",[{"->":".^.b","c":true},{"b":["^ ",{"->":"night_4.costume_bex_threat"},{"->":".^.^.^.52"},null]}],"nop","\n",{"#f":1}],"costume_bex_ally":["^They're quiet tonight. Focused. They fit your costume without small talk. The prosthetics go on fast. Greasepaint, mask, done. Their hands are steady but there's a tension behind them. The same tension you saw this morning at the motel, when they drew the containment pattern on the notepad.","\n","^They hand you the mask. And then, quietly, close enough that no one else can hear:","\n","^\"Zone 8 puts you near the south stairwell. At the back of the zone, past the last scare position, there's a utility corridor. It goes down. Below that is the service tunnel to the deep rooms.\"","\n","^They adjust your collar. To anyone watching, they're fixing a costume.","\n","^\"I'll find you after midnight.\"","\n",{"->":".^.^.zone_8_briefing"},{"#f":1}],"costume_bex_neutral":[["^They work at their usual pace. Professional. Efficient. Prosthetic gash, greasepaint, mask. Same routine, fourth night running. They don't mention this morning. They don't mention anything about what's below.","\n",["ev",{"^->":"night_4.costume_bex_neutral.0.2.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"Any advice for mid-level?\"",{"->":"$r","var":true},null]}],"ev","str","^Say nothing.","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["ev",{"^->":"night_4.costume_bex_neutral.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.2.s"},[{"#n":"$r2"}],"\n","^\"It's more physical than the uppers. The guests expect contact. Don't break character, don't break bones.\" A pause. \"The zones are longer down there. Wider corridors. Easier to get turned around.\"","\n",{"->":"night_4.zone_8_briefing"},{"#f":5}],"c-1":["\n","^They finish the costume. Nod once. Move to the next actor.","\n",{"->":"night_4.zone_8_briefing"},{"#f":5}]}],{"#f":1}],"costume_bex_threat":["^They don't look at you. Hands moving fast. Greasepaint, prosthetic, mask. Mechanical. They finish in under two minutes, which is half the time they usually take.","\n","^They step back. Still no eye contact. This morning they stood in a parking lot and told you to run. You didn't run.","\n","^They move to the next actor without a word.","\n",{"->":".^.^.zone_8_briefing"},{"#f":1}],"zone_8_briefing":["^Zone 8: The Seam.","\n","^The briefing is delivered by a floor manager you haven't met before. Short woman, headset, clipboard. She talks fast.","\n","^\"The Seam is a transition zone. Guests come down from the uppers, the corridor narrows, the ceiling drops, and you're the first thing they see on mid-level. The concept is geological pressure. You're a miner who got caught in a rock shift. Half your body is embedded in the wall. You reach for them as they pass.\"","\n","^She demonstrates the position: one arm extended through a gap in the set wall, the other hidden behind foam rock. The gap is tight. Your torso has to twist to fit.","\n","^\"Make it slow. Make it desperate. You're trapped and you need their help. When they get close, grab. Not hard. Just enough to make them jump.\"","\n","^She checks her clipboard. \"Full house tonight. Groups of four every three minutes. Stay hydrated. Radio's on channel 3 for mid-level.\"","\n","^You walk down to Zone 8. Past the upper zones, past the stairwell, deeper into the building. The set dressing changes. The plywood walls are thicker. The lighting is more sophisticated: fiber optics in the ceiling, simulating fissures in rock. The fog is denser. The sound design is layered: creaking timbers, distant rockfalls, the drip of water.","\n","^And underneath all of it, the hum. Louder here than in the uppers. Not much louder. But enough.","\n",{"->":".^.^.the_seam"},{"#f":1}],"the_seam":["^You find your position. The gap in the wall. You wedge yourself in, one arm through, one arm braced behind the foam rock. The fit is tight. Your ribs compress. Your breath is loud in the narrow space.","\n","^The first group comes through.","\n","^Four people. College age. They're already scared from the upper zones, voices tight, moving close together. The corridor narrows around them. The ceiling drops. They hunch. And then your arm comes through the wall.","\n","^The scream is genuine. One of them grabs another. They stumble past, fast, looking back at your reaching hand. You hold the position. They round the corner. Gone.","\n","^Reset. Next group. Three minutes.","\n","^Contact scares are a different craft. In the uppers, you triggered reactions. A window, a lunge, a scream. The guest jumps and it's over. Down here, you sustain them. Your arm comes through the wall and stays. The fingers move. You grab. The guests are supposed to feel you. That's the contract they signed when they bought the premium ticket. The startle is just the beginning. What follows is the slow, deliberate certainty that something in the wall has you and is not letting go.","\n","^After about ten groups, you start to find it. The grab has to be firm enough to register but loose enough to release clean. You learn to read the hesitation: the moment a guest feels your hand and hasn't decided yet whether to pull away or freeze. That's the window. You hold through it. Then you let go. They stumble forward. Next group.","\n","^The set design is better down here. The sound is spatial, not just directional. Creaking timbers from above, water dripping from below, the low grinding of rock against rock somewhere behind the walls. The fog is thicker and it doesn't pulse on a timer. It seeps. The zones bleed into each other instead of having clean transitions. No painted plywood dividers, no glow-tape pathways. The corridor narrows and widens and narrows again like a throat. The real stone is right there, inches behind the foam. You can feel it when you brace your arm. Cold and rough and older than anything built on top of it.","\n","^A group of five comes through. They've done this before. Extreme haunt veterans. You can tell by the way they spread out instead of bunching up, by the way they lean into the corridor instead of flinching from it. When your arm comes through the wall, one of them grabs back. Wraps a hand around your wrist and grins in the dark. Holds on. You're supposed to be the one grabbing, but now you're locked together and neither of you is letting go. You wait them out. After four seconds, they release, laugh, slap their friend's shoulder. Move on.","\n","^A couple. One of them wanted this. The other didn't. You can see it in the body language: one pulling forward, one braking. The reluctant one is pressed against the far wall of the corridor, as far from your position as the narrow space allows. When your arm comes through, the willing one flinches and laughs. The reluctant one makes a sound that isn't a scream. It's smaller than that. A caught breath. Their eyes are wet. The contact scare hits different when the person didn't choose to be here. You let go fast. They hurry past. You hear them arguing around the corner, voices tight and hushed.","\n","^A solo guest. Mid-level allows singles. They walk through alone, hands at their sides, pace steady. No phone light. No nervous chatter. When your arm comes through the wall, they stop. They don't scream. They don't flinch. They look at your hand. Your fingers, still curled in the grab position, greasepaint cracking at the knuckles. They reach out and touch your fingers. Gently. Like checking if you're real. Skin on skin, for just a moment. Then they walk on without looking back. It's the most unsettling reaction you've had all week.","\n","^This is the job. Sustained. Physical. Intimate. Four nights in and your body is a catalogue of compound damage. The spinal twist in the wall sits on top of the shoulder from Night 1's window, which sits on top of the leg ache from Night 2's stalker walk, which sits on top of the core strain from Night 3's narrow gap. The prosthetic gash has rubbed a raw welt into your cheek that stings with each extension. Four nights of greasepaint have left a chemical smell on your skin that soap won't touch. You can taste copper in the back of your throat, though you don't know if that's the makeup or the mine.","\n","^By 10:30, you've done maybe forty groups. The rhythm is in your body. Extend, grab, hold, release. Reset. The three-minute interval is automatic. You don't count anymore. You feel the next group coming in the vibration of the floor, in the shift of the fog, in the change in air pressure when bodies enter the corridor.","\n","^But the rhythm is wrong tonight.","\n",{"->":".^.^.show_wrong"},{"#f":1}],"show_wrong":["^It starts with the fog.","\n","^The fog machines run on a cycle. You've been around them long enough to recognize it: thirty seconds of output, thirty seconds of rest. The fog should pulse. Tonight it doesn't. It pours. Continuous. Thicker than the machines produce. And warm. Not the lukewarm mist of glycol vapor. Warm like breath. Warm like the air that rises from below.","\n","^It pools at your feet. It doesn't dissipate the way machine fog does. It settles. It has weight.","\n","^Then the hum.","\n","^A guest stops in front of your position. Not frozen in fear. Confused. She tilts her head, listening.","\n","^\"Is that part of the show?\" she asks her friend. \"That sound?\"","\n","^Her friend listens. Nods. \"It's like a bass speaker. Really low. Can you feel it?\"","\n","^They can hear it. The hum that's been in your back teeth for four days. The guests can hear it now.","\n","^They move on. The next group has the same reaction. One man puts his hand on the wall and frowns. \"The wall is vibrating,\" he says. Nobody laughs.","\n","^Between groups, you watch the corridor. An animatronic arm, mounted to the wall thirty feet ahead of your position, goes through its scare cycle. Extend, retract, extend. The rhythm should be mechanical. Regular. Tonight the movement is wrong. Too smooth. Too organic. The arm extends and instead of retracting on its timer, it pauses. Turns. The fingers flex independently, one at a time, in a sequence that no programming would produce.","\n","^It points at you.","\n","^Then it retracts. Returns to its cycle. Extend, retract. Normal.","\n","^The next group enters your zone. Four guests. You extend your arm through the wall, reaching, desperate.","\n","^The woman in front looks directly at you.","\n","^She doesn't scream. She doesn't flinch. She looks at your arm, your face behind the mask, your body wedged in the gap. And her eyes don't register you. She's not being brave. She's not performing composure. She doesn't see you. She looks through you the way you'd look through glass.","\n","^Her friends react. They jump, they grab each other, they hurry past. But she walks through your zone like you aren't there. Like the wall is empty.","\n","^The erasure. Visible now. You're becoming transparent to people who don't know you. To the general public, you're not quite real.","\n","^Another group. You extend your arm. A man flinches, and then he laughs. \"Good one,\" he says. But the laugh is uncertain. Because behind you, from deeper in the wall, something else moved. Something you didn't do. The foam rock shifted. The man saw it. You felt it.","\n","^Between groups, in the silence, you hear one of the other actors. Two positions down. A voice you don't recognize, delivering a line:","\n","^\"She went down. Past the last light. She's still there.\"","\n","^It's not show dialogue. There's no scripted line like that in any zone. You lean out of your position to look. The actor is standing in the corridor, facing nothing, mouth slightly open. After a moment, they blink. Shake their head. Step back into position.","\n","^They don't know they said it.","\n",{"->":".^.^.figure_returns"},{"#f":1}],"figure_returns":[["^The Figure is back.","\n","^After Night 3's absence, after the empty corridors and the silence where something should have been standing, the Figure is back.","\n","^You see it first at the far end of the corridor, past the last scare position in Zone 8. Where the set dressing ends and the raw stone begins. Standing motionless. The burlap mask. The faded base layer. The posture you've been seeing for four nights.","\n","^But tonight it doesn't vanish. It stays. It watches you work.","\n","^A group passes through your zone. You extend, they scream, they move on. You look back. The Figure is still there. Unchanged. Watching.","\n","^The second sighting is worse.","\n","^The Figure is in your zone. Among the guests. A group of six comes through, bunched together, navigating the narrow corridor. And the Figure is standing in the middle of them. Not moving. Not performing. Just there, like a pillar, and the guests flow around it without seeing it. They part and reform around the motionless shape the way water moves around a stone.","\n","^One of the guests brushes against the Figure's shoulder. She doesn't react. She doesn't feel it.","\n","^Nobody sees it but you.","\n","^The third sighting.","\n","^Between groups. The corridor is empty. You lean out of your position to stretch your shoulder. And the Figure is ten feet away.","\n","^Close enough, finally, to see detail. The base layer is worse than it was two nights ago. The fabric has gone translucent in places, thin enough to see the shape of bones beneath. The mineral crust runs up from the hems, calcified white against faded black. Where the seams have split, the fabric curls back like dead skin. The burlap mask is rough, handmade, stitched tight over the face beneath. No eye holes. The fabric is unbroken.","\n","ev",{"VAR?":"mara_clues"},4,">=","/ev",[{"->":".^.b","c":true},{"b":["^ It's Mara. You're certain now. The height. The build. The way she stands, weight slightly forward, one hand at her side and one half-raised. You've seen photographs. You've heard her voice on the recorder. This is Mara Castillo. Or what's left of her. What the mine made of her.",{"->":".^.^.^.30"},null]}],"nop","\n","ev",{"VAR?":"mara_clues"},2,">=",{"VAR?":"mara_clues"},4,"<","&&","/ev",[{"->":".^.b","c":true},{"b":["^ The build is slight. The height is wrong for most of the male actors you've seen. The posture is careful, deliberate, like someone trained to observe. Like a researcher. Like an investigator.",{"->":".^.^.^.42"},null]}],"nop","\n","ev",{"VAR?":"mara_clues"},2,"<","/ev",[{"->":".^.b","c":true},{"b":["^ You can't make out anything identifying. The ruined base layer. The mask. The stillness. Whatever this is, it's been here longer than you have.",{"->":".^.^.^.50"},null]}],"nop","\n","^The Figure raises one hand. Slowly. The movement takes seconds, like something moving through water.","\n","^It points down.","\n","^Not at the floor. Through it. Into the earth. Into the mine beneath the mine.","\n","^Then the Figure is gone. Between one blink and the next. The corridor is empty.","\n","^Down.","\n","ev","str","^Leave your zone.","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n",{"->":"night_4.break_away"},{"#f":5}]}],{"#f":1}],"break_away":["^It's past midnight. The crowds have thinned. The three-minute interval has stretched to five, then eight. Long silences between groups. The fog still pours. The hum still builds.","\n","^You step out of the wall. Peel the foam rock away from your shoulder. Flex your arm, which has gone numb from the twist. You leave the mask on. If anyone sees you, you're an actor between positions. Nothing unusual.","\n","ev",{"VAR?":"bex_relationship"},5,">=","/ev",[{"->":".^.b","c":true},{"b":["^ Bex said the south stairwell. At the back of Zone 8, past the last scare position, the utility corridor. You walk toward it. The set dressing thins. The fiber-optic fissures in the ceiling give way to caged utility bulbs. The plywood walls end. Raw stone.",{"->":".^.^.^.10"},null]}],"nop","\n","ev",{"VAR?":"bex_relationship"},5,">=","/ev",[{"->":".^.b","c":true},{"b":["^ The stairwell is where Bex said it would be. A steel door, propped open with a wedge. Beyond it, concrete steps going down. The air rising from below is warm.",{"->":".^.^.^.18"},null]}],"nop","\n","ev",{"VAR?":"bex_relationship"},5,"<",{"VAR?":"visited_tunnels"},"&&","/ev",[{"->":".^.b","c":true},{"b":["^ You know the way. You were here this afternoon, in daylight, without the show running. The path down from mid-level to the deep rooms. You retrace your steps. Past the last zone, past the set dressing, into the raw stone.",{"->":".^.^.^.28"},null]}],"nop","\n","ev",{"VAR?":"bex_relationship"},5,"<",{"VAR?":"visited_tunnels"},"!","&&",{"VAR?":"has_mara_pages"},"&&","/ev",[{"->":".^.b","c":true},{"b":["^ Mara's map. The hand-drawn layout of all three levels, the portal marked at the bottom. You've memorized the route. Past Zone 8, through the utility corridor, down.",{"->":".^.^.^.41"},null]}],"nop","\n","ev",{"VAR?":"bex_relationship"},5,"<",{"VAR?":"visited_tunnels"},"!","&&",{"VAR?":"has_mara_pages"},"!","&&","/ev",[{"->":".^.b","c":true},{"b":["^ You don't have a map. You don't have directions. But you have the hum and the heat, and they both pull the same direction: down. You follow them past the last zone, past the set dressing, into stone.",{"->":".^.^.^.55"},null]}],"nop","\n","^The transition is the same as always. Plywood gives way to rock. Paint gives way to dust. The temperature rises. The hum gets louder with every step down, vibrating through the handrails, through the steps, through the bones of your feet.","\n","^Mid-level. Below mid-level. The corridors are wider here. The ceiling is higher. No set dressing. No scare positions. No guests. Just the mine.","\n","ev",{"VAR?":"bex_relationship"},5,">=","/ev",[{"->":".^.b","c":true},{"b":["^ ",{"->":"night_4.descent_ally"},{"->":".^.^.^.67"},null]}],"nop","\n","ev",{"VAR?":"bex_relationship"},1,">=",{"VAR?":"bex_relationship"},5,"<","&&","/ev",[{"->":".^.b","c":true},{"b":["^ ",{"->":"night_4.descent_neutral"},{"->":".^.^.^.79"},null]}],"nop","\n","ev",{"VAR?":"bex_relationship"},0,"<=","/ev",[{"->":".^.b","c":true},{"b":["^ ",{"->":"night_4.descent_threat"},{"->":".^.^.^.87"},null]}],"nop","\n",{"#f":1}],"descent_ally":[["^A voice in the dark ahead of you. Quiet. Familiar.","\n","^\"This way.\"","\n","^Bex. Standing at a junction where the tunnel forks. They're not in their costume room clothes. They're wearing the same black outfit, same boots, but they look different down here. More present. More real. As if the mine is where they belong and the surface was the costume.","\n","^\"Stay close. Don't touch the walls.\"","\n","^They move. You follow. They navigate the deep rooms with the certainty of long practice: every fork, every dead end, every cluster of carvings on the walls. They don't hesitate. They don't check. They know this place the way you know your own apartment. Better.","\n","^The tunnels narrow. The air gets hotter. The hum gets louder. You pass carvings you haven't seen before: concentric arcs, angular intersections, the same language as the containment pattern Bex drew this morning. Some are sharp and fresh. Some are worn almost smooth. Decades of tracing. Bex's decades.","\n","ev",{"VAR?":"has_ritual_knowledge"},"/ev",[{"->":".^.b","c":true},{"b":["^ You recognize the symbols now. Containment glyphs. Bex's handiwork. The lines they've been reinforcing, night after night, for longer than they can remember. The lock they've been holding shut.",{"->":".^.^.^.16"},null]}],"nop","\n","^\"Bex.\"","\n","^\"Keep moving.\"","\n","^\"How many times have you walked this route?\"","\n","^They don't answer. They walk.","\n","^Ten minutes. Fifteen. The tunnels descend in long, gradual slopes. The heat builds. The amber glow appears in the distance, faint at first, then brighter. Pulsing. The breathing.","\n","^And Bex starts to fade.","\n","^It's not metaphorical. You're walking behind them and their footsteps get quieter. Not softer, like they're trying to be silent. Quieter, like the sound itself is thinning. Their outline in the glow from below becomes less distinct. The edges blur.","\n","^\"Bex.\"","\n","^\"I'm here.\" Their voice sounds like it's coming from further away. They're right in front of you. \"The closer I get, the less there is of me. I told you.\"","\n","^You keep walking. Bex keeps fading. Their shape in the tunnel ahead is a sketch now, an impression. The black clothes are gray. The boots make no sound.","\n","^At a junction, the last junction, where the tunnel opens into a wider chamber and the spiral steps begin their descent to the portal, Bex stops.","\n","^\"I can't.\" Their voice is a whisper. Not because they're whispering. Because there's not enough of them left to speak at full volume. \"This is as far as I go.\"","\n","^You look at them. In the amber light pulsing from below, Bex is barely there. A shape. A suggestion.","\n","^\"Left at the fork. Down the spiral steps. You'll feel it before you see it.\"","\n","^A pause. The pulsing light. The hum.","\n","^\"Val. When you get to the bottom, you need to...\" The word isn't there. You can see them searching for it. Their mouth forms the shape of something and nothing comes out. They try again. \"The pattern starts at the...\" Gone. The knowledge they carried for decades, the one thing they stayed for, dissolving at the threshold of the thing that's been dissolving them.","\n","^Their hand reaches toward you. Whether to touch you or to hold onto something solid, you can't tell. The hand is barely visible.","\n","^\"Val.\" Almost inaudible. \"It was good. Having someone to talk to.\"","\n",["ev",{"^->":"night_4.descent_ally.0.54.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"I'll come back.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_4.descent_ally.0.55.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Thank you, Bex.\"",{"->":"$r","var":true},null]}],"ev","str","^Turn and look back.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["ev",{"^->":"night_4.descent_ally.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.54.s"},[{"#n":"$r2"}],"\n","^The shape that might be Bex doesn't respond. You don't know if they heard you. You don't know if there's enough of them left to hear.","\n",{"->":"night_4.descent_portal"},{"#f":5}],"c-1":["ev",{"^->":"night_4.descent_ally.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.55.s"},[{"#n":"$r2"}],"\n","^Nothing. The tunnel ahead is empty. Between one breath and the next, the shape was there and then it wasn't. Like a signal that finally cut out.","\n",{"->":"night_4.descent_portal"},{"#f":5}],"c-2":["\n","^The tunnel behind you is empty. Bex is gone. You didn't see them leave. You didn't hear them go. They were there and then they were less there and then they weren't.","\n",{"->":"night_4.descent_portal"},{"#f":5}]}],{"#f":1}],"descent_neutral":["^You navigate alone.","\n","^The deep rooms are disorienting. The tunnels fork and merge and fork again. The stone is uniform. The utility lights are spaced too far apart, leaving long stretches of darkness between pools of yellow. Without a guide, you lose your bearings.","\n","ev",{"VAR?":"bex_relationship"},1,">=","/ev",[{"->":".^.b","c":true},{"b":["^ Bex said stay left. At the motel this morning, squinting in the sun: \"Past the stairwell, past mid-level, when the tunnel forks. Stay left. The right passages loop.\"",{"->":".^.^.^.10"},null]}],"nop","\n","ev",{"VAR?":"bex_relationship"},1,">=","/ev",[{"->":".^.b","c":true},{"b":["^ You stay left. The left passages descend. Every fork, take the left. The hum gets louder. The air gets hotter. You're going the right direction.",{"->":".^.^.^.18"},null]}],"nop","\n","ev",{"VAR?":"bex_relationship"},1,"<","/ev",[{"->":".^.b","c":true},{"b":["^ You follow the heat. You follow the hum. They both pull the same way: down, always down. When the tunnel forks, you test both directions with your hand held out. The warmer passage. The louder hum. You take it.",{"->":".^.^.^.26"},null]}],"nop","\n","ev",{"VAR?":"bex_relationship"},1,"<","/ev",[{"->":".^.b","c":true},{"b":["^ You double back twice. Lose twenty minutes in a loop that deposits you where you started. The third time, you find the trick: the warm air rises from the left passages. The right passages recirculate.",{"->":".^.^.^.34"},null]}],"nop","\n","ev",{"VAR?":"visited_tunnels"},"/ev",[{"->":".^.b","c":true},{"b":["^ You were here this afternoon. The route is familiar. Not comfortable, but recognizable. You move faster than you would otherwise. The handprint on the wall. The arrow scratched into stone. Mara's trail.",{"->":".^.^.^.40"},null]}],"nop","\n","^Deeper. The carvings appear on the walls. The amber glow from below. The heat. The breathing rhythm of the portal, felt in the floor before it's seen.","\n","^The spiral steps.","\n",{"->":".^.^.descent_portal"},{"#f":1}],"descent_threat":["ev",{"VAR?":"dale_suspicion"},2,"+",{"VAR=":"dale_suspicion","re":true},"/ev","^You make it past the last mid-level zone. Into the raw stone. And the obstacles start.","\n","^A floor manager at the junction you need to pass through. Standing there with a clipboard, checking something, blocking the corridor. You wait. They don't leave. You circle around through a parallel tunnel and come at the junction from the other side.","\n","^Past the junction, a door that wasn't locked this afternoon. The keycard reader blinks red. You try the handle. Nothing. You look for another way. A ventilation shaft, too small. A maintenance hatch, bolted. You backtrack and find a side corridor that bypasses the door, adding fifteen minutes to the route.","\n","^Dale's voice on the radio. Channel 3. \"Val, you're off position. Return to Zone 8.\"","\n","^You turn the radio off.","\n","ev",{"VAR?":"bex_relationship"},0,"<=","/ev",[{"->":".^.b","c":true},{"b":["^ Bex told Dale. This morning, after the warning, after you refused to leave. They went back to the mine and they told Dale you were going to try something tonight. Not out of malice. Out of the system asserting itself through them. Or out of a desperate, misguided hope that Dale could keep you safe the way they couldn't.",{"->":".^.^.^.22"},null]}],"nop","\n","ev",{"VAR?":"bex_relationship"},0,"<=","/ev",[{"->":".^.b","c":true},{"b":["^ It doesn't matter why. Dale knows. And the deep rooms are harder to reach because of it.",{"->":".^.^.^.30"},null]}],"nop","\n","^You push through. Past the obstacles, past the locked doors, down. The hum pulls you. The heat pulls you. Whatever Dale did to slow you down, the mine itself is drawing you in.","\n","^The carvings on the walls. The amber glow. The spiral steps.","\n",{"->":".^.^.descent_portal"},{"#f":1}],"descent_portal":["ev",{"VAR?":"erasure_level"},1,"+",{"VAR=":"erasure_level","re":true},"/ev","^The spiral steps. Rough-cut stone, old, descending in a tight helix. The amber light pulses from below, casting your shadow in long spirals on the wall. The hum is so loud now it's not a sound. It's a pressure. A weight on your chest. Your vision blurs at the edges. Your teeth ache. The fillings in your molars vibrate.","\n","^The air is hot. Not warm. Hot. Each breath singes the back of your throat. The copper-ozone smell fills your sinuses. Under it, something older. Mineral. The smell of deep stone, of earth that hasn't seen air in millennia.","\n","^You descend.","\n","^The steps are worn smooth in the center. Thousands of feet, over thousands of years, walking this same spiral. Not just miners. Not just HorrorCo employees. Someone carved these steps long before the mine existed. Someone was coming down here when this was just a mountain with something underneath it.","\n","^The glow brightens. The pulsing is visible now: brighter, dimmer, brighter, dimmer. The rhythm Bex described. The portal's respiration. You can feel it in your body. The exhale pushes outward, a wave of heat and pressure. The inhale draws inward, a brief contraction, a moment of stillness.","\n","^Brighter. Dimmer. Brighter. Dimmer.","\n","ev",{"VAR?":"has_ritual_knowledge"},"/ev",[{"->":".^.b","c":true},{"b":["^ Between the exhales. The pause. The contraction. That's when the containment can be restored. You count the rhythm. Four seconds of exhale. Two seconds of pause. Four seconds of exhale. Two seconds of pause. The window is small.",{"->":".^.^.^.22"},null]}],"nop","\n","^The bottom of the steps is close. You can see the chamber below. A cavern, natural, the stone walls curved and smooth. The amber light fills it, sourceless, emanating from the air itself. Or from something in the air. The portal.","\n","^And standing on the steps between you and the bottom, looking up at you:","\n","^Dale.","\n",{"->":".^.^.dale_confrontation"},{"#f":1}],"dale_confrontation":["^He's not wearing his polo shirt. Not holding his clipboard. Not smiling.","\n","^He's wearing a jumpsuit. Dark fabric, stiff, the cut wrong for modern clothing. The stitching is from another era. Something that belongs to the mine, not to the man wearing it.","\n","^He stands three steps below you. Close. The amber light pulses behind him, casting his shadow up the wall, long and warped.","\n","^\"I told you to stay in your lane, Val.\"","\n","ev",{"VAR?":"dale_suspicion"},6,">=","/ev",[{"->":".^.b","c":true},{"b":["^ ",{"->":"night_4.dale_adversarial"},{"->":".^.^.^.14"},null]}],"nop","\n","ev",{"VAR?":"dale_suspicion"},3,">=",{"VAR?":"dale_suspicion"},6,"<","&&","/ev",[{"->":".^.b","c":true},{"b":["^ ",{"->":"night_4.dale_offer"},{"->":".^.^.^.26"},null]}],"nop","\n","ev",{"VAR?":"dale_suspicion"},3,"<","/ev",[{"->":".^.b","c":true},{"b":["^ ",{"->":"night_4.dale_explanation"},{"->":".^.^.^.34"},null]}],"nop","\n",{"#f":1}],"dale_adversarial":[["^His voice is flat. Hard. The warmth, the enthusiasm, the performance of Dale-the-manager: gone. This is whatever Dale is underneath.","\n","^\"I gave you chances. More than most. I told you what mattered. I told you to stay in your zone, do your job, don't wander. Simple instructions.\"","\n","^He doesn't move. He doesn't need to. The stairwell is narrow. He fills it.","\n","^\"I moved you to perimeter. I moved you to different zones. I put obstacles in your path. Every time, you went around them. Every time, you came back to the tunnels. To the records. To the questions.\"","\n",["ev",{"^->":"night_4.dale_adversarial.0.8.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"What are you, Dale?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_4.dale_adversarial.0.9.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"You can't stop me.\"",{"->":"$r","var":true},null]}],"ev","str","^Say nothing.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["ev",{"^->":"night_4.dale_adversarial.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.8.s"},[{"#n":"$r2"}],"\n","^\"I'm the manager.\" He says it without irony. \"I manage this operation. I keep it running. I keep the system balanced. And you are unbalancing it.\"","\n",{"->":"night_4.dale_exhale"},{"#f":5}],"c-1":["ev",{"^->":"night_4.dale_adversarial.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.9.s"},[{"#n":"$r2"}],"\n","^\"I don't have to.\" He looks down, toward the portal. The glow pulses. \"It stops you.\"","\n",{"->":"night_4.dale_exhale"},{"#f":5}],"c-2":["\n","^Dale watches you. The amber light pulses between you. He sees that you're not going to argue, not going to explain, not going to justify.","\n","^\"Fine,\" he says quietly.","\n",{"->":"night_4.dale_exhale"},{"#f":5}]}],{"#f":1}],"dale_offer":[["^His voice is quiet. Not threatening. Something closer to disappointment.","\n","^\"You're a good worker, Val. You know that? Reliable. Focused. The guests respond to you. You've got the instinct for it.\"","\n","^He shifts on the step. The amber light catches his face and for a moment he looks older. Much older. The lines deeper, the skin thinner.","\n","^\"You could stay. That's what I'm offering. Not a threat. An opportunity. You could be part of this for a long time. Like Bex. Like the others.\"","\n",["ev",{"^->":"night_4.dale_offer.0.8.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","str","^\"","/str","/ev",{"*":".^.^.c-0","flg":22},{"s":["^\"Like Bex?",{"->":"$r","var":true},null]}],["ev",{"^->":"night_4.dale_offer.0.9.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"What does 'a long time' mean?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_4.dale_offer.0.10.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"No.\"",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"night_4.dale_offer.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.8.s"},[{"#n":"$r2"}],"^ Bex doesn't remember their own name.\"","\n","^Dale is quiet for a moment. \"Bex has been here a long time. Longer than most. The details fade. But the work doesn't. The purpose doesn't.\"","\n",{"->":"night_4.dale_exhale"},{"#f":5}],"c-1":["ev",{"^->":"night_4.dale_offer.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.9.s"},[{"#n":"$r2"}],"\n","^\"It means you don't have to worry about what comes after. The job takes care of you. The mine takes care of you. You'll always have a place here.\"","\n",{"->":"night_4.dale_exhale"},{"#f":5}],"c-2":["ev",{"^->":"night_4.dale_offer.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.10.s"},[{"#n":"$r2"}],"\n","^Dale nods. He expected that. \"They always say no. At first.\"","\n",{"->":"night_4.dale_exhale"},{"#f":5}]}],{"#f":1}],"dale_explanation":[["^His voice is calm. Almost gentle. He sits down on the step, which is the last thing you expected. He sits and he looks up at you and the amber light pulses behind him and he looks tired. Genuinely tired. For the first time since you've known him, Dale looks like a person who carries something heavy.","\n","^\"You're not the first,\" he says. \"You won't be the last. They always come down here eventually. The curious ones. The ones who ask questions. The ones who can't leave well enough alone.\"","\n","^He looks at the cavern below. The portal.","\n","^\"It doesn't close. I want you to understand that. It's been open for longer than the mine, longer than the town, longer than anything built on this land. It was here when the mountain was just rock and sagebrush. It'll be here when the mountain is gone.\"","\n",["ev",{"^->":"night_4.dale_explanation.0.8.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","str","^\"","/str","/ev",{"*":".^.^.c-0","flg":22},{"s":["^\"Then what's the point of all this?",{"->":"$r","var":true},null]}],["ev",{"^->":"night_4.dale_explanation.0.9.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"Who are you?\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_4.dale_explanation.0.10.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","str","^\"","/str","/ev",{"*":".^.^.c-2","flg":22},{"s":["^\"The people it's erased.",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"night_4.dale_explanation.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.8.s"},[{"#n":"$r2"}],"^ The Hollows? The show?\"","\n","^\"Management.\" He says it simply. \"What we built up there isn't a cage. It's a management system. We keep it fed so it doesn't feed itself.\" He pauses. \"The fear. The guests' fear. It's controlled. Measured. Enough to keep it satisfied without letting it reach out on its own. Without HorrorCo, the portal would take what it needs. Randomly. Violently. The whole town. Maybe more.\"","\n",{"->":"night_4.dale_exhale"},{"#f":5}],"c-1":["ev",{"^->":"night_4.dale_explanation.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.9.s"},[{"#n":"$r2"}],"\n","^\"I'm the manager.\" He says it without irony, without performance. \"Someone has to be. Someone has to make sure the system runs. That the balance holds. That the thing down there stays fed and doesn't get hungry.\"","\n",{"->":"night_4.dale_exhale"},{"#f":5}],"c-2":["ev",{"^->":"night_4.dale_explanation.0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.10.s"},[{"#n":"$r2"}],"^ Mara. The others.\"","\n","^Dale closes his eyes. \"Costs. I don't pretend otherwise. The system isn't clean. It isn't kind. But the alternative...\" He opens his eyes. Looks at you. \"The alternative is worse.\"","\n",{"->":"night_4.dale_exhale"},{"#f":5}]}],{"#f":1}],"dale_exhale":[["^The portal breathes.","\n","^You feel it before you see it. The pressure in the chamber shifts. The hum drops in pitch, so low it becomes a vibration in your organs, your lungs, the fluid in your eyes. The glow flares white at the edges, bleaching the stone walls pale, turning every mote of dust in the air into a bright point of light. The air temperature spikes, ten degrees in a second, twenty. Sweat breaks under the costume. The greasepaint on your knuckles softens, goes slick, starts to run.","\n","^The exhale.","\n","^It hits you from below. Your lungs flatten. Your inner ear lurches sideways. Not wind. A column of heat and particulate boiling up from the portal, thick as smoke but denser, hotter, carrying the copper-ozone smell ten times stronger and something new underneath it: sulfur. Sharp. Chemical. It hits the back of your throat and you gag. The force rolls through you the way a wave rolls through you if you're standing in the wrong place at the wrong time. You stagger backward. Your feet slip on the worn steps. You catch yourself on the wall. The stone is burning hot under your palm.","\n","^Dale doesn't move. The exhale passes through him like he isn't there. Or like he's part of it.","\n","^The force drives you up. One step. Two. Three. You brace yourself and it pushes you further. The mine groans. Dust falls from the ceiling. The smoke curls along the low points, pooling in the carved hollows of the walls. A crack opens in the stone beside you. Not amber in the fissure. White. Searing. The color of heated metal. It holds for a second. Two. Then it closes, and where it was the stone is dark and scorched, a hairline burn mark that smells like struck flint.","\n","ev",{"VAR?":"has_ritual_knowledge"},"/ev",[{"->":".^.b","c":true},{"b":["^ Two seconds. The pause between exhales is two seconds. You counted it from above. Now you feel it: the exhale lasts four seconds and the force is enormous. The pause is two seconds of stillness. Two seconds to act. Two seconds to carve a pattern that was meant to hold this shut.",{"->":".^.^.^.16"},null]}],"nop","\n","ev",{"VAR?":"has_ritual_knowledge"},"/ev",[{"->":".^.b","c":true},{"b":["^ It's not enough time. Not tonight. Not without preparation. Not without a plan.",{"->":".^.^.^.22"},null]}],"nop","\n","^The exhale fades. The pressure drops. The temperature settles.","\n","^Dale stands on the steps below you. The smoke drifts between you, thinning, lit from below. The sulfur smell is still thick in the air. He hasn't moved.","\n","^\"Tomorrow,\" he says. \"If you're still here tomorrow. It'll be over one way or another.\"","\n",["ev",{"^->":"night_4.dale_exhale.0.30.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^\"I'll be here.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"night_4.dale_exhale.0.31.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^\"What does that mean?\"",{"->":"$r","var":true},null]}],"ev","str","^Turn and climb.","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["ev",{"^->":"night_4.dale_exhale.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.30.s"},[{"#n":"$r2"}],"\n","^Dale nods. As if he expected nothing less. As if he's heard it before.","\n",{"->":"night_4.retreat"},{"#f":5}],"c-1":["ev",{"^->":"night_4.dale_exhale.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.31.s"},[{"#n":"$r2"}],"\n","^\"It means the system is reaching capacity. Tonight was manageable. Tomorrow won't be.\"","\n",{"->":"night_4.retreat"},{"#f":5}],"c-2":["\n",{"->":"night_4.retreat"},{"#f":5}]}],{"#f":1}],"retreat":["^You climb. Up the spiral steps, away from the amber light, away from the heat. The pressure eases as you ascend. The hum softens. The air cools.","\n","^Dale doesn't follow you.","\n","^Back through the deep rooms. You follow the cool air. You follow the fading hum. You climb.","\n","^Mid-level. The show is still running. You can hear it: the speakers, the sound effects, the screams. Above you, on the other side of plywood walls and painted foam, guests are still walking through the attraction. Still paying to be frightened. Still feeding the machine.","\n","^The mine doesn't care that you went down. The mine doesn't care that Dale stopped you. The show goes on.","\n","^You pass through the utility corridor, back into the set dressing, back into Zone 8. Your position in the wall is empty. Nobody noticed you were gone. The fog still pours. The animatronics still cycle. The hum is still there, under everything.","\n","^You work the last hour. Extend, retract. Guests scream. Guests laugh. One of them looks through you again, eyes sliding past like you're part of the wall.","\n","^The shift ends.","\n",{"->":".^.^.post_night_4"},{"#f":1}],"post_night_4":[["^You change out of costume. Scrub the greasepaint off. Your face is raw. The prosthetic gash left a red welt across your cheek that won't fade by morning. Your shoulder is locked from four hours in the wall. Your hands smell like copper.","\n","^The break room is quiet. A few actors filter through, tired, heading to their cars. Nobody talks to you. Not unfriendly. Just absent. Like you're not quite in the room.","\n","^You walk out of the building. The parking lot. The cold desert air hits the sweat on your neck and you shiver.","\n","^And the Figure is standing at the mine entrance.","\n","^Not inside. Outside. In the open air. Under the stars.","\n","^The burlap mask faces you. The faded base layer is motionless. No wind moves the fabric. The Figure stands at the threshold between the parking lot and the mine, between the world and whatever is underneath it.","\n","ev",{"VAR?":"mara_clues"},4,">=","/ev",[{"->":".^.b","c":true},{"b":["^ Mara. Standing at the mouth of the mine. Looking at you. Waiting.",{"->":".^.^.^.18"},null]}],"nop","\n","ev",{"VAR?":"mara_clues"},4,"<","/ev",[{"->":".^.b","c":true},{"b":["^ The Figure. Standing at the mouth of the mine.",{"->":".^.^.^.26"},null]}],"nop","\n","^It turns. Slowly. And walks into the mine. Not vanishing. Not flickering. Walking. One step at a time. Deliberately. The amber glow from inside catches the fabric as the Figure passes the threshold and descends.","\n","^It's leading you. It's showing the way. It's saying: come back.","\n","^You stand in the parking lot. The cold. The stars. The hum in the ground beneath your feet.","\n","^Tomorrow.","\n","^You walk to the motel. You don't look back at the mine. You don't need to. You know the way now. You know the path, the spiral steps, the cavern at the bottom. You know the rhythm. You know the heat, the pressure, the two-second window between breaths.","\n","^You know Dale is down there. You know what he is. You know what he believes.","\n","ev",{"VAR?":"bex_relationship"},5,">=","/ev",[{"->":".^.b","c":true},{"b":["^ You know Bex can't go with you. Not all the way. They faded at the last junction like a signal dying. Whatever happens at the portal, you'll be alone.",{"->":".^.^.^.46"},null]}],"nop","\n","ev",{"VAR?":"has_ritual_knowledge"},"/ev",[{"->":".^.b","c":true},{"b":["^ You know the containment pattern. The complete circuit. The lock. You've memorized it not in shorthand but in the shape of the lines, in the movement of your hands. Muscle memory. The one thing the erasure can't reach.",{"->":".^.^.^.52"},null]}],"nop","\n","ev",{"VAR?":"has_escape_route"},"/ev",[{"->":".^.b","c":true},{"b":["^ You know where Gloria's truck is. Behind the diner. Keys under the mat. The way out, if you need it. If you choose it.",{"->":".^.^.^.58"},null]}],"nop","\n","^Tomorrow night. One more shift. One more descent.","\n","^This time you're going all the way down.","\n","ev","str","^Day 5.","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n","done",{"#f":5}]}],{"#f":1}],"#f":1}],"global decl":["ev",false,{"VAR=":"bex_hum"},0,{"VAR=":"bex_relationship"},0,{"VAR=":"dale_suspicion"},false,{"VAR=":"employee_records_seen"},0,{"VAR=":"erasure_level"},false,{"VAR=":"day_1_gloria"},0,{"VAR=":"gloria_trust"},false,{"VAR=":"has_bex_file"},false,{"VAR=":"has_census_data"},false,{"VAR=":"has_dale_file"},false,{"VAR=":"has_escape_route"},false,{"VAR=":"has_gloria_testimony"},false,{"VAR=":"has_horrorco_filing"},false,{"VAR=":"has_mara_pages"},false,{"VAR=":"has_mara_recording"},false,{"VAR=":"has_notebook_page"},false,{"VAR=":"has_portal_mechanics"},false,{"VAR=":"has_ritual_knowledge"},false,{"VAR=":"has_sinkhole_history"},false,{"VAR=":"library_clerk_check"},0,{"VAR=":"mara_clues"},false,{"VAR=":"post_shift_2_tell_bex"},false,{"VAR=":"post_shift_2_keep_quiet"},"str","^","/str",{"VAR=":"priority"},1,{"VAR=":"silas_trust"},false,{"VAR=":"visited_restricted_passage"},false,{"VAR=":"visited_tunnels"},0,{"VAR=":"day_4_visits"},"/ev","end",null],"#f":1}],"listDefs":{}};